/* --- js/ui/difficulty-editor.js?v=role-diff-1 --- */
"use strict";

var DifficultyEditorUI = class DifficultyEditorUI {
    constructor() {
        this.visible = false;
        this.profileId = (typeof difficultyConfigManager !== 'undefined')
            ? difficultyConfigManager.current : 'normal';
        this.ensureOverlay();
    }

    ensureOverlay() {
        if (document.getElementById('difficultyEditorOverlay')) return;
        const overlay = document.createElement('div');
        overlay.id = 'difficultyEditorOverlay';
        overlay.className = 'difficulty-editor-overlay hidden';
        overlay.innerHTML = `
            <div class="difficulty-editor-panel">
                <header class="difficulty-editor-header">
                    <h2>COMBAT DIFFICULTY</h2>
                    <button type="button" class="de-close" id="deClose">×</button>
                </header>
                <div class="difficulty-editor-body">
                    <aside class="difficulty-editor-nav">
                        <div class="de-section-title">PRESET</div>
                        <div id="deProfiles"></div>
                        <div class="de-section-title">ENEMY AI</div>
                        <label class="de-select-label">FACTION
                            <select id="deFaction"></select>
                        </label>
                        <label class="de-select-label">SHIP TIER
                            <select id="deTier">
                                <option value="1">TIER 1</option>
                                <option value="2">TIER 2</option>
                                <option value="3">TIER 3</option>
                                <option value="4">TIER 4</option>
                            </select>
                        </label>
                    </aside>
                    <main class="difficulty-editor-controls" id="deControls"></main>
                </div>
                <footer class="difficulty-editor-footer">
                    <button type="button" class="pe-btn" id="deReset">RESET PRESET</button>
                    <button type="button" class="pe-btn pe-primary" id="deSave">SAVE</button>
                    <button type="button" class="pe-btn" id="deBack">BACK</button>
                </footer>
            </div>`;
        document.body.appendChild(overlay);
        overlay.querySelector('#deClose').addEventListener('click', () => this.hide());
        overlay.querySelector('#deBack').addEventListener('click', () => this.hide());
        overlay.querySelector('#deSave').addEventListener('click', () => this.save());
        overlay.querySelector('#deReset').addEventListener('click', () => this.reset());
        overlay.querySelector('#deFaction').addEventListener('change', () => this.renderAI());
        overlay.querySelector('#deTier').addEventListener('change', () => this.renderAI());
    }

    show() {
        this.ensureOverlay();
        this.visible = true;
        this._returnToSettings = !!(typeof startScreenManager !== 'undefined'
            && startScreenManager
            && (startScreenManager.showSettings
                || startScreenManager.overlayMode
                || startScreenManager.embeddedMode));
        if (typeof startScreenManager !== 'undefined' && startScreenManager) {
            if (startScreenManager.overlayMode) startScreenManager.hideOverlay();
            if (startScreenManager.embeddedMode) startScreenManager.hideEmbedded();
        }
        if (typeof settingsManager !== 'undefined' && settingsManager.hideSettings) {
            settingsManager.hideSettings();
        }
        const overlay = document.getElementById('difficultyEditorOverlay');
        if (overlay.parentNode !== document.body) document.body.appendChild(overlay);
        overlay.classList.remove('hidden');
        this.render();
    }

    hide() {
        this.visible = false;
        const overlay = document.getElementById('difficultyEditorOverlay');
        if (overlay) overlay.classList.add('hidden');
        if (this._returnToSettings && typeof startScreenManager !== 'undefined' && startScreenManager) {
            this._returnToSettings = false;
            startScreenManager.showSettings = true;
            startScreenManager.showCredits = false;
            if (startScreenManager.hasActiveProfile && startScreenManager.hasActiveProfile()
                && typeof homeStationUI !== 'undefined') {
                if (!homeStationUI.isVisible) {
                    homeStationUI.show({ skipPersist: true });
                }
                startScreenManager.show({ asOverlay: true, showSettings: true });
            } else {
                startScreenManager.show({ forceMenu: true });
            }
        }
    }

    makeSlider(label, key, min, max, step, value, onInput) {
        const row = document.createElement('div');
        row.className = 'de-slider-row';
        const title = document.createElement('label');
        title.textContent = label;
        const output = document.createElement('output');
        output.textContent = Number(value).toFixed(step < 1 ? 2 : 0);
        const input = document.createElement('input');
        input.type = 'range';
        input.min = min;
        input.max = max;
        input.step = step;
        input.value = value;
        input.dataset.key = key;
        input.addEventListener('input', () => {
            output.textContent = Number(input.value).toFixed(step < 1 ? 2 : 0);
            onInput(Number(input.value));
        });
        row.append(title, input, output);
        return row;
    }

    appendSection(root, title, fields, profile) {
        const h = document.createElement('h3');
        h.textContent = title;
        root.appendChild(h);
        fields.forEach(([label, key, min, max, step]) => {
            const val = profile[key] != null ? profile[key] : 1;
            root.appendChild(this.makeSlider(label, key, min, max, step, val, (value) => {
                profile[key] = value;
            }));
        });
    }

    render() {
        const manager = window.difficultyConfigManager;
        if (!manager) return;
        const profiles = document.getElementById('deProfiles');
        profiles.innerHTML = '';
        Object.keys(manager.profiles).forEach((id) => {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'de-profile-btn' + (id === this.profileId ? ' active' : '');
            button.textContent = id.toUpperCase();
            button.addEventListener('click', () => {
                this.profileId = id;
                this.render();
            });
            profiles.appendChild(button);
        });
        const faction = document.getElementById('deFaction');
        faction.innerHTML = Object.keys(manager.factionProfiles)
            .map((id) => `<option value="${id}">${id.toUpperCase()}</option>`).join('');
        this.renderProfile();
        this.renderAI();
    }

    renderProfile() {
        const root = document.getElementById('deControls');
        const profile = window.difficultyConfigManager.getProfile(this.profileId);
        root.innerHTML = '';
        this.appendSection(root, 'GLOBAL COMBAT VALUES', [
            ['Enemy damage', 'enemyDamageMul', 0, 3, 0.05],
            ['Player damage', 'playerDamageMul', 0, 3, 0.05],
            ['Enemy health', 'enemyHealthMul', 0.25, 4, 0.05],
            ['Enemy speed', 'enemySpeedMul', 0.25, 3, 0.05],
            ['Number of enemies', 'enemyCountMul', 0.25, 3, 0.05],
            ['Max active enemies', 'enemyMaxActive', 1, 10, 1],
            ['Obstacle frequency', 'obstacleSpawnMul', 0.25, 3, 0.05]
        ], profile);
        this.appendSection(root, 'CHAMPION', [
            ['Damage', 'championDamageMul', 0.25, 3, 0.05],
            ['Health', 'championHealthMul', 0.25, 4, 0.05],
            ['Speed', 'championSpeedMul', 0.25, 3, 0.05],
            ['Evasion', 'championEvasionMul', 0.25, 3, 0.05]
        ], profile);
        this.appendSection(root, 'SIDE ENEMIES', [
            ['Damage', 'sideDamageMul', 0.25, 3, 0.05],
            ['Health', 'sideHealthMul', 0.25, 4, 0.05],
            ['Speed', 'sideSpeedMul', 0.25, 3, 0.05],
            ['Count', 'sideCountMul', 0.25, 3, 0.05]
        ], profile);
        this.appendSection(root, 'BOSS', [
            ['Damage', 'bossDamageMul', 0.25, 3, 0.05],
            ['Health', 'bossHealthMul', 0.25, 4, 0.05],
            ['Speed', 'bossSpeedMul', 0.25, 3, 0.05],
            ['Attack rate', 'bossAttackRateMul', 0.25, 3, 0.05]
        ], profile);
        root.dataset.profile = this.profileId;
        root._profileDraft = profile;
    }

    renderAI() {
        const manager = window.difficultyConfigManager;
        const faction = document.getElementById('deFaction').value;
        const tier = document.getElementById('deTier').value;
        const cfg = manager.factionProfiles[faction];
        const tierCfg = manager.tierProfiles[tier];
        const root = document.getElementById('deControls');
        const old = root.querySelector('.de-ai-controls');
        if (old) old.remove();
        const aiRoot = document.createElement('section');
        aiRoot.className = 'de-ai-controls';
        const heading = document.createElement('h3');
        heading.textContent = `${faction.toUpperCase()} — TIER ${tier} AI`;
        aiRoot.appendChild(heading);
        [['Evasion', 'evasion'], ['Prediction', 'prediction'], ['Damage', 'damage']]
            .forEach(([label, key]) => {
                aiRoot.appendChild(this.makeSlider(label, key, 0, 3, 0.05, (cfg[key] || 1) * (tierCfg[key] || 1), (value) => {
                    cfg[key] = value / (tierCfg[key] || 1);
                }));
            });
        // Show this faction's boss kit so designers see the weapon + doctrine split.
        const kit = manager.getBossWeaponKit ? manager.getBossWeaponKit(faction) : null;
        const beh = manager.getBossBehaviorKit ? manager.getBossBehaviorKit(faction) : null;
        if (kit) {
            const note = document.createElement('p');
            note.className = 'de-kit-note';
            const seq = beh && beh.patterns ? beh.patterns.join(' → ') : 'fan → aimed → sweep';
            const style = beh && beh.style ? beh.style : '?';
            note.textContent = `Boss kit — ${style} · fan: ${kit.fan} · aimed: ${kit.aimed} · sweep: ${kit.sweep} · ${seq}`;
            aiRoot.appendChild(note);
        }
        root.appendChild(aiRoot);
    }

    save() {
        const root = document.getElementById('deControls');
        const draft = root._profileDraft;
        if (draft) window.difficultyConfigManager.setProfile(this.profileId, draft);
        window.difficultyConfigManager.setDifficulty(this.profileId);
        if (typeof settingsManager !== 'undefined') {
            settingsManager.settings.difficulty = this.profileId;
            settingsManager.applyDifficultySettings();
            settingsManager.updateSettingsDisplay();
        }
        if (typeof startScreenManager !== 'undefined' && startScreenManager.settingsItems) {
            const difficultyItem = startScreenManager.settingsItems.find((item) => item.name === 'Difficulty');
            if (difficultyItem) {
                difficultyItem.value = String(this.profileId || 'normal').toUpperCase();
            }
        }
        this.hide();
    }

    reset() {
        window.difficultyConfigManager.resetProfile(this.profileId);
        this.render();
    }
}

var difficultyEditorUI = new DifficultyEditorUI();
window.difficultyEditorUI = difficultyEditorUI;


/* --- js/ui/faction-command.js --- */
"use strict";

var FactionCommandUI = class FactionCommandUI {
    constructor() {
        this.visible = false;
        this.selected = (typeof factionManager !== 'undefined' && factionManager.getAllegiance())
            || 'terran';
    }

    show() {
        if (this.visible) return;
        this.visible = true;
        this._returnToSettings = !!(typeof startScreenManager !== 'undefined'
            && startScreenManager
            && (startScreenManager.showSettings
                || startScreenManager.overlayMode
                || startScreenManager.embeddedMode));
        if (typeof startScreenManager !== 'undefined' && startScreenManager) {
            if (startScreenManager.overlayMode) startScreenManager.hideOverlay();
            if (startScreenManager.embeddedMode) startScreenManager.hideEmbedded();
        }
        if (typeof settingsManager !== 'undefined' && settingsManager.hideSettings) {
            settingsManager.hideSettings();
        }
        this.render();
    }

    hide() {
        this.visible = false;
        const el = document.getElementById('factionCommandOverlay');
        if (el) el.remove();
        if (this._returnToSettings && typeof startScreenManager !== 'undefined' && startScreenManager) {
            this._returnToSettings = false;
            startScreenManager.showSettings = true;
            startScreenManager.showCredits = false;
            if (startScreenManager.hasActiveProfile && startScreenManager.hasActiveProfile()
                && typeof homeStationUI !== 'undefined') {
                if (!homeStationUI.isVisible) {
                    homeStationUI.show({ skipPersist: true });
                }
                startScreenManager.show({ asOverlay: true, showSettings: true });
            } else {
                startScreenManager.show({ forceMenu: true });
            }
        }
    }

    render() {
        const fm = window.factionManager;
        if (!fm) return;
        const existing = document.getElementById('factionCommandOverlay');
        if (existing) existing.remove();
        const faction = fm.getFaction(this.selected);
        const factionColor = (typeof factionShipStyles !== 'undefined' && factionShipStyles.getFactionColor)
            ? factionShipStyles.getFactionColor(this.selected)
            : ((typeof planetConfigManager !== 'undefined' && planetConfigManager.getFactionPlanetTheme)
                ? (planetConfigManager.getFactionPlanetTheme(this.selected) || {}).baseColor
                : null);
        const overlay = document.createElement('div');
        overlay.id = 'factionCommandOverlay';
        overlay.className = 'faction-command-overlay';
        if (factionColor) overlay.style.setProperty('--fc-selected-color', factionColor);
        overlay.innerHTML = `
            <div class="faction-command-panel">
                <header class="faction-command-header">
                    <h2>FACTION COMMAND</h2>
                    <button type="button" class="de-close" id="fcClose">×</button>
                </header>
                <div class="faction-command-grid">
                    <aside class="faction-command-list">
                        <h3>ALLEGIANCE</h3>
                        ${fm.getFactionIds().map((id) => {
                            const color = (typeof factionShipStyles !== 'undefined' && factionShipStyles.getFactionColor)
                                ? factionShipStyles.getFactionColor(id)
                                : ((typeof planetConfigManager !== 'undefined' && planetConfigManager.getFactionPlanetTheme)
                                    ? (planetConfigManager.getFactionPlanetTheme(id) || {}).baseColor
                                    : null);
                            const style = color
                                ? `style="--fc-faction-color:${color};border-color:${color};color:${color}"`
                                : '';
                            return `
                            <button type="button" class="fc-faction ${id === this.selected ? 'active' : ''}" data-faction="${id}" ${style}>
                                ${fm.getFaction(id).label}
                            </button>`;
                        }).join('')}
                    </aside>
                    <main class="faction-command-detail">
                        <h1>${faction.label || this.selected.toUpperCase()}</h1>
                        <p class="fc-lore">${faction.loreLong || faction.lore || ''}</p>
                        <h3>FACTION GOAL</h3>
                        <p>${faction.goal || ''}</p>
                        <h3>OBJECTIVES</h3>
                        <ul>${(faction.objectives || []).map((x) => `<li>${x}</li>`).join('')}</ul>
                        <h3>TERRITORY</h3>
                        <p>${fm.getControlledPlanets().length} planets controlled</p>
                        <div class="fc-actions">
                            <button type="button" class="pe-btn pe-primary" id="fcJoin">
                                ${fm.getAllegiance() === this.selected ? 'ALIGNED' : 'JOIN FACTION'}
                            </button>
                        </div>
                        <h3>PACT NETWORK</h3>
                        <div class="fc-pacts">
                            ${fm.getFactionIds().filter((id) => id !== this.selected).map((id) => `
                                <button type="button" class="pe-btn fc-pact ${fm.hasPact(id) ? 'active' : ''}" data-pact="${id}">
                                    ${fm.getFaction(id).label}: ${fm.hasPact(id) ? 'PACT ACTIVE' : 'PROPOSE PACT'}
                                </button>`).join('')}
                        </div>
                    </main>
                </div>
                <footer class="difficulty-editor-footer">
                    <button type="button" class="pe-btn" id="fcBack">BACK</button>
                </footer>
            </div>`;
        document.body.appendChild(overlay);
        overlay.querySelector('#fcClose').addEventListener('click', () => this.hide());
        overlay.querySelector('#fcBack').addEventListener('click', () => this.hide());
        overlay.querySelector('#fcJoin').addEventListener('click', () => {
            fm.join(this.selected);
            this.render();
        });
        overlay.querySelectorAll('[data-faction]').forEach((button) => {
            button.addEventListener('click', () => {
                this.selected = button.dataset.faction;
                this.render();
            });
        });
        overlay.querySelectorAll('[data-pact]').forEach((button) => {
            button.addEventListener('click', () => {
                if (fm.getAllegiance() === this.selected) fm.togglePact(button.dataset.pact);
                this.render();
            });
        });
    }
}

var factionCommandUI = new FactionCommandUI();
window.factionCommandUI = factionCommandUI;


/* --- js/ui/planet-viewer/core.js --- */
"use strict";

/**
 * Planet Viewer — browse planets by galaxy/system; open Planet Editor from here.
 * Open: Start menu → PLANETS, Pause → PLANETS
 */
var PlanetViewerUI = class PlanetViewerUI {
    constructor() {
        this.visible = false;
        this.selectedIndex = 0;
        this.planets = [];
        this.systems = [];
        this.overlay = null;
        this.previewCanvas = null;
        this.previewCtx = null;
        this.previewAnimId = null;
        this.previewZoom = 1;
        this.previewFullscreen = false;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewPanning = false;
        this.previewPanLastX = 0;
        this.previewPanLastY = 0;
        this.previewObstacles = [];
        this.previewObstacleSpawnAcc = 0;
        this._previewCfgId = null;
        this._keyHandler = (e) => this.handleKeyDown(e);
    }

    getPlanetData(id) {
        if (typeof planetConfigManager === 'undefined') {
            return {
                id: id,
                name: String(id).toUpperCase(),
                difficulty: '',
                description: '',
                galaxy: '',
                galaxyId: '',
                enemyCount: 0,
                layerCount: 0,
                stages: []
            };
        }
        const cfg = planetConfigManager.getConfig(id);
        const gid = planetConfigManager.getPlanetGalaxyId(id);
        const galaxy = planetConfigManager.getGalaxy(gid);
        const stages = cfg && cfg.stages
            ? Object.keys(cfg.stages).map((key) => {
                const stage = cfg.stages[key] || {};
                const enemies = Array.isArray(stage.enemies) ? stage.enemies.length : 0;
                return { key: key, enemies: enemies };
            })
            : [];
        return {
            id: id,
            name: (cfg && cfg.name) || id.toUpperCase(),
            difficulty: (cfg && cfg.difficulty) || '',
            description: (cfg && cfg.description) || '',
            galaxy: galaxy ? galaxy.name : '',
            galaxyId: gid || '',
            factions: (cfg && Array.isArray(cfg.factions)) ? cfg.factions.slice() : [],
            enemyCount: (cfg && cfg.enemies && cfg.enemies.length) || 0,
            layerCount: (cfg && cfg.backgroundLayers && cfg.backgroundLayers.length) || 0,
            stages: stages
        };
    }

    getSelectedConfig() {
        const p = this.planets[this.selectedIndex];
        if (!p || typeof planetConfigManager === 'undefined') return null;
        return planetConfigManager.getConfig(p.id) || null;
    }

    isPlanetVisible(galaxyId, planetId) {
        if (typeof startScreenManager !== 'undefined' && startScreenManager.devMode) {
            return true;
        }
        if (typeof profileManager === 'undefined' || !profileManager.getActiveProfile()) {
            return true;
        }
        const gid = galaxyId || (typeof planetConfigManager !== 'undefined'
            ? planetConfigManager.getPlanetGalaxyId(planetId)
            : null);
        if (!gid) return true;
        return profileManager.isPlanetUnlocked(gid, planetId)
            || profileManager.isPlanetCleared(gid, planetId);
    }

    buildSystems() {
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.getGalaxyTree) {
            const tree = planetConfigManager.getGalaxyTree();
            this.systems = tree.map((g) => ({
                id: g.id,
                name: g.name,
                planets: (g.planets || [])
                    .filter((p) => this.isPlanetVisible(g.id, p.id))
                    .map((p) => this.getPlanetData(p.id))
            })).filter((sys) => sys.planets.length > 0);
        } else {
            const ids = ['mars', 'jupiter', 'saturn', 'neptune', 'pluto'];
            this.systems = [{
                id: 'milky_way',
                name: 'MILKY WAY',
                planets: ids
                    .filter((id) => this.isPlanetVisible('milky_way', id))
                    .map((id) => this.getPlanetData(id))
            }].filter((sys) => sys.planets.length > 0);
        }
        this.planets = [];
        this.systems.forEach((sys) => {
            sys.planets.forEach((p) => this.planets.push(p));
        });
    }

    /** Static icon (list rows): many can be on screen at once, so no spin cost. */
    planetIconHtmlStatic(planetId, size) {
        const sid = String(planetId || 'mars').toLowerCase();
        const px = size || 32;
        if (typeof planetSVGManager !== 'undefined') {
            if (!planetSVGManager.planets || !Object.keys(planetSVGManager.planets).length) {
                planetSVGManager.init();
            }
            let svg = planetSVGManager.getPlanetSVG(sid);
            if (svg) {
                const uid = 'pv_' + sid + '_' + Math.random().toString(36).slice(2, 7);
                svg = svg
                    .replace(/id="([^"]+)"/g, (m, id) => `id="${uid}_${id}"`)
                    .replace(/url\(#([^)]+)\)/g, (m, id) => `url(#${uid}_${id})`)
                    .replace(/width="\d+"/, `width="${px}"`)
                    .replace(/height="\d+"/, `height="${px}"`);
                return `<span class="cv-icon cv-planet-icon">${svg}</span>`;
            }
        }
        return `<span class="cv-icon cv-planet-fallback" data-planet="${sid}" style="width:${px}px;height:${px}px"></span>`;
    }

    /** Animated hero icon (one at a time, the selected-planet detail view). */
    planetIconHtml(planetId, size) {
        const sid = String(planetId || 'mars').toLowerCase();
        const px = size || 32;
        // Shared spin pipeline (js/graphics/planet-svgs/spin-frames.js) so the
        // preview's lava/clouds/bands turn like everywhere else, instead of a
        // once-baked static SVG. Reserved for the single big detail icon —
        // the "featured" bucket in startPlanetSpin's round-robin repaints
        // every tick, so it must stay a handful of icons, not a whole list.
        if (typeof galaxyMapManager !== 'undefined' && galaxyMapManager.planetIconHtml) {
            const html = galaxyMapManager.planetIconHtml(sid, px, true);
            if (html) {
                // The wrapper span needs an explicit pixel box: outside the galaxy
                // map's SVG/flex frame it sits in a plain flex row with no height,
                // so its 100%-height CSS collapses to 0px. That makes the spin
                // timer's getBoundingClientRect visibility check treat it as
                // off-screen forever after the first paint, freezing the planet.
                return html
                    .replace('gm-planet-icon', 'gm-planet-icon cv-icon cv-planet-icon')
                    .replace('class="gm-planet-icon', `style="width:${px}px;height:${px}px" class="gm-planet-icon`);
            }
        }
        if (typeof planetSVGManager !== 'undefined') {
            if (!planetSVGManager.planets || !Object.keys(planetSVGManager.planets).length) {
                planetSVGManager.init();
            }
            let svg = planetSVGManager.getPlanetSVG(sid);
            if (svg) {
                const uid = 'pv_' + sid + '_' + Math.random().toString(36).slice(2, 7);
                svg = svg
                    .replace(/id="([^"]+)"/g, (m, id) => `id="${uid}_${id}"`)
                    .replace(/url\(#([^)]+)\)/g, (m, id) => `url(#${uid}_${id})`)
                    .replace(/width="\d+"/, `width="${px}"`)
                    .replace(/height="\d+"/, `height="${px}"`);
                return `<span class="cv-icon cv-planet-icon">${svg}</span>`;
            }
        }
        return `<span class="cv-icon cv-planet-fallback" data-planet="${sid}" style="width:${px}px;height:${px}px"></span>`;
    }

    show(options) {
        if (options && Object.prototype.hasOwnProperty.call(options, 'onClose')) {
            this.onClose = options.onClose;
        }
        this.buildSystems();
        if (!this.planets.length) return;
        const preferId = options && options.planetId;
        if (preferId) {
            const idx = this.planets.findIndex((p) => p.id === preferId);
            if (idx >= 0) this.selectedIndex = idx;
        }
        this.selectedIndex = Math.max(0, Math.min(this.selectedIndex, this.planets.length - 1));
        this.visible = true;
        this.createUI();
        document.addEventListener('keydown', this._keyHandler);
        if (!(options && options.skipPersist) && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('planet-viewer', {
                planet: this.planets[this.selectedIndex].id
            });
        }
    }

    hide() {
        this.visible = false;
        this.stopPreview();
        this.cleanupPreviewControls();
        this.setPreviewFullscreen(false);
        document.removeEventListener('keydown', this._keyHandler);
        if (this._panelResize) {
            this._panelResize.destroy();
            this._panelResize = null;
        }
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
        this.previewCanvas = null;
        this.previewCtx = null;
    }

    createUI() {
        if (this._panelResize) {
            this._panelResize.destroy();
            this._panelResize = null;
        }
        if (this.overlay) this.overlay.remove();

        this.overlay = document.createElement('div');
        this.overlay.className = 'content-viewer-overlay';
        this.overlay.innerHTML = `
            <div class="content-viewer-panel">
                <h2 class="content-viewer-title">PLANETS</h2>
                <div class="content-viewer-body has-preview" id="pvViewerBody">
                    <aside class="content-viewer-list" id="pvList"></aside>
                    <div class="pe-resize-handle" data-resize="left" title="Resize planet list"></div>
                    <div class="content-viewer-detail" id="pvDetail"></div>
                    <div class="pe-resize-handle" data-resize="right" title="Resize preview"></div>
                    <aside class="content-viewer-preview planet-editor-preview-wrap" id="pvPreviewWrap">
                        <div class="pe-preview-toolbar">
                            <button type="button" class="pe-btn pe-preview-btn" id="pvZoomOut" title="Zoom out">−</button>
                            <span class="pe-zoom-label" id="pvZoomLabel">100%</span>
                            <button type="button" class="pe-btn pe-preview-btn" id="pvZoomIn" title="Zoom in">+</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="pvZoomReset" title="Reset zoom">1:1</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="pvPreviewFullscreen" title="Fullscreen">FULL</button>
                        </div>
                        <div class="pe-preview-viewport" id="pvPreviewViewport">
                            <canvas id="pvPreview" width="240" height="300"></canvas>
                        </div>
                        <div class="pe-preview-label">PREVIEW</div>
                    </aside>
                </div>
                <div class="content-viewer-footer">
                    <button type="button" class="pe-btn pe-primary" id="pvEdit">EDIT</button>
                    <button type="button" class="pe-btn" id="pvClose">CLOSE</button>
                </div>
                <div class="content-viewer-hint">↑↓ Navigate • E Edit • ESC Close</div>
            </div>
        `;
        document.body.appendChild(this.overlay);
        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }

        this.bindPreviewControls();
        this.setupPanelResize();
        this.renderList();
        this.renderDetail();
        this.startPreview();

        this.overlay.querySelector('#pvEdit').addEventListener('click', () => this.openEditor());
        this.overlay.querySelector('#pvClose').addEventListener('click', () => this.close());
        this.mountDevToggles();
    }

    planetProgressFlags(planet) {
        if (!planet || typeof profileManager === 'undefined') {
            return { known: false, visited: false, cleared: false };
        }
        const gid = planet.galaxyId || (typeof planetConfigManager !== 'undefined'
            ? planetConfigManager.getPlanetGalaxyId(planet.id)
            : null);
        return {
            known: profileManager.isDiscovered('planets', planet.id),
            visited: !!(gid && (profileManager.isPlanetUnlocked(gid, planet.id)
                || profileManager.isPlanetCleared(gid, planet.id))),
            cleared: !!(gid && profileManager.isPlanetCleared(gid, planet.id))
        };
    }
}


/* --- js/ui/planet-viewer/mount-dev-toggles.js --- */
"use strict";

// PlanetViewerUI methods, split from planet-viewer.js.
extendClass(PlanetViewerUI, {
    mountDevToggles() {
        this._devToggles = null;
        if (typeof devProfileToggles === 'undefined' || !devProfileToggles.active()) return;
        const footer = this.overlay.querySelector('.content-viewer-footer');
        const hint = this.overlay.querySelector('.content-viewer-hint');
        this._devToggles = devProfileToggles.mount(footer, hint, {
            known: () => {
                const p = this.planets[this.selectedIndex];
                return !!(p && profileManager.isDiscovered('planets', p.id));
            },
            toggleKnown: () => {
                const p = this.planets[this.selectedIndex];
                if (p) profileManager.toggleDiscovered('planets', p.id);
            },
            visited: () => {
                const p = this.planets[this.selectedIndex];
                return !!(p && this.planetProgressFlags(p).visited);
            },
            toggleVisited: () => {
                const p = this.planets[this.selectedIndex];
                if (p) profileManager.togglePlanetVisited(p.id);
            },
            cleared: () => {
                const p = this.planets[this.selectedIndex];
                return !!(p && this.planetProgressFlags(p).cleared);
            },
            toggleCleared: () => {
                const p = this.planets[this.selectedIndex];
                if (p) profileManager.togglePlanetCleared(p.id);
            },
            onChange: () => {
                this.renderList();
                this.renderDetail();
                if (this._devToggles) this._devToggles.refresh();
            }
        });
    },

    setupPanelResize() {
        const body = this.overlay && this.overlay.querySelector('#pvViewerBody');
        if (!body || typeof setupPanelResize !== 'function') return;
        this._panelResize = setupPanelResize({
            body,
            root: this.overlay,
            storageKey: 'pvPanelWidths',
            defaults: { left: 220, right: 260 },
            mins: { left: 140, right: 180, center: 200 },
            leftVar: '--cv-left-w',
            rightVar: '--cv-right-w',
            onChange: () => {
                if (this.visible) this.applyPreviewView();
            }
        });
    },

    bindPreviewControls() {
        const overlay = this.overlay;
        this.previewCanvas = overlay.querySelector('#pvPreview');
        this.previewCtx = this.previewCanvas.getContext('2d');
        this.previewZoom = 1;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewFullscreen = false;

        overlay.querySelector('#pvZoomOut').addEventListener('click', () => this.setPreviewZoom(this.previewZoom - 0.25));
        overlay.querySelector('#pvZoomIn').addEventListener('click', () => this.setPreviewZoom(this.previewZoom + 0.25));
        overlay.querySelector('#pvZoomReset').addEventListener('click', () => {
            this.previewPanX = 0;
            this.previewPanY = 0;
            this.setPreviewZoom(1);
        });
        overlay.querySelector('#pvPreviewFullscreen').addEventListener('click', () => {
            this.setPreviewFullscreen(!this.previewFullscreen);
        });

        const viewport = overlay.querySelector('#pvPreviewViewport');
        viewport.addEventListener('wheel', (e) => {
            e.preventDefault();
            this.setPreviewZoom(this.previewZoom + (e.deltaY < 0 ? 0.1 : -0.1));
        }, { passive: false });
        viewport.addEventListener('contextmenu', (e) => e.preventDefault());
        viewport.addEventListener('mousedown', (e) => {
            if (e.button !== 2) return;
            e.preventDefault();
            this.previewPanning = true;
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            viewport.classList.add('pe-panning');
        });
        const onMove = (e) => {
            if (!this.previewPanning || !this.visible) return;
            this.previewPanX += vfPanDelta(this.previewCanvas, e.clientX - this.previewPanLastX);
            this.previewPanY += vfPanDelta(this.previewCanvas, e.clientY - this.previewPanLastY);
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            this.applyPreviewView();
        };
        const endPan = () => {
            if (!this.previewPanning) return;
            this.previewPanning = false;
            const vp = this.overlay && this.overlay.querySelector('#pvPreviewViewport');
            if (vp) vp.classList.remove('pe-panning');
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', endPan);
        this._previewCleanup = () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', endPan);
        };
        this.applyPreviewView();
        requestAnimationFrame(() => this.applyPreviewView());
    },

    setPreviewZoom(zoom) {
        this.previewZoom = Math.min(4, Math.max(0.5, Math.round(zoom * 100) / 100));
        this.applyPreviewView();
    },

    setPreviewFullscreen(on) {
        this.previewFullscreen = !!on;
        requestAnimationFrame(() => this.applyPreviewView());
    },

    applyPreviewView() {
        const wrap = this.overlay && this.overlay.querySelector('#pvPreviewWrap');
        const label = this.overlay && this.overlay.querySelector('#pvZoomLabel');
        const fsBtn = this.overlay && this.overlay.querySelector('#pvPreviewFullscreen');
        const viewport = this.overlay && this.overlay.querySelector('#pvPreviewViewport');
        if (wrap) wrap.classList.toggle('pe-preview-fs', this.previewFullscreen);
        if (label) label.textContent = `${Math.round(this.previewZoom * 100)}%`;
        if (fsBtn) fsBtn.textContent = this.previewFullscreen ? 'EXIT' : 'FULL';
        if (this.previewCanvas && viewport) {
            const pad = 8;
            const availW = Math.max(140, viewport.clientWidth - pad);
            const availH = Math.max(200, viewport.clientHeight - pad);
            const aspect = this.previewCanvas.width / this.previewCanvas.height || 0.8;
            let fitW = availW;
            let fitH = fitW / aspect;
            if (fitH > availH) {
                fitH = availH;
                fitW = fitH * aspect;
            }
            this.previewCanvas.style.width = `${Math.round(fitW)}px`;
            this.previewCanvas.style.height = `${Math.round(fitH)}px`;
            this.previewCanvas.style.transform =
                `translate(${this.previewPanX}px, ${this.previewPanY}px) scale(${this.previewZoom})`;
        }
    },

    startPreview() {
        this.stopPreview();
        if (this.previewCanvas) {
            this.previewCanvas.width = 240;
            this.previewCanvas.height = 300;
            this.previewCtx = this.previewCanvas.getContext('2d');
        }
        this.previewObstacles = [];
        this.previewObstacleSpawnAcc = 0;
        this._previewCfgId = null;
        let lastTs = 0;
        const tick = (ts) => {
            if (!this.visible) return;
            if (!lastTs) lastTs = ts;
            const dt = Math.min(50, ts - lastTs);
            lastTs = ts;
            this.updatePreviewObstacles(dt);
            this.drawPreview();
            this.previewAnimId = requestAnimationFrame(tick);
        };
        this.previewAnimId = requestAnimationFrame(tick);
    },

    stopPreview() {
        if (this.previewAnimId) {
            cancelAnimationFrame(this.previewAnimId);
            this.previewAnimId = null;
        }
        this.previewObstacles = [];
        this.previewObstacleSpawnAcc = 0;
    },

    cleanupPreviewControls() {
        if (this._previewCleanup) {
            this._previewCleanup();
            this._previewCleanup = null;
        }
    },

    drawPreview() {
        if (!this.previewCtx || !this.previewCanvas) return;
        const ctx = this.previewCtx;
        const w = this.previewCanvas.width;
        const h = this.previewCanvas.height;
        const cfg = this.getSelectedConfig();
        const bg = getComputedStyle(document.documentElement).getPropertyValue('--current-background').trim() || '#0a0a0a';
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, w, h);

        if (!cfg) {
            ctx.fillStyle = '#888';
            ctx.font = '11px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('NO DATA', w / 2, h / 2);
            return;
        }

        const t = performance.now() / 1000;
        const canDraw = typeof parallaxManager !== 'undefined' && parallaxManager.drawLayerPattern;
        const layers = cfg.backgroundLayers || [];

        layers.forEach((layer) => {
            if (layer.visible === false) return;
            const opacity = layer.opacity != null ? layer.opacity : 0.15;
            if (opacity <= 0) return;

            let color = '#808080';
            if (typeof planetConfigManager !== 'undefined') {
                color = planetConfigManager.resolveLayerColor(layer);
            }

            ctx.save();
            ctx.globalAlpha = opacity;
            if (canDraw) {
                const speed = layer.speed || 0.3;
                const fakeLayer = {
                    pattern: layer.pattern,
                    y: (t * speed * 40) % 600,
                    color,
                    colorSource: 'custom',
                    opacity: 1,
                    scale: layer.scale != null ? layer.scale : 1,
                    visible: true
                };
                parallaxManager.drawLayerPattern(ctx, fakeLayer, 0);
            } else {
                ctx.fillStyle = color;
                const speed = layer.speed || 0.3;
                const offset = (t * speed * 40) % 40;
                const step = layer.pattern && layer.pattern.includes('sky') ? 16 : 10;
                for (let x = 0; x < w; x += step) {
                    for (let y = -40; y < h + 40; y += step) {
                        if (((Math.floor(x / step) + Math.floor((y + offset) / step)) % 3) === 0) {
                            ctx.fillRect(x, Math.floor(y + offset) % h, 3, 3);
                        }
                    }
                }
            }
            ctx.restore();
        });

        this.drawObstaclePreviews(ctx);
        this.drawSideEnemyPreviews(ctx, w, h, cfg.enemies || cfg.sideEnemies || []);

        const p = this.planets[this.selectedIndex];
        ctx.globalAlpha = 1;
        ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--current-text').trim() || '#e8a040';
        ctx.font = '10px monospace';
        ctx.textAlign = 'left';
        ctx.fillText((p && p.name) || 'PLANET', 8, 14);
    },
});


/* --- js/ui/planet-viewer/update-preview-obstacles.js --- */
"use strict";

// PlanetViewerUI methods, split from planet-viewer.js.
extendClass(PlanetViewerUI, {
    updatePreviewObstacles(dtMs) {
        if (!this.previewCanvas) return;
        const cfg = this.getSelectedConfig();
        const defs = (cfg && cfg.obstacles) || [];
        const cfgId = cfg && cfg.id;
        if (cfgId !== this._previewCfgId) {
            this._previewCfgId = cfgId;
            this.previewObstacles = [];
            this.previewObstacleSpawnAcc = 0;
        }
        if (!defs.length) {
            this.previewObstacles = [];
            return;
        }
        const w = this.previewCanvas.width;
        const h = this.previewCanvas.height;
        const frames = dtMs / 16.67;
        const interval = Math.max(400, (cfg && cfg.obstacleSpawnRate) || 2000);
        this.previewObstacleSpawnAcc += dtMs;
        while (this.previewObstacleSpawnAcc >= interval) {
            this.previewObstacleSpawnAcc -= interval;
            this.spawnPreviewObstacle(defs, w, h);
        }
        if (this.previewObstacles.length === 0) {
            for (let i = 0; i < Math.min(3, defs.length); i++) {
                this.spawnPreviewObstacle(defs, w, h);
                const o = this.previewObstacles[this.previewObstacles.length - 1];
                if (o) o.x = Math.random() * w * 0.7;
            }
        }
        const margin = 40;
        this.previewObstacles = this.previewObstacles.filter((o) => {
            o.x += o.horizontalSpeed * frames;
            o.y += o.verticalSpeed * frames;
            return o.x < w + margin && o.y < h + margin && o.x > -margin && o.y > -margin;
        });
    },

    spawnPreviewObstacle(defs, w, h) {
        if (!defs || !defs.length) return;
        let total = 0;
        defs.forEach((d) => { total += Math.max(1, d.weight || 1); });
        let r = Math.random() * total;
        let def = defs[0];
        for (let i = 0; i < defs.length; i++) {
            r -= Math.max(1, defs[i].weight || 1);
            if (r <= 0) { def = defs[i]; break; }
        }
        if (typeof obstacleManager !== 'undefined' && obstacleManager.createObstacleFromDef) {
            const origin = obstacleManager.spawnOriginForDirection
                ? obstacleManager.spawnOriginForDirection(def.direction || 'ltr', def.width, def.height, { width: w, height: h })
                : { x: -(def.width || 18), y: Math.random() * Math.max(1, h - (def.height || 18)) };
            this.previewObstacles.push(obstacleManager.createObstacleFromDef(def, { x: origin.x, y: origin.y }));
            return;
        }
        const size = { width: def.width || 18, height: def.height || 18 };
        const horizontalSpeed = def.speed != null ? def.speed : 0.8;
        this.previewObstacles.push({
            x: -size.width,
            y: Math.random() * Math.max(1, h - size.height),
            width: size.width,
            height: size.height,
            horizontalSpeed,
            verticalSpeed: horizontalSpeed * 0.3,
            type: def.type,
            kind: def.kind,
            isFog: def.kind === 'fog',
            reflectsShots: !!def.reflectsShots,
            sprite: def.sprite,
            opacity: def.opacity != null ? def.opacity : 1,
            opticalMode: def.opticalMode || 'none',
            rotation: 0
        });
    },

    drawObstaclePreviews(ctx) {
        const list = this.previewObstacles || [];
        const fogs = list.filter((o) => o.isFog);
        const solids = list.filter((o) => !o.isFog);
        [...fogs, ...solids].forEach((obstacle) => {
            if (typeof renderManager !== 'undefined' && renderManager.drawObstacleSprite) {
                renderManager.drawObstacleSprite(ctx, obstacle);
                return;
            }
            const spriteName = obstacle.sprite
                || (obstacle.isFog ? 'fog' : (obstacle.reflectsShots ? 'shield' : 'obstacle'));
            const alpha = obstacle.opacity != null ? obstacle.opacity : 1;
            if (typeof graphicsManager !== 'undefined' && graphicsManager.drawSprite && graphicsManager.getSprite) {
                const sprite = graphicsManager.getSprite(spriteName)
                    || graphicsManager.getSprite(obstacle.reflectsShots ? 'shield' : 'obstacle');
                if (sprite) {
                    ctx.save();
                    if (alpha < 1) ctx.globalAlpha = alpha;
                    graphicsManager.drawSprite(
                        ctx, sprite,
                        obstacle.x, obstacle.y, obstacle.width, obstacle.height,
                        0, 'var(--current-text-secondary)'
                    );
                    ctx.restore();
                    return;
                }
            }
            ctx.save();
            ctx.globalAlpha = alpha;
            ctx.fillStyle = obstacle.isFog ? 'rgba(120,140,180,0.5)' : (obstacle.reflectsShots ? '#7a9aaa' : '#6a6a6a');
            ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
            ctx.restore();
        });
    },

    drawSideEnemyPreviews(ctx, w, h, enemies) {
        if (!enemies.length) return;
        enemies.slice(0, 4).forEach((entry, i) => {
            const x = w - 48;
            const y = 28 + i * 48;
            ctx.save();
            ctx.globalAlpha = 0.9;
            if (typeof graphicsManager !== 'undefined' && graphicsManager.renderEnemyShip) {
                graphicsManager.renderEnemyShip(ctx, {
                    x, y, width: 24, height: 18, type: entry.type
                }, 0.85);
            } else {
                ctx.fillStyle = '#999';
                ctx.fillRect(x, y, 24, 18);
            }
            if (entry.champion) {
                ctx.strokeStyle = '#c45c26';
                ctx.lineWidth = 2;
                ctx.strokeRect(x - 2, y - 2, 28, 22);
            }
            ctx.restore();
        });
    },

    renderList() {
        const list = this.overlay && this.overlay.querySelector('#pvList');
        if (!list) return;
        list.innerHTML = '';

        this.systems.forEach((sys) => {
            const group = document.createElement('div');
            group.className = 'cv-system-group';

            const head = document.createElement('div');
            head.className = 'cv-system-label';
            head.textContent = sys.name || 'SYSTEM';
            group.appendChild(head);

            if (!sys.planets.length) {
                const empty = document.createElement('div');
                empty.className = 'cv-system-empty';
                empty.textContent = '—';
                group.appendChild(empty);
            } else {
                sys.planets.forEach((planet) => {
                    const flatIndex = this.planets.findIndex((p) => p.id === planet.id);
                    const btn = document.createElement('button');
                    btn.type = 'button';
                    btn.className = 'content-viewer-item' + (flatIndex === this.selectedIndex ? ' selected' : '');
                    btn.innerHTML =
                        this.planetIconHtmlStatic(planet.id, 32) +
                        `<span class="cv-item-label">${planet.name}` +
                        (typeof devProfileToggles !== 'undefined' && devProfileToggles.active()
                            ? devProfileToggles.badgesHtml(this.planetProgressFlags(planet))
                            : '') +
                        `</span>`;
                    btn.addEventListener('click', () => {
                        this.selectedIndex = flatIndex;
                        this.renderList();
                        this.renderDetail();
                        this.persist();
                    });
                    group.appendChild(btn);
                });
            }
            list.appendChild(group);
        });
        const selected = list.querySelector('.content-viewer-item.selected');
        if (selected) selected.scrollIntoView({ block: 'nearest', behavior: 'auto' });
    },

    renderDetail() {
        const root = this.overlay && this.overlay.querySelector('#pvDetail');
        const p = this.planets[this.selectedIndex];
        if (!root || !p) return;

        const stageRows = (p.stages && p.stages.length)
            ? p.stages.map((s) => {
                const label = s.key === 'boss' ? 'BOSS' : `STAGE ${s.key}`;
                return `<div class="stat-row"><span class="stat-label">${label}</span><span class="stat-value">${s.enemies} enemies</span></div>`;
            }).join('')
            : '<div class="stat-row"><span class="stat-label">Stages</span><span class="stat-value">—</span></div>';

        const systemsHtml = this.systems.map((sys) => {
            const active = sys.id === p.galaxyId || sys.name === p.galaxy;
            const count = sys.planets.length;
            return `<span class="cv-system-chip${active ? ' active' : ''}">${sys.name} (${count})</span>`;
        }).join('');

        root.innerHTML = `
            <div class="content-viewer-hero">
                ${this.planetIconHtml(p.id, 48)}
                <div>
                    <h3 class="content-viewer-name">${p.name}</h3>
                    <p class="content-viewer-desc">${p.description || 'No description.'}</p>
                </div>
            </div>
            <div class="cv-systems-row">
                <div class="cv-systems-title">SYSTEMS</div>
                <div class="cv-systems-chips">${systemsHtml || '—'}</div>
            </div>
            <div class="content-viewer-stats">
                <div class="stat-row"><span class="stat-label">Galaxy</span><span class="stat-value">${p.galaxy || '—'}</span></div>
                <div class="stat-row"><span class="stat-label">Factions</span><span class="stat-value">${(p.factions && p.factions.length) ? p.factions.join(', ') : 'ALL'}</span></div>
                <div class="stat-row"><span class="stat-label">Difficulty</span><span class="stat-value">${p.difficulty || '—'}</span></div>
                <div class="stat-row"><span class="stat-label">BG Layers</span><span class="stat-value">${p.layerCount}</span></div>
                <div class="stat-row"><span class="stat-label">Enemies</span><span class="stat-value">${p.enemyCount}</span></div>
            </div>
            <div class="cv-stages-block">
                <div class="cv-systems-title">STAGES</div>
                <div class="content-viewer-stats">${stageRows}</div>
            </div>
        `;
        if (this._devToggles) this._devToggles.refresh();
    },

    persist() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            const p = this.planets[this.selectedIndex];
            menuStateManager.setScreen('planet-viewer', { planet: p ? p.id : 'mars' });
        }
    },

    handleKeyDown(e) {
        if (!this.visible) return;
        if (this._devToggles && this._devToggles.handleKey(e)) return;
        if (e.key === 'Escape' && this.previewFullscreen) {
            e.preventDefault();
            this.setPreviewFullscreen(false);
            return;
        }
        switch (e.key) {
            case 'ArrowUp':
            case 'ArrowLeft':
                e.preventDefault();
                this.selectedIndex = Math.max(0, this.selectedIndex - 1);
                this.renderList();
                this.renderDetail();
                this.persist();
                break;
            case 'ArrowDown':
            case 'ArrowRight':
                e.preventDefault();
                this.selectedIndex = Math.min(this.planets.length - 1, this.selectedIndex + 1);
                this.renderList();
                this.renderDetail();
                this.persist();
                break;
            case 'e':
            case 'E':
            case 'Enter':
                e.preventDefault();
                this.openEditor();
                break;
            case 'Escape':
                e.preventDefault();
                this.close();
                break;
        }
    },
});


/* --- js/ui/planet-viewer/open-editor.js --- */
"use strict";

// PlanetViewerUI methods, split from planet-viewer.js.
extendClass(PlanetViewerUI, {
    openEditor() {
        const p = this.planets[this.selectedIndex];
        if (!p || typeof planetEditorUI === 'undefined') return;
        this.hide();
        planetEditorUI.show(p.id, undefined, false, { returnTo: 'planet-viewer' });
    },

    close() {
        this.hide();
        const container = document.querySelector('.game-container');
        const inGame = container && container.style.display !== 'none';
        if (inGame) {
            if (typeof menuStateManager !== 'undefined') menuStateManager.setScreen('ingame');
            return;
        }
        if (this.onClose) {
            const cb = this.onClose;
            this.onClose = null;
            cb();
            return;
        }
        if (typeof homeStationUI !== 'undefined') {
            homeStationUI.show({
                tab: 'explorations',
                focusExplore: 'planets',
                onClose: () => {
                    if (typeof startScreenManager !== 'undefined') startScreenManager.show();
                }
            });
        } else if (typeof startScreenManager !== 'undefined') {
            startScreenManager.show();
        } else if (typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('start');
        }
    },
});


/* --- js/ui/planet-viewer.js --- */
"use strict";

// PlanetViewerUI is defined in planet-viewer/core.js and extended by the other files in planet-viewer/,
// which index.html loads before this file.
var planetViewerUI = new PlanetViewerUI();


/* --- js/ui/enemy-viewer/core.js --- */
"use strict";

/**
 * Enemy Viewer — browse enemy types with ship icons; open Enemy Editor from here.
 * Open: Start menu → ENEMIES, Pause → ENEMIES
 */
var EnemyViewerUI = class EnemyViewerUI {
    constructor() {
        this.visible = false;
        this.selectedIndex = 0;
        this.enemies = [];
        this.overlay = null;
        this.previewCanvas = null;
        this.previewCtx = null;
        this.previewAnimId = null;
        this.previewZoom = 1;
        this.previewFullscreen = false;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewPanning = false;
        this.previewPanLastX = 0;
        this.previewPanLastY = 0;
        this.previewSim = null;
        this.previewLastTs = 0;
        this._keyHandler = (e) => this.handleKeyDown(e);
        this._onAssetsReady = () => {
            if (this.visible) {
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
            }
        };
        if (typeof window !== 'undefined') {
            window.addEventListener('vf-sprites-loaded', this._onAssetsReady);
            window.addEventListener('vf-ships-loaded', this._onAssetsReady);
        }
    }

    getEnemyList() {
        if (typeof enemyConfigManager === 'undefined') {
            return [
                { id: 'enemyBasic', name: 'BASIC', description: '', factions: ['pirate'], primaryFaction: 'pirate', maxHealth: 100, armor: 15, damage: 25, speed: 1.5, weapon: 'laser', shootInterval: 1200, verticalSpeed: 0.3, minY: 25, maxY: 100 },
                { id: 'enemyFast', name: 'FAST', description: '', factions: ['kronax'], primaryFaction: 'kronax', maxHealth: 80, armor: 8, damage: 20, speed: 2.75, weapon: 'laser', shootInterval: 900, verticalSpeed: 0.4, minY: 25, maxY: 100 },
                { id: 'enemyHeavy', name: 'HEAVY', description: '', factions: ['machine'], primaryFaction: 'machine', maxHealth: 180, armor: 35, damage: 40, speed: 1.0, weapon: 'plasma', shootInterval: 1500, verticalSpeed: 0.2, minY: 25, maxY: 100 },
                { id: 'enemyBoss', name: 'BOSS', description: '', factions: ['voidborn'], primaryFaction: 'voidborn', maxHealth: 400, armor: 50, damage: 60, speed: 0.4, weapon: 'plasma', shootInterval: 800, verticalSpeed: 0.15, minY: 20, maxY: 80 }
            ];
        }
        const factionOrder = typeof enemyConfigManager.getFactionOptions === 'function'
            ? enemyConfigManager.getFactionOptions()
            : ['terran', 'kronax', 'voidborn', 'pirate', 'machine'];
        let typeIds = enemyConfigManager.getTypeIds();
        const devMode = typeof startScreenManager !== 'undefined' && startScreenManager.devMode;
        if (!devMode && typeof profileManager !== 'undefined' && profileManager.hasActiveProfile()) {
            const allowed = {};
            profileManager.getDiscovered('enemies').forEach((id) => { allowed[id] = true; });
            typeIds = typeIds.filter((id) => !!allowed[id]);
        }
        const list = typeIds.map((id) => {
            const cfg = enemyConfigManager.getConfig(id);
            const factions = (cfg && Array.isArray(cfg.factions) && cfg.factions.length)
                ? cfg.factions.slice()
                : [enemyConfigManager.getDefaultFaction
                    ? enemyConfigManager.getDefaultFaction(id)
                    : 'pirate'];
            return {
                id: id,
                name: enemyConfigManager.getDisplayName(id) || (cfg && cfg.name) || id,
                description: (cfg && cfg.description) || '',
                factions: factions,
                primaryFaction: factions[0] || 'unassigned',
                maxHealth: (cfg && cfg.maxHealth) || 0,
                armor: (cfg && cfg.armor) || 0,
                damage: (cfg && cfg.damage) || 0,
                speed: (cfg && cfg.speed) || 0,
                weapon: (cfg && cfg.defaultWeapon) || '—',
                shootInterval: (cfg && cfg.shootInterval) || 1200,
                verticalSpeed: (cfg && cfg.verticalSpeed) || 0.3,
                minY: (cfg && cfg.minY != null) ? cfg.minY : 25,
                maxY: (cfg && cfg.maxY != null) ? cfg.maxY : 100,
                shieldMax: (cfg && cfg.shieldMax) || 0
            };
        });
        list.sort((a, b) => {
            const ai = factionOrder.indexOf(a.primaryFaction);
            const bi = factionOrder.indexOf(b.primaryFaction);
            const ao = ai === -1 ? 999 : ai;
            const bo = bi === -1 ? 999 : bi;
            if (ao !== bo) return ao - bo;
            return String(a.name).localeCompare(String(b.name));
        });
        return list;
    }

    /**
     * Expand enemies into faction clusters (multi-faction enemies appear in each group).
     * Returns [{ faction, enemies: [{ enemy, index }] }]
     */
    getFactionClusters() {
        const factionOrder = typeof enemyConfigManager !== 'undefined' && enemyConfigManager.getFactionOptions
            ? enemyConfigManager.getFactionOptions()
            : ['terran', 'kronax', 'voidborn', 'pirate', 'machine'];
        const buckets = {};
        this.enemies.forEach((enemy, index) => {
            const factions = (enemy.factions && enemy.factions.length)
                ? enemy.factions
                : [enemy.primaryFaction || 'unassigned'];
            factions.forEach((f) => {
                const key = f || 'unassigned';
                if (!buckets[key]) buckets[key] = [];
                buckets[key].push({ enemy, index });
            });
        });
        const keys = Object.keys(buckets).sort((a, b) => {
            const ai = factionOrder.indexOf(a);
            const bi = factionOrder.indexOf(b);
            const ao = ai === -1 ? 999 : ai;
            const bo = bi === -1 ? 999 : bi;
            if (ao !== bo) return ao - bo;
            return a.localeCompare(b);
        });
        return keys.map((faction) => ({ faction, enemies: buckets[faction] }));
    }

    getShipModel(typeId) {
        if (typeof factionShipStyles !== 'undefined' && factionShipStyles.resolveFactionShipVisual) {
            const visual = factionShipStyles.resolveFactionShipVisual({ typeId: typeId });
            if (visual && visual.model) return visual.model;
        }
        if (typeof enemyConfigManager !== 'undefined' && enemyConfigManager.getBaseModel) {
            const model = enemyConfigManager.getBaseModel(typeId);
            if (model) return model;
        }
        return {
            name: typeId,
            type: 'enemy',
            modelClass: 'fighter',
            width: 16,
            height: 12,
            sprite: [
                [0, 0, 1, 1, 0, 0],
                [0, 1, 2, 2, 1, 0],
                [1, 2, 3, 3, 2, 1],
                [0, 1, 2, 2, 1, 0]
            ],
            colors: {
                0: 'transparent',
                1: 'var(--current-text-secondary)',
                2: 'var(--current-text)',
                3: 'var(--current-text)'
            }
        };
    }

    resolvePreviewFaction(enemy) {
        if (!enemy) return 'pirate';
        if (enemy.primaryFaction) return enemy.primaryFaction;
        if (enemy.factions && enemy.factions.length) return enemy.factions[0];
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.taxonomyForType) {
            return planetConfigManager.taxonomyForType(enemy.id).faction || 'pirate';
        }
        return 'pirate';
    }

    resolvePreviewClass(enemy) {
        if (!enemy) return 'assault';
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.taxonomyForType) {
            return planetConfigManager.taxonomyForType(enemy.id).enemyClass || 'assault';
        }
        return 'assault';
    }

    paintShipIcon(canvas, typeId) {
        if (!canvas) return;
        const enemy = this.enemies.find((e) => e.id === typeId);
        const faction = this.resolvePreviewFaction(enemy);
        const enemyClass = this.resolvePreviewClass(enemy);
        let ship = this.getShipModel(typeId);
        if (typeof factionShipStyles !== 'undefined' && factionShipStyles.resolveFactionShipVisual) {
            const visual = factionShipStyles.resolveFactionShipVisual({
                faction: faction,
                enemyClass: enemyClass,
                typeId: typeId
            });
            if (visual && visual.model) ship = visual.model;
            canvas.setAttribute('data-ag-type', 'factionShip');
            canvas.setAttribute('data-ag-id', visual.spriteKey);
            canvas.setAttribute('data-ag-key', visual.spriteKey);
        } else {
            if (typeof shipRenderer !== 'undefined') {
                if (shipRenderer.init) shipRenderer.init();
                shipRenderer.renderShipPreview(canvas, ship, 1);
            }
            const spriteName = typeof shipRenderer !== 'undefined' && shipRenderer.getSpriteNameForShip
                ? shipRenderer.getSpriteNameForShip(ship)
                : null;
            if (spriteName) canvas.setAttribute('data-ag-key', spriteName);
            else if (typeId) canvas.setAttribute('data-ag-key', String(typeId));
        }
        if (typeof graphicsManager !== 'undefined' && graphicsManager.renderEnemyShip) {
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                const scale = Math.min(canvas.width / 30, canvas.height / 24) * 0.85;
                graphicsManager.renderEnemyShip(ctx, {
                    x: (canvas.width - 16) / 2,
                    y: (canvas.height - 12) / 2,
                    width: 16,
                    height: 12,
                    type: typeId,
                    faction: faction,
                    enemyClass: enemyClass,
                    tier: (typeof factionShipStyles !== 'undefined' && factionShipStyles.classTier)
                        ? factionShipStyles.classTier[enemyClass]
                        : 2
                }, scale);
            }
        } else if (typeof shipRenderer !== 'undefined') {
            if (shipRenderer.init) shipRenderer.init();
            shipRenderer.renderShipPreview(canvas, ship, 1);
        }
        const spriteName = ship && ship.factionSpriteKey;
        const hasSprite = typeof spriteLoader !== 'undefined' && spriteName && spriteLoader.getSprite(spriteName);
        const shipsReady = typeof graphicsManager !== 'undefined'
            && graphicsManager.shipAssetLoader
            && graphicsManager.shipAssetLoader.isLoaded();
        if ((!hasSprite || !shipsReady) && !canvas.dataset.vfRetryBound) {
            canvas.dataset.vfRetryBound = '1';
            const retry = () => {
                if (!canvas.isConnected || !this.visible) return;
                this.paintShipIcon(canvas, typeId);
            };
            window.addEventListener('vf-sprites-loaded', retry, { once: true });
            window.addEventListener('vf-ships-loaded', retry, { once: true });
            window.addEventListener('vf-asset-accepted', retry, { once: true });
        }
    }

    show(options) {
        if (options && Object.prototype.hasOwnProperty.call(options, 'onClose')) {
            this.onClose = options.onClose;
        }
        this.enemies = this.getEnemyList();
        if (!this.enemies.length) return;
        const preferId = options && options.enemyType;
        if (preferId) {
            const idx = this.enemies.findIndex((e) => e.id === preferId);
            if (idx >= 0) this.selectedIndex = idx;
        }
        this.selectedIndex = Math.max(0, Math.min(this.selectedIndex, this.enemies.length - 1));
        this.visible = true;
        this.createUI();
        document.addEventListener('keydown', this._keyHandler);
        if (!(options && options.skipPersist) && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('enemy-viewer', {
                enemyType: this.enemies[this.selectedIndex].id
            });
        }
    }

    hide() {
        this.visible = false;
        this.stopPreview();
        this.cleanupPreviewControls();
        this.setPreviewFullscreen(false);
        document.removeEventListener('keydown', this._keyHandler);
        if (this._panelResize) {
            this._panelResize.destroy();
            this._panelResize = null;
        }
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
        this.previewCanvas = null;
        this.previewCtx = null;
        this.previewSim = null;
    }
}


/* --- js/ui/enemy-viewer/create-ui.js --- */
"use strict";

// EnemyViewerUI methods, split from enemy-viewer.js.
extendClass(EnemyViewerUI, {
    createUI() {
        if (this._panelResize) {
            this._panelResize.destroy();
            this._panelResize = null;
        }
        if (this.overlay) this.overlay.remove();

        this.overlay = document.createElement('div');
        this.overlay.className = 'content-viewer-overlay';
        this.overlay.innerHTML = `
            <div class="content-viewer-panel">
                <h2 class="content-viewer-title">ENEMIES</h2>
                <div class="content-viewer-body has-preview" id="evViewerBody">
                    <aside class="content-viewer-list" id="evList"></aside>
                    <div class="pe-resize-handle" data-resize="left" title="Resize enemy list"></div>
                    <div class="content-viewer-detail" id="evDetail"></div>
                    <div class="pe-resize-handle" data-resize="right" title="Resize preview"></div>
                    <aside class="content-viewer-preview planet-editor-preview-wrap" id="evPreviewWrap">
                        <div class="pe-preview-toolbar">
                            <button type="button" class="pe-btn pe-preview-btn" id="evZoomOut" title="Zoom out">−</button>
                            <span class="pe-zoom-label" id="evZoomLabel">100%</span>
                            <button type="button" class="pe-btn pe-preview-btn" id="evZoomIn" title="Zoom in">+</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="evZoomReset" title="Reset zoom">1:1</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="evPreviewFullscreen" title="Fullscreen">FULL</button>
                        </div>
                        <div class="pe-preview-viewport" id="evPreviewViewport">
                            <canvas id="evPreview" width="200" height="300"></canvas>
                        </div>
                        <div class="pe-preview-label">PREVIEW</div>
                    </aside>
                </div>
                <div class="content-viewer-footer">
                    <button type="button" class="pe-btn pe-primary" id="evEdit">EDIT</button>
                    <button type="button" class="pe-btn" id="evEditGfx">EDIT GFX</button>
                    <button type="button" class="pe-btn" id="evClose">CLOSE</button>
                </div>
                <div class="content-viewer-hint">↑↓ Navigate • E Edit • ESC Close</div>
            </div>
        `;
        document.body.appendChild(this.overlay);
        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }

        this.bindPreviewControls();
        this.setupPanelResize();
        this.renderList();
        this.renderDetail();
        this.resetPreviewSim();
        this.startPreview();

        this.overlay.querySelector('#evEdit').addEventListener('click', () => this.openEditor());
        this.overlay.querySelector('#evEditGfx').addEventListener('click', () => this.openGfxEditor());
        this.overlay.querySelector('#evClose').addEventListener('click', () => this.close());
        this.mountDevToggles();
    },

    mountDevToggles() {
        this._devToggles = null;
        if (typeof devProfileToggles === 'undefined' || !devProfileToggles.active()) return;
        const footer = this.overlay.querySelector('.content-viewer-footer');
        const hint = this.overlay.querySelector('.content-viewer-hint');
        this._devToggles = devProfileToggles.mount(footer, hint, {
            known: () => {
                const e = this.enemies[this.selectedIndex];
                return !!(e && profileManager.isDiscovered('enemies', e.id));
            },
            toggleKnown: () => {
                const e = this.enemies[this.selectedIndex];
                if (e) profileManager.toggleDiscovered('enemies', e.id);
            },
            onChange: () => {
                this.renderList();
                this.renderDetail();
                if (this._devToggles) this._devToggles.refresh();
            }
        });
    },

    setupPanelResize() {
        const body = this.overlay && this.overlay.querySelector('#evViewerBody');
        if (!body || typeof setupPanelResize !== 'function') return;
        this._panelResize = setupPanelResize({
            body,
            root: this.overlay,
            storageKey: 'evPanelWidths',
            defaults: { left: 220, right: 260 },
            mins: { left: 140, right: 180, center: 200 },
            leftVar: '--cv-left-w',
            rightVar: '--cv-right-w',
            onChange: () => {
                if (this.visible) this.applyPreviewView();
            }
        });
    },

    bindPreviewControls() {
        const overlay = this.overlay;
        this.previewCanvas = overlay.querySelector('#evPreview');
        this.previewCtx = this.previewCanvas.getContext('2d');
        this.previewZoom = 1;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewFullscreen = false;

        overlay.querySelector('#evZoomOut').addEventListener('click', () => this.setPreviewZoom(this.previewZoom - 0.25));
        overlay.querySelector('#evZoomIn').addEventListener('click', () => this.setPreviewZoom(this.previewZoom + 0.25));
        overlay.querySelector('#evZoomReset').addEventListener('click', () => {
            this.previewPanX = 0;
            this.previewPanY = 0;
            this.setPreviewZoom(1);
        });
        overlay.querySelector('#evPreviewFullscreen').addEventListener('click', () => {
            this.setPreviewFullscreen(!this.previewFullscreen);
        });

        const viewport = overlay.querySelector('#evPreviewViewport');
        viewport.addEventListener('wheel', (e) => {
            e.preventDefault();
            this.setPreviewZoom(this.previewZoom + (e.deltaY < 0 ? 0.1 : -0.1));
        }, { passive: false });
        viewport.addEventListener('contextmenu', (e) => e.preventDefault());
        viewport.addEventListener('mousedown', (e) => {
            if (e.button !== 2) return;
            e.preventDefault();
            this.previewPanning = true;
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            viewport.classList.add('pe-panning');
        });
        const onMove = (e) => {
            if (!this.previewPanning || !this.visible) return;
            this.previewPanX += vfPanDelta(this.previewCanvas, e.clientX - this.previewPanLastX);
            this.previewPanY += vfPanDelta(this.previewCanvas, e.clientY - this.previewPanLastY);
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            this.applyPreviewView();
        };
        const endPan = () => {
            if (!this.previewPanning) return;
            this.previewPanning = false;
            const vp = this.overlay && this.overlay.querySelector('#evPreviewViewport');
            if (vp) vp.classList.remove('pe-panning');
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', endPan);
        this._previewCleanup = () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', endPan);
        };
        this.applyPreviewView();
        requestAnimationFrame(() => this.applyPreviewView());
    },

    setPreviewZoom(zoom) {
        this.previewZoom = Math.min(3, Math.max(0.5, Math.round(zoom * 100) / 100));
        this.applyPreviewView();
    },

    setPreviewFullscreen(on) {
        this.previewFullscreen = !!on;
        requestAnimationFrame(() => this.applyPreviewView());
    },

    applyPreviewView() {
        const wrap = this.overlay && this.overlay.querySelector('#evPreviewWrap');
        const label = this.overlay && this.overlay.querySelector('#evZoomLabel');
        const fsBtn = this.overlay && this.overlay.querySelector('#evPreviewFullscreen');
        const viewport = this.overlay && this.overlay.querySelector('#evPreviewViewport');
        if (wrap) wrap.classList.toggle('pe-preview-fs', this.previewFullscreen);
        if (label) label.textContent = `${Math.round(this.previewZoom * 100)}%`;
        if (fsBtn) fsBtn.textContent = this.previewFullscreen ? 'EXIT' : 'FULL';
        if (this.previewCanvas && viewport) {
            const pad = 8;
            const availW = Math.max(140, viewport.clientWidth - pad);
            const availH = Math.max(200, viewport.clientHeight - pad);
            const aspect = this.previewCanvas.width / this.previewCanvas.height || (2 / 3);
            let fitW = availW;
            let fitH = fitW / aspect;
            if (fitH > availH) {
                fitH = availH;
                fitW = fitH * aspect;
            }
            this.previewCanvas.style.width = `${Math.round(fitW)}px`;
            this.previewCanvas.style.height = `${Math.round(fitH)}px`;
            this.previewCanvas.style.transform =
                `translate(${this.previewPanX}px, ${this.previewPanY}px) scale(${this.previewZoom})`;
        }
    },

    startPreview() {
        this.stopPreview();
        this.previewLastTs = 0;
        if (!this.previewSim) this.resetPreviewSim();
        const loop = () => {
            if (!this.visible) return;
            this.drawPreview();
            this.previewAnimId = requestAnimationFrame(loop);
        };
        this.previewAnimId = requestAnimationFrame(loop);
    },

    stopPreview() {
        if (this.previewAnimId) {
            cancelAnimationFrame(this.previewAnimId);
            this.previewAnimId = null;
        }
        this.previewLastTs = 0;
    },

    cleanupPreviewControls() {
        if (this._previewCleanup) {
            this._previewCleanup();
            this._previewCleanup = null;
        }
    },

    resetPreviewSim() {
        const e = this.enemies[this.selectedIndex];
        const model = this.getShipModel(e ? e.id : 'enemyBasic');
        const shipW = Math.max(8, Math.round(model.width || 18));
        const shipH = Math.max(8, Math.round(model.height || 14));
        const minY = Number(e && e.minY != null ? e.minY : 25);
        const maxY = Number(e && e.maxY != null ? e.maxY : 100);
        this.previewSim = {
            enemy: {
                x: 100 - shipW / 2,
                y: minY,
                width: shipW,
                height: shipH,
                speed: Number(e && e.speed != null ? e.speed : 1),
                verticalSpeed: Number(e && e.verticalSpeed != null ? e.verticalSpeed : 0.3),
                minY,
                maxY
            },
            bullets: [],
            shootAcc: 0,
            starPhase: 0
        };
        this.previewLastTs = 0;
    },
});


/* --- js/ui/enemy-viewer/update-preview-sim.js --- */
"use strict";

// EnemyViewerUI methods, split from enemy-viewer.js.
extendClass(EnemyViewerUI, {
    updatePreviewSim(dtMs) {
        const sim = this.previewSim;
        const cfg = this.enemies[this.selectedIndex];
        if (!sim || !cfg) return;
        const frameScale = dtMs / 16.67;
        const model = this.getShipModel(cfg.id);
        const en = sim.enemy;
        en.width = Math.max(8, Math.round(model.width || 18));
        en.height = Math.max(8, Math.round(model.height || 14));
        en.speed = Number(cfg.speed) || 1;
        en.verticalSpeed = Number(cfg.verticalSpeed) || 0.3;
        en.minY = Number(cfg.minY != null ? cfg.minY : 25);
        en.maxY = Number(cfg.maxY != null ? cfg.maxY : 100);

        en.x += en.speed * frameScale * (en._dirX || 1);
        if (en.x <= 4 || en.x + en.width >= 196) {
            en._dirX = -(en._dirX || 1);
            en.x = Math.max(4, Math.min(196 - en.width, en.x));
        }
        en.y += en.verticalSpeed * frameScale * (en._dirY || 1);
        if (en.y <= en.minY || en.y >= en.maxY) {
            en._dirY = -(en._dirY || 1);
            en.y = Math.max(en.minY, Math.min(en.maxY, en.y));
        }

        sim.starPhase += dtMs * 0.004;
        sim.shootAcc += dtMs;
        const interval = Math.max(200, Number(cfg.shootInterval) || 1200);
        if (sim.shootAcc >= interval) {
            sim.shootAcc = 0;
            sim.bullets.push({
                x: en.x + en.width / 2 - 1,
                y: en.y + en.height,
                vy: 2.5,
                life: 1400,
                plasma: String(cfg.weapon || '').toLowerCase().includes('plasma')
            });
        }
        sim.bullets = sim.bullets.filter((b) => {
            b.y += b.vy * frameScale;
            b.life -= dtMs;
            return b.life > 0 && b.y < 310;
        });
    },

    drawPreview() {
        const canvas = this.previewCanvas;
        const ctx = this.previewCtx;
        const cfg = this.enemies[this.selectedIndex];
        if (!canvas || !ctx || !cfg) return;

        const now = performance.now();
        const dt = this.previewLastTs ? Math.min(48, now - this.previewLastTs) : 16;
        this.previewLastTs = now;
        if (!this.previewSim) this.resetPreviewSim();
        this.updatePreviewSim(dt);

        const w = canvas.width;
        const h = canvas.height;
        const sim = this.previewSim;

        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, w, h);

        ctx.fillStyle = 'rgba(200, 180, 140, 0.35)';
        for (let i = 0; i < 40; i++) {
            const sx = (i * 97) % w;
            const sy = (i * 53 + Math.floor(sim.starPhase * 20)) % h;
            ctx.fillRect(sx, sy, 2, 2);
        }

        for (const b of sim.bullets) {
            ctx.fillStyle = b.plasma ? '#c06040' : '#e07028';
            if (b.plasma) {
                ctx.beginPath();
                ctx.arc(b.x + 1, b.y + 2, 3, 0, Math.PI * 2);
                ctx.fill();
            } else {
                ctx.fillRect(b.x, b.y, 2, 6);
            }
        }

        const model = this.getShipModel(cfg.id);
        const e = sim.enemy;
        let rendered = false;
        if (typeof graphicsManager !== 'undefined' && graphicsManager.renderEnemyShip) {
            try {
                graphicsManager.renderEnemyShip(ctx, {
                    x: e.x,
                    y: e.y,
                    width: e.width,
                    height: e.height,
                    type: cfg.id,
                    faction: this.resolvePreviewFaction(cfg),
                    enemyClass: this.resolvePreviewClass(cfg),
                    tier: (typeof factionShipStyles !== 'undefined' && factionShipStyles.classTier)
                        ? factionShipStyles.classTier[this.resolvePreviewClass(cfg)]
                        : 2
                }, 1);
                rendered = true;
            } catch (err) {
                rendered = false;
            }
        }
        if (!rendered) {
            if (typeof shipRenderer !== 'undefined') {
                if (shipRenderer.init) shipRenderer.init();
                const tmp = document.createElement('canvas');
                tmp.width = Math.max(1, e.width);
                tmp.height = Math.max(1, e.height);
                shipRenderer.renderShipPreview(tmp, model, 1);
                ctx.drawImage(tmp, e.x, e.y, e.width, e.height);
            } else {
                ctx.fillStyle = '#e07028';
                ctx.fillRect(e.x, e.y, e.width, e.height);
            }
        }

        ctx.fillStyle = '#e07028';
        ctx.font = '10px "Courier New", monospace';
        ctx.textAlign = 'center';
        ctx.fillText(String(cfg.name || cfg.id).toUpperCase(), w / 2, h - 34);
        ctx.fillStyle = '#b09070';
        ctx.font = '9px "Courier New", monospace';
        ctx.fillText(`HP ${cfg.maxHealth}  SPD ${Number(cfg.speed).toFixed(2)}`, w / 2, h - 20);
        ctx.fillText(`ARM ${cfg.armor}  DMG ${cfg.damage}`, w / 2, h - 8);
    },

    renderList() {
        const list = this.overlay && this.overlay.querySelector('#evList');
        if (!list) return;
        list.innerHTML = '';
        const clusters = this.getFactionClusters();
        clusters.forEach((cluster) => {
            const header = document.createElement('div');
            header.className = 'content-viewer-group';
            header.textContent = 'FACTION: ' + String(cluster.faction).toUpperCase();
            list.appendChild(header);
            cluster.enemies.forEach(({ enemy, index }) => {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'content-viewer-item' + (index === this.selectedIndex ? ' selected' : '');
                btn.innerHTML =
                    `<canvas class="cv-icon cv-ship-icon" width="32" height="32" data-enemy="${enemy.id}"></canvas>` +
                    `<span class="cv-item-label">${enemy.name}` +
                    (typeof devProfileToggles !== 'undefined' && devProfileToggles.active()
                        ? devProfileToggles.badgesHtml({
                            known: profileManager.isDiscovered('enemies', enemy.id)
                        })
                        : '') +
                    `</span>`;
                btn.addEventListener('click', () => {
                    this.selectedIndex = index;
                    this.renderList();
                    this.renderDetail();
                    this.resetPreviewSim();
                    this.persist();
                });
                list.appendChild(btn);
                const canvas = btn.querySelector('canvas');
                this.paintShipIcon(canvas, enemy.id);
            });
        });
        const selected = list.querySelector('.content-viewer-item.selected');
        if (selected) selected.scrollIntoView({ block: 'nearest', behavior: 'auto' });
    },

    renderDetail() {
        const root = this.overlay && this.overlay.querySelector('#evDetail');
        const e = this.enemies[this.selectedIndex];
        if (!root || !e) return;
        const cfg = typeof enemyConfigManager !== 'undefined' ? enemyConfigManager.getConfig(e.id) : null;
        const abilities = (cfg && (cfg.abilities || cfg.defenseMechanisms)) || [];
        const devOn = typeof startScreenManager !== 'undefined' && startScreenManager.devMode;
        let dropDev = '';
        if (devOn && typeof economyConfig !== 'undefined' && economyConfig.buildEnemyDropDevTableHtml) {
            let dropBonus = 0;
            if (typeof profileManager !== 'undefined' && profileManager.getStationStats) {
                const stats = profileManager.getStationStats();
                dropBonus = stats && stats.dropBonus ? stats.dropBonus : 0;
            }
            dropDev = economyConfig.buildEnemyDropDevTableHtml(dropBonus, e.id);
        }
        root.innerHTML = `
            <div class="content-viewer-hero">
                <canvas class="cv-ship-preview" width="32" height="32" id="evHeroCanvas"></canvas>
                <div>
                    <h3 class="content-viewer-name">${e.name}</h3>
                    <p class="content-viewer-desc">${e.description || 'No description.'}</p>
                </div>
            </div>
            <div class="content-viewer-stats">
                <div class="stat-row"><span class="stat-label">Hull</span><span class="stat-value">${(cfg && cfg.hullId) ? String(cfg.hullId).toUpperCase() : String(e.id).toUpperCase()}</span></div>
                <div class="stat-row"><span class="stat-label">Factions</span><span class="stat-value">${(cfg && cfg.factions && cfg.factions.length) ? cfg.factions.join(', ') : '—'}</span></div>
                <div class="stat-row"><span class="stat-label">Class</span><span class="stat-value">${String(this.resolvePreviewClass(e)).toUpperCase()}</span></div>
                <div class="stat-row"><span class="stat-label">Galaxies</span><span class="stat-value">${(cfg && cfg.galaxyIds && cfg.galaxyIds.length) ? cfg.galaxyIds.join(', ') : 'ALL'}</span></div>
                <div class="stat-row"><span class="stat-label">Planets</span><span class="stat-value">${(cfg && cfg.planetIds && cfg.planetIds.length) ? cfg.planetIds.join(', ') : 'ALL'}</span></div>
                <div class="stat-row"><span class="stat-label">Health</span><span class="stat-value">${e.maxHealth}</span></div>
                <div class="stat-row"><span class="stat-label">Armor</span><span class="stat-value">${e.armor}</span></div>
                <div class="stat-row"><span class="stat-label">Damage</span><span class="stat-value">${e.damage}</span></div>
                <div class="stat-row"><span class="stat-label">Speed</span><span class="stat-value">${e.speed}</span></div>
                <div class="stat-row"><span class="stat-label">Weapon</span><span class="stat-value">${String(e.weapon || '—').toUpperCase()}</span></div>
                <div class="stat-row stat-row-abilities"><span class="stat-label">Abilities</span><span class="stat-value cv-ability-chips">${
                    typeof abilityConfigManager !== 'undefined'
                        ? abilityConfigManager.formatAbilityChipsHtml(abilities)
                        : (abilities.length ? abilities.join(', ') : '—')
                }</span></div>
            </div>
            ${dropDev}
        `;
        const hero = root.querySelector('#evHeroCanvas');
        this.paintShipIcon(hero, e.id);
        if (this._devToggles) this._devToggles.refresh();
    },

    persist() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            const e = this.enemies[this.selectedIndex];
            menuStateManager.setScreen('enemy-viewer', { enemyType: e ? e.id : 'enemyBasic' });
        }
    },

    handleKeyDown(e) {
        if (!this.visible) return;
        if (this._devToggles && this._devToggles.handleKey(e)) return;
        if (e.key === 'Escape' && this.previewFullscreen) {
            e.preventDefault();
            this.setPreviewFullscreen(false);
            return;
        }
        switch (e.key) {
            case 'ArrowUp':
            case 'ArrowLeft':
                e.preventDefault();
                this.selectedIndex = Math.max(0, this.selectedIndex - 1);
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
                this.persist();
                break;
            case 'ArrowDown':
            case 'ArrowRight':
                e.preventDefault();
                this.selectedIndex = Math.min(this.enemies.length - 1, this.selectedIndex + 1);
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
                this.persist();
                break;
            case 'e':
            case 'E':
            case 'Enter':
                e.preventDefault();
                this.openEditor();
                break;
            case 'Escape':
                e.preventDefault();
                this.close();
                break;
        }
    },

    openEditor() {
        const enemy = this.enemies[this.selectedIndex];
        if (!enemy || typeof enemyEditorUI === 'undefined') return;
        this.hide();
        enemyEditorUI.show(enemy.id, undefined, false, { returnTo: 'enemy-viewer' });
    },
});


/* --- js/ui/enemy-viewer/open-gfx-editor.js --- */
"use strict";

// EnemyViewerUI methods, split from enemy-viewer.js.
extendClass(EnemyViewerUI, {
    openGfxEditor() {
        const enemy = this.enemies[this.selectedIndex];
        if (!enemy || typeof componentEditorUI === 'undefined') return;
        let type = 'enemy';
        let id = enemy.id;
        if (typeof assetGenRegistry !== 'undefined' && assetGenRegistry.findByKey) {
            const hit = assetGenRegistry.findByKey(enemy.id)
                || assetGenRegistry.findByKey('enemy-' + String(enemy.id).replace(/^enemy[-_]?/, ''));
            if (hit) {
                type = hit.type;
                id = hit.id;
            }
        }
        const returnCb = this.onClose;
        this.hide();
        componentEditorUI.open({
            type: type,
            id: id,
            returnTo: 'enemy-viewer',
            onClose: () => {
                this.show({ onClose: returnCb });
            }
        });
    },

    close() {
        this.hide();
        const container = document.querySelector('.game-container');
        const inGame = container && container.style.display !== 'none';
        if (inGame) {
            if (typeof menuStateManager !== 'undefined') menuStateManager.setScreen('ingame');
            return;
        }
        if (this.onClose) {
            const cb = this.onClose;
            this.onClose = null;
            cb();
            return;
        }
        if (typeof homeStationUI !== 'undefined') {
            homeStationUI.show({
                tab: 'explorations',
                focusExplore: 'enemies',
                onClose: () => {
                    if (typeof startScreenManager !== 'undefined') startScreenManager.show();
                }
            });
        } else if (typeof startScreenManager !== 'undefined') {
            startScreenManager.show();
        } else if (typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('start');
        }
    },
});


/* --- js/ui/enemy-viewer.js --- */
"use strict";

// EnemyViewerUI is defined in enemy-viewer/core.js and extended by the other files in enemy-viewer/,
// which index.html loads before this file.
var enemyViewerUI = new EnemyViewerUI();


/* --- js/ui/ship-viewer/core.js --- */
"use strict";

/**
 * Ship Viewer — browse player ships; open Ship Editor from here.
 * Open: Start menu → SHIPS
 */
var ShipViewerUI = class ShipViewerUI {
    constructor() {
        this.visible = false;
        this.selectedIndex = 0;
        this.ships = [];
        this.overlay = null;
        this.previewCanvas = null;
        this.previewCtx = null;
        this.previewAnimId = null;
        this.previewZoom = 1;
        this.previewFullscreen = false;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewPanning = false;
        this.previewPanLastX = 0;
        this.previewPanLastY = 0;
        this.previewSim = null;
        this.previewLastTs = 0;
        this._keyHandler = (e) => this.handleKeyDown(e);
        this._onAssetsReady = () => {
            if (this.visible) {
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
            }
        };
        if (typeof window !== 'undefined') {
            window.addEventListener('vf-sprites-loaded', this._onAssetsReady);
            window.addEventListener('vf-ships-loaded', this._onAssetsReady);
        }
    }

    getShipList() {
        if (typeof shipConfigManager === 'undefined') {
            return [
                { id: 'player', name: 'STARFIGHTER', description: '', maxHealth: 80, armor: 15, damage: 25, speed: 5, weapon: 'laser' },
                { id: 'player_interceptor', name: 'INTERCEPTOR', description: '', maxHealth: 60, armor: 8, damage: 18, speed: 6, weapon: 'rapid' },
                { id: 'player_heavy', name: 'HEAVY FIGHTER', description: '', maxHealth: 150, armor: 40, damage: 45, speed: 2.5, weapon: 'spread' },
                { id: 'player_assault', name: 'ASSAULT', description: '', maxHealth: 120, armor: 25, damage: 35, speed: 3.5, weapon: 'laser' }
            ];
        }
        let ids = shipConfigManager.getTypeIds();
        const devMode = typeof startScreenManager !== 'undefined' && startScreenManager.devMode;
        if (!devMode && typeof profileManager !== 'undefined' && profileManager.hasActiveProfile()) {
            const allowed = {};
            profileManager.getDiscovered('ships').forEach((id) => { allowed[id] = true; });
            profileManager.getOwnedShipIds().forEach((id) => { allowed[id] = true; });
            ids = ids.filter((id) => !!allowed[id]);
        }
        return ids.map((id) => {
            const cfg = shipConfigManager.getConfig(id);
            return {
                id: id,
                name: shipConfigManager.getDisplayName(id) || (cfg && cfg.name) || id,
                description: (cfg && cfg.description) || '',
                maxHealth: (cfg && cfg.maxHealth) || 0,
                armor: (cfg && cfg.armor) || 0,
                damage: (cfg && cfg.damage) || 0,
                speed: (cfg && cfg.speed) || 0,
                weapon: (cfg && cfg.defaultWeapon) || '—',
                weaponCooldown: (cfg && cfg.weaponCooldown) || 300,
                weaponSpeed: (cfg && cfg.weaponSpeed) || 8,
                custom: !!(cfg && cfg.custom)
            };
        });
    }

    getShipModel(typeId) {
        if (typeof shipConfigManager !== 'undefined' && shipConfigManager.getMergedModel) {
            const model = shipConfigManager.getMergedModel(typeId);
            if (model) return model;
        }
        return {
            name: typeId,
            type: 'player',
            modelClass: 'starfighter',
            width: 20,
            height: 16,
            sprite: [
                [0, 0, 1, 1, 0, 0],
                [0, 1, 2, 2, 1, 0],
                [1, 2, 3, 3, 2, 1],
                [0, 1, 2, 2, 1, 0]
            ],
            colors: {
                0: 'transparent',
                1: 'var(--current-text-secondary)',
                2: 'var(--current-text)',
                3: 'var(--current-text)'
            }
        };
    }

    paintShipIcon(canvas, typeId) {
        if (!canvas) return;
        const ship = this.getShipModel(typeId);
        if (typeof shipRenderer !== 'undefined') {
            if (shipRenderer.init) shipRenderer.init();
            shipRenderer.renderShipPreview(canvas, ship, 1);
        }
        const spriteName = typeof shipRenderer !== 'undefined' && shipRenderer.getSpriteNameForShip
            ? shipRenderer.getSpriteNameForShip(ship)
            : null;
        if (spriteName) canvas.setAttribute('data-ag-key', spriteName);
        else if (typeId) canvas.setAttribute('data-ag-key', String(typeId));
        const hasSprite = typeof spriteLoader !== 'undefined' && spriteName && spriteLoader.getSprite(spriteName);
        const shipsReady = typeof graphicsManager !== 'undefined'
            && graphicsManager.shipAssetLoader
            && graphicsManager.shipAssetLoader.isLoaded();
        if ((!hasSprite || !shipsReady) && !canvas.dataset.vfRetryBound) {
            canvas.dataset.vfRetryBound = '1';
            const retry = () => {
                if (!canvas.isConnected || !this.visible) return;
                this.paintShipIcon(canvas, typeId);
            };
            window.addEventListener('vf-sprites-loaded', retry, { once: true });
            window.addEventListener('vf-ships-loaded', retry, { once: true });
        }
    }

    show(options) {
        if (options && Object.prototype.hasOwnProperty.call(options, 'onClose')) {
            this.onClose = options.onClose;
        }
        this.ships = this.getShipList();
        if (!this.ships.length) return;
        const preferId = options && options.shipId;
        if (preferId) {
            const idx = this.ships.findIndex((s) => s.id === preferId);
            if (idx >= 0) this.selectedIndex = idx;
        }
        this.selectedIndex = Math.max(0, Math.min(this.selectedIndex, this.ships.length - 1));
        this.visible = true;
        this.createUI();
        document.addEventListener('keydown', this._keyHandler);
        if (!(options && options.skipPersist) && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('ship-viewer', {
                shipId: this.ships[this.selectedIndex].id
            });
        }
    }

    hide() {
        this.visible = false;
        this.stopPreview();
        this.cleanupPreviewControls();
        this.setPreviewFullscreen(false);
        document.removeEventListener('keydown', this._keyHandler);
        if (this._panelResize) {
            this._panelResize.destroy();
            this._panelResize = null;
        }
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
        this.previewCanvas = null;
        this.previewCtx = null;
        this.previewSim = null;
    }

    createUI() {
        if (this._panelResize) {
            this._panelResize.destroy();
            this._panelResize = null;
        }
        if (this.overlay) this.overlay.remove();

        this.overlay = document.createElement('div');
        this.overlay.className = 'content-viewer-overlay';
        this.overlay.innerHTML = `
            <div class="content-viewer-panel">
                <h2 class="content-viewer-title">SHIPS</h2>
                <div class="content-viewer-body has-preview" id="svViewerBody">
                    <aside class="content-viewer-list" id="svList"></aside>
                    <div class="pe-resize-handle" data-resize="left" title="Resize ship list"></div>
                    <div class="content-viewer-detail" id="svDetail"></div>
                    <div class="pe-resize-handle" data-resize="right" title="Resize preview"></div>
                    <aside class="content-viewer-preview planet-editor-preview-wrap" id="svPreviewWrap">
                        <div class="pe-preview-toolbar">
                            <button type="button" class="pe-btn pe-preview-btn" id="svZoomOut" title="Zoom out">−</button>
                            <span class="pe-zoom-label" id="svZoomLabel">100%</span>
                            <button type="button" class="pe-btn pe-preview-btn" id="svZoomIn" title="Zoom in">+</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="svZoomReset" title="Reset zoom">1:1</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="svPreviewFullscreen" title="Fullscreen">FULL</button>
                        </div>
                        <div class="pe-preview-viewport" id="svPreviewViewport">
                            <canvas id="svPreview" width="200" height="300"></canvas>
                        </div>
                        <div class="pe-preview-label">PREVIEW</div>
                    </aside>
                </div>
                <div class="content-viewer-footer">
                    <button type="button" class="pe-btn" id="svNew">NEW</button>
                    <button type="button" class="pe-btn pe-primary" id="svEdit">EDIT</button>
                    <button type="button" class="pe-btn" id="svEditGfx">EDIT GFX</button>
                    <button type="button" class="pe-btn" id="svDelete">DELETE</button>
                    <button type="button" class="pe-btn" id="svClose">CLOSE</button>
                </div>
                <div class="content-viewer-hint">↑↓ Navigate • N New • E Edit • DEL Delete • ESC Close</div>
            </div>
        `;
        document.body.appendChild(this.overlay);
        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }

        this.bindPreviewControls();
        this.setupPanelResize();
        this.renderList();
        this.renderDetail();
        this.resetPreviewSim();
        this.startPreview();

        this.overlay.querySelector('#svNew').addEventListener('click', () => this.createNew());
        this.overlay.querySelector('#svEdit').addEventListener('click', () => this.openEditor());
        this.overlay.querySelector('#svEditGfx').addEventListener('click', () => this.openGfxEditor());
        this.overlay.querySelector('#svDelete').addEventListener('click', () => this.deleteSelected());
        this.overlay.querySelector('#svClose').addEventListener('click', () => this.close());
        this.mountDevToggles();
    }

    mountDevToggles() {
        this._devToggles = null;
        if (typeof devProfileToggles === 'undefined' || !devProfileToggles.active()) return;
        const footer = this.overlay.querySelector('.content-viewer-footer');
        const hint = this.overlay.querySelector('.content-viewer-hint');
        this._devToggles = devProfileToggles.mount(footer, hint, {
            known: () => {
                const s = this.ships[this.selectedIndex];
                return !!(s && profileManager.isDiscovered('ships', s.id));
            },
            toggleKnown: () => {
                const s = this.ships[this.selectedIndex];
                if (s) profileManager.toggleDiscovered('ships', s.id);
            },
            owned: () => {
                const s = this.ships[this.selectedIndex];
                return !!(s && profileManager.ownsShip(s.id));
            },
            toggleOwned: () => {
                const s = this.ships[this.selectedIndex];
                if (s) profileManager.toggleOwnedShip(s.id);
            },
            onChange: () => {
                this.renderList();
                this.renderDetail();
                if (this._devToggles) this._devToggles.refresh();
            }
        });
    }

    setupPanelResize() {
        const body = this.overlay && this.overlay.querySelector('#svViewerBody');
        if (!body || typeof setupPanelResize !== 'function') return;
        this._panelResize = setupPanelResize({
            body,
            root: this.overlay,
            storageKey: 'svPanelWidths',
            defaults: { left: 220, right: 260 },
            mins: { left: 140, right: 180, center: 200 },
            leftVar: '--cv-left-w',
            rightVar: '--cv-right-w',
            onChange: () => {
                if (this.visible) this.applyPreviewView();
            }
        });
    }
}


/* --- js/ui/ship-viewer/bind-preview-controls.js --- */
"use strict";

// ShipViewerUI methods, split from ship-viewer.js.
extendClass(ShipViewerUI, {
    bindPreviewControls() {
        const overlay = this.overlay;
        this.previewCanvas = overlay.querySelector('#svPreview');
        this.previewCtx = this.previewCanvas.getContext('2d');
        this.previewZoom = 1;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewFullscreen = false;

        overlay.querySelector('#svZoomOut').addEventListener('click', () => this.setPreviewZoom(this.previewZoom - 0.25));
        overlay.querySelector('#svZoomIn').addEventListener('click', () => this.setPreviewZoom(this.previewZoom + 0.25));
        overlay.querySelector('#svZoomReset').addEventListener('click', () => {
            this.previewPanX = 0;
            this.previewPanY = 0;
            this.setPreviewZoom(1);
        });
        overlay.querySelector('#svPreviewFullscreen').addEventListener('click', () => {
            this.setPreviewFullscreen(!this.previewFullscreen);
        });

        const viewport = overlay.querySelector('#svPreviewViewport');
        viewport.addEventListener('wheel', (e) => {
            e.preventDefault();
            this.setPreviewZoom(this.previewZoom + (e.deltaY < 0 ? 0.1 : -0.1));
        }, { passive: false });
        viewport.addEventListener('contextmenu', (e) => e.preventDefault());
        viewport.addEventListener('mousedown', (e) => {
            if (e.button !== 2) return;
            e.preventDefault();
            this.previewPanning = true;
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            viewport.classList.add('pe-panning');
        });
        const onMove = (e) => {
            if (!this.previewPanning || !this.visible) return;
            this.previewPanX += vfPanDelta(this.previewCanvas, e.clientX - this.previewPanLastX);
            this.previewPanY += vfPanDelta(this.previewCanvas, e.clientY - this.previewPanLastY);
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            this.applyPreviewView();
        };
        const endPan = () => {
            if (!this.previewPanning) return;
            this.previewPanning = false;
            const vp = this.overlay && this.overlay.querySelector('#svPreviewViewport');
            if (vp) vp.classList.remove('pe-panning');
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', endPan);
        this._previewCleanup = () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', endPan);
        };
        this.applyPreviewView();
        requestAnimationFrame(() => this.applyPreviewView());
    },

    setPreviewZoom(zoom) {
        this.previewZoom = Math.min(3, Math.max(0.5, Math.round(zoom * 100) / 100));
        this.applyPreviewView();
    },

    setPreviewFullscreen(on) {
        this.previewFullscreen = !!on;
        requestAnimationFrame(() => this.applyPreviewView());
    },

    applyPreviewView() {
        const wrap = this.overlay && this.overlay.querySelector('#svPreviewWrap');
        const label = this.overlay && this.overlay.querySelector('#svZoomLabel');
        const fsBtn = this.overlay && this.overlay.querySelector('#svPreviewFullscreen');
        const viewport = this.overlay && this.overlay.querySelector('#svPreviewViewport');
        if (wrap) wrap.classList.toggle('pe-preview-fs', this.previewFullscreen);
        if (label) label.textContent = `${Math.round(this.previewZoom * 100)}%`;
        if (fsBtn) fsBtn.textContent = this.previewFullscreen ? 'EXIT' : 'FULL';
        if (this.previewCanvas && viewport) {
            const pad = 8;
            const availW = Math.max(140, viewport.clientWidth - pad);
            const availH = Math.max(200, viewport.clientHeight - pad);
            const aspect = this.previewCanvas.width / this.previewCanvas.height || (2 / 3);
            let fitW = availW;
            let fitH = fitW / aspect;
            if (fitH > availH) {
                fitH = availH;
                fitW = fitH * aspect;
            }
            this.previewCanvas.style.width = `${Math.round(fitW)}px`;
            this.previewCanvas.style.height = `${Math.round(fitH)}px`;
            this.previewCanvas.style.transform =
                `translate(${this.previewPanX}px, ${this.previewPanY}px) scale(${this.previewZoom})`;
        }
    },

    startPreview() {
        this.stopPreview();
        this.previewLastTs = 0;
        if (!this.previewSim) this.resetPreviewSim();
        const loop = (ts) => {
            if (!this.visible) return;
            if (!this.previewLastTs) this.previewLastTs = ts;
            const dt = Math.min(50, ts - this.previewLastTs);
            this.previewLastTs = ts;
            this.updatePreviewSim(dt);
            this.drawPreview();
            this.previewAnimId = requestAnimationFrame(loop);
        };
        this.previewAnimId = requestAnimationFrame(loop);
    },

    stopPreview() {
        if (this.previewAnimId) {
            cancelAnimationFrame(this.previewAnimId);
            this.previewAnimId = null;
        }
        this.previewLastTs = 0;
    },

    cleanupPreviewControls() {
        if (this._previewCleanup) {
            this._previewCleanup();
            this._previewCleanup = null;
        }
    },

    resetPreviewSim() {
        const s = this.ships[this.selectedIndex];
        const model = this.getShipModel(s ? s.id : 'player');
        const shipW = Math.round((model.width || 20) * 1.5);
        const shipH = Math.round((model.height || 16) * 1.5);
        this.previewSim = {
            player: {
                x: 100 - shipW / 2,
                y: 250,
                width: shipW,
                height: shipH,
                dir: 1
            },
            bullets: [],
            shootAcc: 0,
            starPhase: 0
        };
        this.previewLastTs = 0;
    },

    updatePreviewSim(dtMs) {
        const sim = this.previewSim;
        const s = this.ships[this.selectedIndex];
        if (!sim || !s) return;
        const frameScale = dtMs / 16.67;
        const model = this.getShipModel(s.id);
        const shipW = Math.round((model.width || 20) * 1.5);
        const shipH = Math.round((model.height || 16) * 1.5);
        const p = sim.player;
        p.width = shipW;
        p.height = shipH;
        const speed = Math.max(0.5, Number(s.speed) || 4) * 0.35;
        p.x += p.dir * speed * frameScale;
        if (p.x <= 8 || p.x + p.width >= 192) {
            p.dir *= -1;
            p.x = Math.max(8, Math.min(192 - p.width, p.x));
        }
        p.y = 250 + Math.sin(sim.starPhase * 1.5) * 3;
        sim.starPhase += dtMs * 0.004;

        sim.shootAcc += dtMs;
        const cooldown = Math.max(80, Number(s.weaponCooldown) || 300);
        if (sim.shootAcc >= cooldown) {
            sim.shootAcc = 0;
            const bulletSpeed = Math.max(2, Number(s.weaponSpeed) || 8);
            sim.bullets.push({
                x: p.x + p.width / 2 - 1,
                y: p.y - 4,
                vy: -bulletSpeed,
                life: 1200
            });
        }
        sim.bullets = sim.bullets.filter((b) => {
            b.y += b.vy * frameScale;
            b.life -= dtMs;
            return b.life > 0 && b.y > -10;
        });
    },

    drawPreview() {
        const ctx = this.previewCtx;
        const canvas = this.previewCanvas;
        const sim = this.previewSim;
        const s = this.ships[this.selectedIndex];
        if (!ctx || !canvas || !sim || !s) return;
        const w = canvas.width;
        const h = canvas.height;
        ctx.fillStyle = '#0a0a0c';
        ctx.fillRect(0, 0, w, h);

        ctx.fillStyle = 'rgba(255,140,40,0.35)';
        for (let i = 0; i < 40; i++) {
            const sx = (i * 47 + sim.starPhase * 20) % w;
            const sy = (i * 73 + sim.starPhase * 8) % h;
            ctx.fillRect(sx, sy, 1, 1);
        }

        ctx.strokeStyle = 'rgba(255,140,40,0.15)';
        ctx.strokeRect(0.5, 0.5, w - 1, h - 1);

        sim.bullets.forEach((b) => {
            ctx.fillStyle = '#ffaa44';
            ctx.fillRect(b.x, b.y, 2, 6);
        });

        const model = this.getShipModel(s.id);
        const p = sim.player;
        if (typeof shipRenderer !== 'undefined') {
            if (shipRenderer.init) shipRenderer.init();
            const tmp = document.createElement('canvas');
            tmp.width = Math.max(1, p.width);
            tmp.height = Math.max(1, p.height);
            shipRenderer.renderShipPreview(tmp, model, 1);
            ctx.drawImage(tmp, p.x, p.y, p.width, p.height);
        } else {
            ctx.fillStyle = '#ff8c28';
            ctx.fillRect(p.x, p.y, p.width, p.height);
        }

        ctx.fillStyle = 'rgba(255,140,40,0.85)';
        ctx.font = '10px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(s.name || 'SHIP', 8, 14);
        ctx.fillText(`SPD ${s.speed}`, 8, 28);
        ctx.fillText(`HP ${s.maxHealth}`, 8, 42);
    },

    renderList() {
        const list = this.overlay && this.overlay.querySelector('#svList');
        if (!list) return;
        list.innerHTML = '';
        this.ships.forEach((ship, index) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'content-viewer-item' + (index === this.selectedIndex ? ' selected' : '');
            btn.innerHTML =
                `<canvas class="cv-icon cv-ship-icon" width="32" height="32" data-ship="${ship.id}"></canvas>` +
                `<span class="cv-item-label">${ship.name}${ship.custom ? ' *' : ''}` +
                (typeof devProfileToggles !== 'undefined' && devProfileToggles.active()
                    ? devProfileToggles.badgesHtml({
                        known: profileManager.isDiscovered('ships', ship.id),
                        owned: profileManager.ownsShip(ship.id)
                    })
                    : '') +
                `</span>`;
            btn.addEventListener('click', () => {
                this.selectedIndex = index;
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
                this.persist();
            });
            list.appendChild(btn);
            const canvas = btn.querySelector('canvas');
            this.paintShipIcon(canvas, ship.id);
        });
        const selected = list.querySelector('.content-viewer-item.selected');
        if (selected) selected.scrollIntoView({ block: 'nearest', behavior: 'auto' });
        this.updateDeleteButton();
    },
});


/* --- js/ui/ship-viewer/stat-icon-html.js --- */
"use strict";

// ShipViewerUI methods, split from ship-viewer.js.
extendClass(ShipViewerUI, {
    statIconHtml(key, size) {
        const px = size || 16;
        if (typeof iconRenderer !== 'undefined') {
            const html = iconRenderer.imgHtml(key, px, 'cv-stat-icon-img');
            if (html) return html;
        }
        return '';
    },

    weaponIconKey(weapon) {
        const w = String(weapon || '').toLowerCase();
        const map = {
            laser: 'shotLaser',
            rapid: 'shotRapid',
            spread: 'shotSpread',
            plasma: 'shotPlasma',
            missile: 'shotMissile',
            ion: 'shotIon',
            wave: 'shotWave',
            burst: 'shotBurst',
            pierce: 'shotPierce',
            nova: 'shotNova'
        };
        return map[w] || 'statWeapon';
    },

    statRowHtml(iconKey, label, value, extraClass, valueClass) {
        const icon = this.statIconHtml(iconKey, 16);
        const cls = extraClass ? ` ${extraClass}` : '';
        const vCls = valueClass ? ` ${valueClass}` : '';
        return `<div class="stat-row${cls}">` +
            `<span class="stat-label"><span class="cv-stat-icon">${icon}</span>${label}</span>` +
            `<span class="stat-value${vCls}">${value}</span>` +
            `</div>`;
    },

    renderDetail() {
        const root = this.overlay && this.overlay.querySelector('#svDetail');
        const s = this.ships[this.selectedIndex];
        if (!root || !s) return;
        const cfg = typeof shipConfigManager !== 'undefined' ? shipConfigManager.getConfig(s.id) : null;
        const abilities = (cfg && cfg.abilities) || [];
        const abilityChips = typeof abilityConfigManager !== 'undefined'
            ? abilityConfigManager.formatAbilityChipsHtml(abilities)
            : (abilities.length ? abilities.join(', ') : '—');
        const weaponKey = this.weaponIconKey(s.weapon);
        root.innerHTML = `
            <div class="content-viewer-hero cv-ship-hero">
                <canvas class="cv-ship-preview" width="64" height="64" id="svHeroCanvas"></canvas>
                <div class="cv-ship-hero-text">
                    <h3 class="content-viewer-name">${s.name}</h3>
                    <p class="content-viewer-desc">${s.description || 'No description.'}</p>
                </div>
            </div>
            <div class="content-viewer-stats cv-stat-clusters">
                <div class="cv-stat-cluster">
                    <div class="cv-stat-cluster-title">Defense</div>
                    ${this.statRowHtml('statHealth', 'Health', s.maxHealth)}
                    ${this.statRowHtml('statArmor', 'Armor', s.armor)}
                </div>
                <div class="cv-stat-cluster">
                    <div class="cv-stat-cluster-title">Combat</div>
                    ${this.statRowHtml('statDamage', 'Damage', s.damage)}
                    ${this.statRowHtml(weaponKey, 'Weapon', String(s.weapon || '—').toUpperCase())}
                </div>
                <div class="cv-stat-cluster">
                    <div class="cv-stat-cluster-title">Mobility</div>
                    ${this.statRowHtml('statSpeed', 'Speed', s.speed)}
                </div>
                <div class="cv-stat-cluster">
                    <div class="cv-stat-cluster-title">Abilities</div>
                    ${this.statRowHtml('statAbilities', 'Abilities', abilityChips, 'stat-row-abilities', 'cv-ability-chips')}
                </div>
            </div>
        `;
        const hero = root.querySelector('#svHeroCanvas');
        this.paintShipIcon(hero, s.id);
        this.updateDeleteButton();
        if (this._devToggles) this._devToggles.refresh();
    },

    updateDeleteButton() {
        const btn = this.overlay && this.overlay.querySelector('#svDelete');
        const s = this.ships[this.selectedIndex];
        if (!btn) return;
        btn.disabled = !(s && s.custom);
        btn.style.opacity = btn.disabled ? '0.4' : '1';
    },

    persist() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            const s = this.ships[this.selectedIndex];
            menuStateManager.setScreen('ship-viewer', { shipId: s ? s.id : 'player' });
        }
    },

    handleKeyDown(e) {
        if (!this.visible) return;
        if (this._devToggles && this._devToggles.handleKey(e)) return;
        if (e.key === 'Escape' && this.previewFullscreen) {
            e.preventDefault();
            this.setPreviewFullscreen(false);
            return;
        }
        switch (e.key) {
            case 'ArrowUp':
            case 'ArrowLeft':
                e.preventDefault();
                this.selectedIndex = Math.max(0, this.selectedIndex - 1);
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
                this.persist();
                break;
            case 'ArrowDown':
            case 'ArrowRight':
                e.preventDefault();
                this.selectedIndex = Math.min(this.ships.length - 1, this.selectedIndex + 1);
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
                this.persist();
                break;
            case 'n':
            case 'N':
                e.preventDefault();
                this.createNew();
                break;
            case 'e':
            case 'E':
            case 'Enter':
                e.preventDefault();
                this.openEditor();
                break;
            case 'Delete':
            case 'Backspace':
                e.preventDefault();
                this.deleteSelected();
                break;
            case 'Escape':
                e.preventDefault();
                this.close();
                break;
        }
    },

    createNew() {
        if (typeof shipConfigManager === 'undefined') return;
        const current = this.ships[this.selectedIndex];
        const ship = shipConfigManager.createShip({
            baseId: current ? current.id : 'player',
            name: 'New Ship'
        });
        this.ships = this.getShipList();
        const idx = this.ships.findIndex((s) => s.id === ship.id);
        this.selectedIndex = idx >= 0 ? idx : this.ships.length - 1;
        this.renderList();
        this.renderDetail();
        this.resetPreviewSim();
        this.persist();
        this.openEditor();
    },

    deleteSelected() {
        const ship = this.ships[this.selectedIndex];
        if (!ship || !ship.custom || typeof shipConfigManager === 'undefined') return;
        shipConfigManager.deleteShip(ship.id);
        this.ships = this.getShipList();
        this.selectedIndex = Math.max(0, Math.min(this.selectedIndex, this.ships.length - 1));
        this.renderList();
        this.renderDetail();
        this.resetPreviewSim();
        this.persist();
    },

    openEditor() {
        const ship = this.ships[this.selectedIndex];
        if (!ship || typeof shipEditorUI === 'undefined') return;
        this.hide();
        shipEditorUI.show(ship.id, undefined, false, { returnTo: 'ship-viewer' });
    },

    openGfxEditor() {
        const ship = this.ships[this.selectedIndex];
        if (!ship || typeof componentEditorUI === 'undefined') return;
        let type = 'ship';
        let id = ship.id;
        if (typeof assetGenRegistry !== 'undefined' && assetGenRegistry.findByKey) {
            const hit = assetGenRegistry.findByKey(ship.id)
                || assetGenRegistry.findByKey(String(ship.id).replace(/_/g, '-'));
            if (hit) {
                type = hit.type;
                id = hit.id;
            }
        }
        const returnCb = this.onClose;
        this.hide();
        componentEditorUI.open({
            type: type,
            id: id,
            returnTo: 'ship-viewer',
            onClose: () => {
                this.show({ onClose: returnCb });
            }
        });
    },

    close() {
        this.hide();
        const container = document.querySelector('.game-container');
        const inGame = container && container.style.display !== 'none';
        if (inGame) {
            if (typeof menuStateManager !== 'undefined') menuStateManager.setScreen('ingame');
            return;
        }
        if (this.onClose) {
            const cb = this.onClose;
            this.onClose = null;
            cb();
            return;
        }
        if (typeof homeStationUI !== 'undefined') {
            homeStationUI.show({
                tab: 'explorations',
                focusExplore: 'ships',
                onClose: () => {
                    if (typeof startScreenManager !== 'undefined') startScreenManager.show();
                }
            });
        } else if (typeof startScreenManager !== 'undefined') {
            startScreenManager.show();
        } else if (typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('start');
        }
    },
});


