"use strict";

// EnemyEditorUI is defined in enemy-editor/core.js and extended by the other files in enemy-editor/,
// which index.html loads before this file.
var enemyEditorUI = new EnemyEditorUI();


/* --- js/ui/ship-editor/core.js --- */
"use strict";

/**
 * Ship Editor — stats, weapons, abilities, live preview.
 * Open: Ships viewer → EDIT / NEW, or Ctrl+Shift+S
 */
var ShipEditorUI = class ShipEditorUI {
    constructor() {
        this.visible = false;
        this.returnTo = null;
        this.selectedType = 'player';
        this.activeTab = 'stats';
        this.previewCanvas = null;
        this.previewCtx = null;
        this.previewAnimId = null;
        this.previewBaseWidth = 360;
        this.previewBaseHeight = 300;
        this.previewBackingScale = 1;
        this.previewZoom = 1;
        this.previewFullscreen = false;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewPanning = false;
        this.previewPanLastX = 0;
        this.previewPanLastY = 0;
        this.previewSim = null;
        this.previewLastTs = 0;
        this.draft = null;
        this.init();
    }

    init() {
        this.ensureOverlay();
        document.addEventListener('keydown', (e) => {
            if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === 's') {
                e.preventDefault();
                this.toggle();
            }
            if (e.key === 'Escape' && this.visible) {
                if (this.previewFullscreen) {
                    e.preventDefault();
                    this.setPreviewFullscreen(false);
                    return;
                }
                this.hide();
            }
        });
    }

    ensureOverlay() {
        if (document.getElementById('shipEditorOverlay')) return;

        const overlay = document.createElement('div');
        overlay.id = 'shipEditorOverlay';
        overlay.className = 'planet-editor-overlay ship-editor-overlay hidden';
        overlay.innerHTML = `
            <div class="planet-editor-panel">
                <div class="planet-editor-header">
                    <h2>SHIP EDITOR</h2>
                    <div class="planet-editor-selected" id="seSelectedLabel"></div>
                </div>
                <div class="planet-editor-tabs" id="seTabs">
                    <button type="button" data-tab="stats" class="pe-tab active">STATS</button>
                    <button type="button" data-tab="weapons" class="pe-tab">WEAPONS</button>
                    <button type="button" data-tab="abilities" class="pe-tab">ABILITIES</button>
                    <button type="button" data-tab="graphics" class="pe-tab">GRAPHICS</button>
                </div>
                <div class="planet-editor-body" id="seEditorBody">
                    <aside class="planet-editor-sidebar" id="seSidebar">
                        <div class="pe-sidebar-title">SHIPS</div>
                        <div class="pe-tree" id="seTypeSelect"></div>
                    </aside>
                    <div class="pe-resize-handle" data-resize="left" title="Resize ship list"></div>
                    <div class="planet-editor-controls" id="seControls"></div>
                    <div class="pe-resize-handle" data-resize="right" title="Resize preview"></div>
                    <div class="planet-editor-preview-wrap" id="sePreviewWrap">
                        <div class="pe-preview-toolbar">
                            <button type="button" class="pe-btn pe-preview-btn" id="seZoomOut" title="Zoom out">−</button>
                            <span class="pe-zoom-label" id="seZoomLabel">100%</span>
                            <button type="button" class="pe-btn pe-preview-btn" id="seZoomIn" title="Zoom in">+</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="seZoomReset" title="Reset zoom">1:1</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="sePreviewFullscreen" title="Fullscreen">FULL</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="seRerollShape" title="Generate new part shapes">REROLL SHAPE</button>
                        </div>
                        <div class="pe-preview-viewport" id="sePreviewViewport">
                            <canvas id="sePreview" width="360" height="300"></canvas>
                        </div>
                        <div class="pe-preview-label">LIVE PREVIEW</div>
                    </div>
                </div>
                <div class="planet-editor-footer">
                    <button type="button" class="pe-btn" id="seNew">NEW</button>
                    <button type="button" class="pe-btn" id="seReset">RESET</button>
                    <button type="button" class="pe-btn pe-primary" id="seSave">SAVE</button>
                    <button type="button" class="pe-btn" id="seClose">CLOSE</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);

        overlay.querySelector('#seTabs').addEventListener('click', (e) => {
            const btn = e.target.closest('[data-tab]');
            if (!btn) return;
            this.activeTab = btn.dataset.tab;
            this.renderTabs();
            this.renderControls();
            this.persistMenuState();
        });
        overlay.querySelector('#seSave').addEventListener('click', () => this.save());
        overlay.querySelector('#seReset').addEventListener('click', () => this.reset());
        overlay.querySelector('#seNew').addEventListener('click', () => this.createNew());
        overlay.querySelector('#seClose').addEventListener('click', () => this.hide());
        overlay.querySelector('#seZoomOut').addEventListener('click', () => this.setPreviewZoom(this.previewZoom - 0.25));
        overlay.querySelector('#seZoomIn').addEventListener('click', () => this.setPreviewZoom(this.previewZoom + 0.25));
        overlay.querySelector('#seZoomReset').addEventListener('click', () => {
            this.previewPanX = 0;
            this.previewPanY = 0;
            this.setPreviewZoom(1);
        });
        overlay.querySelector('#sePreviewFullscreen').addEventListener('click', () => {
            this.setPreviewFullscreen(!this.previewFullscreen);
        });
        overlay.querySelector('#seRerollShape').addEventListener('click', () => this.rerollHullShape());

        const viewport = overlay.querySelector('#sePreviewViewport');
        viewport.addEventListener('wheel', (e) => {
            e.preventDefault();
            const step = e.deltaY < 0 ? 0.1 : -0.1;
            this.setPreviewZoom(this.previewZoom + step);
        }, { passive: false });
        viewport.addEventListener('contextmenu', (e) => e.preventDefault());
        viewport.addEventListener('mousedown', (e) => {
            if (e.button !== 2) return;
            e.preventDefault();
            this.previewPanning = true;
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            viewport.classList.add('pe-panning');
        });
        window.addEventListener('mousemove', (e) => {
            if (!this.previewPanning) return;
            const dx = vfPanDelta(this.previewCanvas, e.clientX - this.previewPanLastX);
            const dy = vfPanDelta(this.previewCanvas, e.clientY - this.previewPanLastY);
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            this.previewPanX += dx;
            this.previewPanY += dy;
            this.applyPreviewView();
        });
        const endPan = () => {
            if (!this.previewPanning) return;
            this.previewPanning = false;
            const vp = document.getElementById('sePreviewViewport');
            if (vp) vp.classList.remove('pe-panning');
        };
        window.addEventListener('mouseup', (e) => {
            if (e.button === 2 || this.previewPanning) endPan();
        });
        window.addEventListener('blur', endPan);
        window.addEventListener('resize', () => {
            if (this.visible) this.applyPreviewView();
        });

        this.previewCanvas = overlay.querySelector('#sePreview');
        this.previewCtx = this.previewCanvas.getContext('2d');
        this.setupPanelResize(overlay);
        this.applyPreviewView();
    }

    setupPanelResize(overlay) {
        const body = overlay.querySelector('#seEditorBody');
        if (!body || typeof setupPanelResize !== 'function') return;
        this._panelResize = setupPanelResize({
            body,
            root: overlay,
            storageKey: 'sePanelWidths',
            defaults: { left: 200, right: 280 },
            mins: { left: 140, right: 180, center: 200 },
            onChange: () => {
                if (this.visible) this.applyPreviewView();
            }
        });
    }

    setPreviewZoom(zoom) {
        this.previewZoom = Math.min(3, Math.max(0.5, Math.round(zoom * 100) / 100));
        this.applyPreviewView();
    }

    setPreviewFullscreen(on) {
        this.previewFullscreen = !!on;
        requestAnimationFrame(() => this.applyPreviewView());
    }

    /** Picks a new random per-part shape combination for the ship being edited. */
    rerollHullShape() {
        if (typeof profileManager === 'undefined' || !profileManager.setHullShapeSeed) return;
        const shipId = this.selectedType;
        if (!shipId) return;
        const seed = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
        profileManager.setHullShapeSeed(shipId, seed);
        // Per-part picks in the shape panel override the seed; clear them too,
        // otherwise a reroll would leave manually-picked parts unchanged.
        if (profileManager.clearSegmentShapeVariant) {
            ['front', 'center', 'back', 'wing', 'wingLeft', 'wingRight'].forEach((seg) => {
                profileManager.clearSegmentShapeVariant(shipId, seg);
            });
        }
        if (this.renderControls) this.renderControls();
        // Animation loop repaints every frame; no forced redraw needed.
    }

    applyPreviewView() {
        const wrap = document.getElementById('sePreviewWrap');
        const label = document.getElementById('seZoomLabel');
        const fsBtn = document.getElementById('sePreviewFullscreen');
        const viewport = document.getElementById('sePreviewViewport');
        if (wrap) wrap.classList.toggle('pe-preview-fs', this.previewFullscreen);
        if (label) label.textContent = `${Math.round(this.previewZoom * 100)}%`;
        if (fsBtn) fsBtn.textContent = this.previewFullscreen ? 'EXIT' : 'FULL';
        if (this.previewCanvas && viewport) {
            const pad = 8;
            const availW = Math.max(140, viewport.clientWidth - pad);
            const availH = Math.max(200, viewport.clientHeight - pad);
            const aspect = this.previewBaseWidth / this.previewBaseHeight;
            let fitW = availW;
            let fitH = fitW / aspect;
            if (fitH > availH) {
                fitH = availH;
                fitW = fitH * aspect;
            }
            const cssW = fitW * this.previewZoom;
            const cssH = fitH * this.previewZoom;
            const dpr = window.devicePixelRatio || 1;
            // Bake zoom into the canvas backing store so pixel art is regenerated
            // crisp at the target resolution instead of CSS-stretching a fixed bitmap.
            this.previewBackingScale = (cssW * dpr) / this.previewBaseWidth;
            // Global Pixel Size: one backing pixel == gp screen px.
            const gpx = (typeof uiAppearanceManager !== 'undefined' && uiAppearanceManager.getGlobalPixelPx)
                ? uiAppearanceManager.getGlobalPixelPx() : 0;
            if (gpx > 0) this.previewBackingScale = cssW / (gpx * this.previewBaseWidth);
            const backingW = Math.max(1, Math.round(this.previewBaseWidth * this.previewBackingScale));
            const backingH = Math.max(1, Math.round(this.previewBaseHeight * this.previewBackingScale));
            if (this.previewCanvas.width !== backingW || this.previewCanvas.height !== backingH) {
                this.previewCanvas.width = backingW;
                this.previewCanvas.height = backingH;
            }
            this.previewCanvas.style.width = `${Math.round(cssW)}px`;
            this.previewCanvas.style.height = `${Math.round(cssH)}px`;
            this.previewCanvas.style.transform = `translate(${this.previewPanX}px, ${this.previewPanY}px)`;
        }
    }

    persistMenuState() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            menuStateManager.setScreen('ship-editor', {
                shipId: this.selectedType,
                tab: this.activeTab,
                returnTo: this.returnTo
            });
        }
    }

    toggle() {
        if (this.visible) this.hide();
        else this.show();
    }
}


/* --- js/ui/ship-editor/show.js --- */
"use strict";

// ShipEditorUI methods, split from ship-editor.js.
extendClass(ShipEditorUI, {
    show(typeId, tab, fromRestore, options) {
        this.ensureOverlay();
        if (typeId) this.selectedType = String(typeId);
        if (tab) this.activeTab = tab;
        if (options && options.returnTo) this.returnTo = options.returnTo;
        else if (!fromRestore) this.returnTo = null;
        this.loadDraft();
        this.visible = true;
        document.getElementById('shipEditorOverlay').classList.remove('hidden');
        this.renderTypeSelect();
        this.renderTabs();
        this.renderControls();
        this.resetPreviewSim();
        this.previewZoom = 1;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.applyPreviewView();
        requestAnimationFrame(() => this.applyPreviewView());
        this.startPreview();
        if (!fromRestore && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('ship-editor', {
                shipId: this.selectedType,
                tab: this.activeTab,
                returnTo: this.returnTo
            });
        }
    },

    hide() {
        this.visible = false;
        this.setPreviewFullscreen(false);
        const el = document.getElementById('shipEditorOverlay');
        if (el) el.classList.add('hidden');
        this.stopPreview();
        const backTo = this.returnTo;
        this.returnTo = null;
        if (backTo === 'ship-viewer' && typeof shipViewerUI !== 'undefined') {
            shipViewerUI.show({ shipId: this.selectedType });
            return;
        }
        if (typeof menuStateManager !== 'undefined') {
            const container = document.querySelector('.game-container');
            const inGame = container && container.style.display !== 'none';
            menuStateManager.setScreen(inGame ? 'ingame' : 'start');
        }
    },

    loadDraft() {
        if (typeof shipConfigManager === 'undefined') {
            this.draft = {
                id: this.selectedType,
                name: this.selectedType,
                description: '',
                modelClass: 'starfighter',
                speed: 4,
                maxHealth: 100,
                armor: 15,
                damage: 25,
                minY: 0,
                maxY: 284,
                defaultWeapon: 'laser',
                availableWeapons: ['laser'],
                weaponDamage: 10,
                weaponSpeed: 8,
                weaponCooldown: 300,
                abilities: [],
                tier: 1,
                cost: 0
            };
            return;
        }
        this.draft = JSON.parse(JSON.stringify(shipConfigManager.getConfig(this.selectedType)));
    },

    createNew() {
        if (typeof shipConfigManager === 'undefined') return;
        const ship = shipConfigManager.createShip({
            baseId: this.selectedType,
            name: 'New Ship'
        });
        this.selectedType = ship.id;
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        this.resetPreviewSim();
        this.persistMenuState();
    },

    renderTypeSelect() {
        const root = document.getElementById('seTypeSelect');
        const label = document.getElementById('seSelectedLabel');
        if (!root) return;
        root.innerHTML = '';
        const types = typeof shipConfigManager !== 'undefined'
            ? shipConfigManager.getTypeIds()
            : ['player', 'player_interceptor', 'player_heavy', 'player_assault'];
        types.forEach((id) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'pe-planet-btn' + (id === this.selectedType ? ' active' : '');
            btn.style.width = '100%';
            btn.style.textAlign = 'left';
            btn.textContent = typeof shipConfigManager !== 'undefined'
                ? shipConfigManager.getDisplayName(id)
                : id.toUpperCase();
            btn.addEventListener('click', () => {
                this.selectedType = id;
                this.loadDraft();
                this.renderTypeSelect();
                this.renderControls();
                this.resetPreviewSim();
                this.persistMenuState();
            });
            root.appendChild(btn);
        });
        if (label) {
            const name = typeof shipConfigManager !== 'undefined'
                ? shipConfigManager.getDisplayName(this.selectedType)
                : this.selectedType;
            label.textContent = name || this.selectedType;
        }
    },

    renderTabs() {
        const tabs = document.querySelectorAll('#seTabs .pe-tab');
        tabs.forEach((tab) => {
            tab.classList.toggle('active', tab.dataset.tab === this.activeTab);
        });
    },

    renderControls() {
        const root = document.getElementById('seControls');
        if (!root || !this.draft) return;
        root.innerHTML = '';

        if (this.activeTab === 'stats') this.renderStatsTab(root);
        else if (this.activeTab === 'weapons') this.renderWeaponsTab(root);
        else if (this.activeTab === 'abilities') this.renderAbilitiesTab(root);
        else this.renderGraphicsTab(root);
    },

    renderStatsTab(root) {
        root.appendChild(this.makeTextInput('Name', this.draft.name || '', (v) => {
            this.draft.name = v;
        }));
        root.appendChild(this.makeTextInput('Description', this.draft.description || '', (v) => {
            this.draft.description = v;
        }));
        const modelClasses = ['starfighter', 'interceptor', 'heavy_fighter', 'assault'];
        root.appendChild(this.makeSelect('Model class', this.draft.modelClass || 'starfighter', modelClasses, (v) => {
            this.draft.modelClass = v;
            this.resetPreviewSim();
        }));
        root.appendChild(this.makeSlider('Max health', this.draft.maxHealth, 20, 400, 5, (v) => {
            this.draft.maxHealth = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Armor', this.draft.armor, 0, 100, 1, (v) => {
            this.draft.armor = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Damage', this.draft.damage, 1, 100, 1, (v) => {
            this.draft.damage = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Speed', this.draft.speed, 0.5, 10, 0.1, (v) => {
            this.draft.speed = v;
        }));
        root.appendChild(this.makeSlider('Min Y', this.draft.minY, 100, 280, 1, (v) => {
            this.draft.minY = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Max Y', this.draft.maxY, 150, 320, 1, (v) => {
            this.draft.maxY = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Tier', this.draft.tier, 1, 5, 1, (v) => {
            this.draft.tier = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Cost', this.draft.cost, 0, 500, 5, (v) => {
            this.draft.cost = Math.round(v);
        }));
    },

    renderWeaponsTab(root) {
        const weapons = typeof shipConfigManager !== 'undefined'
            ? shipConfigManager.availableWeapons
            : ['laser', 'plasma', 'spread', 'rapid'];
        if (!this.draft.weaponConfig) this.draft.weaponConfig = {};
        const ensureWeaponConfig = (id) => {
            if (!this.draft.weaponConfig[id]) {
                const defaults = (typeof weaponConfigManager !== 'undefined'
                    && weaponConfigManager.getDefaultsForShip)
                    ? weaponConfigManager.getDefaultsForShip(id) : {};
                this.draft.weaponConfig[id] = Object.assign({}, defaults);
            }
            return this.draft.weaponConfig[id];
        };

        root.appendChild(this.makeSelect('Default weapon', this.draft.defaultWeapon || 'laser', weapons, (v) => {
            this.draft.defaultWeapon = v;
            if (this.draft.availableWeapons.indexOf(v) === -1) {
                this.draft.availableWeapons.push(v);
                this.renderControls();
            }
        }));

        const listTitle = document.createElement('div');
        listTitle.className = 'pe-row';
        listTitle.innerHTML = '<label>Available weapons</label>';
        root.appendChild(listTitle);

        weapons.forEach((w) => {
            const on = this.draft.availableWeapons.indexOf(w) !== -1;
            root.appendChild(this.makeCheckbox(w.toUpperCase(), on, (checked) => {
                if (checked) {
                    if (this.draft.availableWeapons.indexOf(w) === -1) {
                        this.draft.availableWeapons.push(w);
                    }
                    ensureWeaponConfig(w);
                } else {
                    this.draft.availableWeapons = this.draft.availableWeapons.filter((x) => x !== w);
                    if (!this.draft.availableWeapons.length) {
                        this.draft.availableWeapons = [this.draft.defaultWeapon || 'laser'];
                    }
                    if (this.draft.availableWeapons.indexOf(this.draft.defaultWeapon) === -1) {
                        this.draft.defaultWeapon = this.draft.availableWeapons[0];
                    }
                }
                this.renderControls();
            }));
            if (on) {
                const cfg = ensureWeaponConfig(w);
                const details = document.createElement('details');
                details.className = 'pe-weapon-details';
                details.open = false;
                const summary = document.createElement('summary');
                summary.textContent = 'CONFIGURE ' + w.toUpperCase();
                details.appendChild(summary);
                details.appendChild(this.makeSlider('Damage', cfg.damage || this.draft.weaponDamage || 1,
                    1, 150, 1, (v) => { cfg.damage = Math.round(v); }));
                details.appendChild(this.makeSlider('Speed', cfg.speed || this.draft.weaponSpeed || 1,
                    1, 20, 0.5, (v) => { cfg.speed = v; }));
                details.appendChild(this.makeSlider('Cooldown (ms)', cfg.cooldown || this.draft.weaponCooldown || 100,
                    50, 4000, 10, (v) => { cfg.cooldown = Math.round(v); }));
                root.appendChild(details);
            }
        });

        root.appendChild(this.makeSlider('Weapon damage', this.draft.weaponDamage, 1, 60, 1, (v) => {
            this.draft.weaponDamage = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Weapon speed', this.draft.weaponSpeed, 1, 20, 0.5, (v) => {
            this.draft.weaponSpeed = v;
        }));
        root.appendChild(this.makeSlider('Weapon cooldown (ms)', this.draft.weaponCooldown, 50, 2000, 10, (v) => {
            this.draft.weaponCooldown = Math.round(v);
        }));
    },

    renderGraphicsTab(root) {
        this.renderShapeControls(root, this.selectedType);
        const wing = Object.assign(
            { x: 0.02, y: 0.30, w: 0.24, h: 0.40 },
            this.draft.segmentUv && this.draft.segmentUv.wing
        );
        const setWing = (key, value) => {
            this.draft.segmentUv = Object.assign({}, this.draft.segmentUv || {}, {
                wing: Object.assign({}, wing, { [key]: value })
            });
            this.resetPreviewSim();
        };
        root.appendChild(this.makeSlider('Wing crop X', wing.x, 0, 0.9, 0.01, (v) => setWing('x', v)));
        root.appendChild(this.makeSlider('Wing crop Y', wing.y, 0, 0.9, 0.01, (v) => setWing('y', v)));
        root.appendChild(this.makeSlider('Wing crop width', wing.w, 0.05, 1, 0.01, (v) => setWing('w', v)));
        root.appendChild(this.makeSlider('Wing crop height', wing.h, 0.05, 1, 0.01, (v) => setWing('h', v)));
        const hint = document.createElement('p');
        hint.className = 'pe-hint';
        hint.textContent = 'Crop the wing from the ship graphic set. Smaller width/height removes fuselage pixels.';
        root.appendChild(hint);
    },

    /**
     * Simple per-part shape picker: named variants for nose/core/aft plus
     * wing style, instead of only the black-box "REROLL SHAPE" button.
     * Shared pattern with the enemy editor's own copy of this method.
     */
    renderShapeControls(root, shipId) {
        const loader = typeof graphicsManager !== 'undefined' && graphicsManager.shipAssetLoader;
        if (!loader || !shipId || typeof profileManager === 'undefined') return;
        const title = document.createElement('p');
        title.className = 'pe-hint';
        title.textContent = 'Pick a named shape per part, or randomize the whole hull.';
        root.appendChild(title);

        const segmentRow = (segId, label, labels) => {
            const current = profileManager.getSegmentShapeVariant(shipId, segId);
            const options = ['AUTO'].concat(labels);
            const value = current != null && labels[current] ? labels[current] : 'AUTO';
            root.appendChild(this.makeSelect(label, value, options, (v) => {
                if (v === 'AUTO') profileManager.clearSegmentShapeVariant(shipId, segId);
                else profileManager.setSegmentShapeVariant(shipId, segId, labels.indexOf(v));
                this.resetPreviewSim();
            }));
        };
        segmentRow('front', 'Nose shape', loader.bodyShapeVariantLabels('front'));
        segmentRow('center', 'Core shape', loader.bodyShapeVariantLabels('center'));
        segmentRow('back', 'Aft shape', loader.bodyShapeVariantLabels('back'));

        const symmetric = profileManager.getWingStyleSymmetry(shipId);
        root.appendChild(this.makeCheckbox('Mirror wings', symmetric, (checked) => {
            profileManager.setWingStyleSymmetry(shipId, checked);
            this.resetPreviewSim();
        }));
        const wingLabels = loader.wingShapeVariants.map((v) => v.label);
        segmentRow(symmetric ? 'wing' : 'wingLeft', symmetric ? 'Wing shape' : 'Left wing shape', wingLabels);
        if (!symmetric) segmentRow('wingRight', 'Right wing shape', wingLabels);

        const reroll = document.createElement('button');
        reroll.type = 'button';
        reroll.className = 'pe-btn';
        reroll.textContent = 'RANDOMIZE ALL';
        reroll.addEventListener('click', () => this.rerollHullShape());
        root.appendChild(reroll);
    },

    getAbilityMeta(id) {
        if (typeof abilityConfigManager !== 'undefined') {
            return abilityConfigManager.getMeta(id);
        }
        return { icon: '◆', cluster: 'other', name: id };
    },

    getSharedAbilityIds() {
        if (typeof abilityConfigManager !== 'undefined') {
            return abilityConfigManager.getIds();
        }
        if (typeof shipConfigManager !== 'undefined') {
            return shipConfigManager.availableAbilities || [];
        }
        return [];
    },
});


/* --- js/ui/ship-editor/render-abilities-tab.js --- */
"use strict";

// ShipEditorUI methods, split from ship-editor.js.
extendClass(ShipEditorUI, {
    renderAbilitiesTab(root) {
        const abilities = this.getSharedAbilityIds();
        const current = this.draft.abilities || [];
        const clusterOrder = typeof abilityConfigManager !== 'undefined'
            ? abilityConfigManager.clusterOrder
            : [
                { id: 'core', label: 'CORE' },
                { id: 'mobility', label: 'MOBILITY' },
                { id: 'offense', label: 'OFFENSE' },
                { id: 'defense', label: 'DEFENSE' },
                { id: 'combat', label: 'COMBAT' },
                { id: 'other', label: 'OTHER' }
            ];
        const grouped = {};
        abilities.forEach((a) => {
            const cluster = this.getAbilityMeta(a).cluster;
            if (!grouped[cluster]) grouped[cluster] = [];
            grouped[cluster].push(a);
        });

        clusterOrder.forEach((cluster) => {
            const list = grouped[cluster.id];
            if (!list || !list.length) return;

            const group = document.createElement('div');
            group.className = 'pe-ability-group';
            const title = document.createElement('div');
            title.className = 'pe-ability-group-title';
            title.textContent = cluster.label;
            group.appendChild(title);

            list.forEach((a) => {
                const on = current.indexOf(a) !== -1;
                const meta = this.getAbilityMeta(a);
                const label = meta.name || a.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
                group.appendChild(this.makeCheckbox(label, on, (checked) => {
                    if (!Array.isArray(this.draft.abilities)) this.draft.abilities = [];
                    if (checked) {
                        if (this.draft.abilities.indexOf(a) === -1) this.draft.abilities.push(a);
                    } else {
                        this.draft.abilities = this.draft.abilities.filter((x) => x !== a);
                    }
                }, meta.icon));
            });

            root.appendChild(group);
        });
    },

    makeSlider(labelText, value, min, max, step, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const val = document.createElement('span');
        val.className = 'pe-val';
        const format = (v) => (step < 1 ? Number(v).toFixed(2) : String(Math.round(v)));
        val.textContent = format(value);
        const input = document.createElement('input');
        input.type = 'range';
        input.min = String(min);
        input.max = String(max);
        input.step = String(step);
        input.value = String(value);
        input.addEventListener('input', () => {
            const v = Number(input.value);
            val.textContent = format(v);
            onChange(v);
        });
        row.appendChild(label);
        row.appendChild(val);
        row.appendChild(input);
        return row;
    },

    makeSelect(labelText, value, options, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const select = document.createElement('select');
        options.forEach((opt) => {
            const o = document.createElement('option');
            o.value = opt;
            o.textContent = opt;
            if (opt === value) o.selected = true;
            select.appendChild(o);
        });
        select.addEventListener('change', () => onChange(select.value));
        row.appendChild(label);
        row.appendChild(select);
        return row;
    },

    makeTextInput(labelText, value, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const input = document.createElement('input');
        input.type = 'text';
        input.value = value;
        input.className = 'pe-text-input';
        input.addEventListener('input', () => onChange(input.value));
        row.appendChild(label);
        row.appendChild(input);
        return row;
    },

    makeCheckbox(labelText, checked, onChange, icon) {
        const row = document.createElement('div');
        row.className = 'pe-row pe-row-check';
        const label = document.createElement('label');
        if (icon) {
            const iconEl = document.createElement('span');
            iconEl.className = 'pe-ability-icon';
            if (typeof abilityConfigManager !== 'undefined' && String(icon).indexOf('ability_') === 0) {
                iconEl.innerHTML = abilityConfigManager.resolveIconHtml(icon, 16, 'cv-ability-icon-img');
            } else {
                iconEl.textContent = icon;
            }
            label.appendChild(iconEl);
            label.appendChild(document.createTextNode(labelText));
        } else {
            label.textContent = labelText;
        }
        const input = document.createElement('input');
        input.type = 'checkbox';
        input.checked = !!checked;
        input.addEventListener('change', () => onChange(input.checked));
        row.appendChild(label);
        row.appendChild(input);
        return row;
    },

    save() {
        if (typeof shipConfigManager === 'undefined' || !this.draft) return;
        shipConfigManager.setConfig(this.selectedType, this.draft);
        shipConfigManager.applyToRuntime(this.selectedType);
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        const header = document.querySelector('#shipEditorOverlay .planet-editor-header h2');
        if (header) {
            const prev = header.textContent;
            header.textContent = 'SAVED';
            setTimeout(() => { header.textContent = prev || 'SHIP EDITOR'; }, 700);
        }
    },

    reset() {
        if (typeof shipConfigManager === 'undefined') return;
        shipConfigManager.resetConfig(this.selectedType);
        this.loadDraft();
        this.renderControls();
        this.resetPreviewSim();
    },

    startPreview() {
        this.stopPreview();
        this.previewLastTs = 0;
        if (!this.previewSim) this.resetPreviewSim();
        const loop = (ts) => {
            if (!this.visible) return;
            if (!this.previewLastTs) this.previewLastTs = ts;
            const dt = Math.min(50, ts - this.previewLastTs);
            this.previewLastTs = ts;
            this.updatePreviewSim(dt);
            this.drawPreview();
            this.previewAnimId = requestAnimationFrame(loop);
        };
        this.previewAnimId = requestAnimationFrame(loop);
    },

    stopPreview() {
        if (this.previewAnimId) {
            cancelAnimationFrame(this.previewAnimId);
            this.previewAnimId = null;
        }
        this.previewLastTs = 0;
    },

    getPreviewModel() {
        let base = null;
        if (typeof shipConfigManager !== 'undefined') {
            base = shipConfigManager.getBaseModel(this.selectedType);
            if (this.draft && this.draft.modelClass && base) {
                const classMap = {
                    starfighter: 'player',
                    interceptor: 'player_interceptor',
                    heavy_fighter: 'player_heavy',
                    assault: 'player_assault'
                };
                const key = classMap[this.draft.modelClass];
                if (key && typeof graphicsManager !== 'undefined' && graphicsManager.shipAssetLoader) {
                    const alt = graphicsManager.shipAssetLoader.getShip(key);
                    if (alt) base = alt;
                }
            }
        }
        return Object.assign({}, base || {
            width: 20,
            height: 16,
            type: 'player',
            modelClass: 'starfighter',
            sprite: null
        }, {
            id: this.selectedType,
            name: this.draft && this.draft.name,
            speed: this.draft && this.draft.speed,
            maxHealth: this.draft && this.draft.maxHealth,
            armor: this.draft && this.draft.armor,
            damage: this.draft && this.draft.damage,
            modelClass: this.draft && this.draft.modelClass
        });
    },

    resetPreviewSim() {
        const w = this.previewBaseWidth || 360;
        const h = this.previewBaseHeight || 300;
        const model = this.getPreviewModel();
        const shipW = Math.round((model.width || 20) * 1.5);
        const shipH = Math.round((model.height || 16) * 1.5);
        this.previewSim = {
            player: {
                x: w / 2 - shipW / 2,
                y: h - 50,
                width: shipW,
                height: shipH,
                vx: 1.2,
                dir: 1
            },
            bullets: [],
            shootAcc: 0,
            starPhase: 0
        };
        this.previewLastTs = 0;
    },
});


/* --- js/ui/ship-editor/update-preview-sim.js --- */
"use strict";

// ShipEditorUI methods, split from ship-editor.js.
extendClass(ShipEditorUI, {
    updatePreviewSim(dtMs) {
        const sim = this.previewSim;
        const d = this.draft;
        if (!sim || !d) return;
        const frameScale = dtMs / 16.67;
        const model = this.getPreviewModel();
        const shipW = Math.round((model.width || 20) * 1.5);
        const shipH = Math.round((model.height || 16) * 1.5);
        const p = sim.player;
        p.width = shipW;
        p.height = shipH;
        const w = this.previewBaseWidth || 360;
        const h = this.previewBaseHeight || 300;
        const speed = Math.max(0.5, Number(d.speed) || 4) * 0.35;
        p.x += p.dir * speed * frameScale;
        if (p.x <= 8 || p.x + p.width >= w - 8) {
            p.dir *= -1;
            p.x = Math.max(8, Math.min(w - 8 - p.width, p.x));
        }
        p.y = h - 50 + Math.sin(sim.starPhase * 1.5) * 3;
        sim.starPhase += dtMs * 0.004;

        sim.shootAcc += dtMs;
        const cooldown = Math.max(80, Number(d.weaponCooldown) || 300);
        if (sim.shootAcc >= cooldown) {
            sim.shootAcc = 0;
            const bulletSpeed = Math.max(2, Number(d.weaponSpeed) || 8);
            sim.bullets.push({
                x: p.x + p.width / 2 - 1,
                y: p.y - 4,
                vy: -bulletSpeed,
                life: 1200
            });
        }
        sim.bullets = sim.bullets.filter((b) => {
            b.y += b.vy * frameScale;
            b.life -= dtMs;
            return b.life > 0 && b.y > -10;
        });
    },

    drawPreview() {
        const ctx = this.previewCtx;
        const canvas = this.previewCanvas;
        const sim = this.previewSim;
        if (!ctx || !canvas || !sim) return;
        const w = this.previewBaseWidth;
        const h = this.previewBaseHeight;
        const backingScale = this.previewBackingScale || 1;
        ctx.imageSmoothingEnabled = false;
        ctx.save();
        ctx.scale(backingScale, backingScale);
        ctx.fillStyle = '#0a0a0c';
        ctx.fillRect(0, 0, w, h);

        ctx.fillStyle = 'rgba(255,140,40,0.35)';
        for (let i = 0; i < 40; i++) {
            const sx = (i * 47 + sim.starPhase * 20) % w;
            const sy = (i * 73 + sim.starPhase * 8) % h;
            ctx.fillRect(sx, sy, 1, 1);
        }

        ctx.strokeStyle = 'rgba(255,140,40,0.15)';
        ctx.strokeRect(0.5, 0.5, w - 1, h - 1);

        sim.bullets.forEach((b) => {
            ctx.fillStyle = '#ffaa44';
            ctx.fillRect(b.x, b.y, 2, 6);
        });

        const model = this.getPreviewModel();
        const p = sim.player;
        if (typeof shipRenderer !== 'undefined') {
            if (shipRenderer.init) shipRenderer.init();
            const tmp = document.createElement('canvas');
            // Size the offscreen ship canvas to the actual backing-store density
            // (not the fixed logical p.width/height) so the hull/module pixels
            // regenerate crisp at the current zoom instead of being upscaled.
            tmp.width = Math.max(1, Math.round(p.width * backingScale));
            tmp.height = Math.max(1, Math.round(p.height * backingScale));
            shipRenderer.renderShipPreview(tmp, model, 1);
            ctx.drawImage(tmp, p.x, p.y, p.width, p.height);
        } else if (model.sprite) {
            const scale = Math.max(1, Math.floor(p.width / (model.width || 20)));
            for (let row = 0; row < model.sprite.length; row++) {
                for (let col = 0; col < model.sprite[row].length; col++) {
                    const pixel = model.sprite[row][col];
                    if (!pixel) continue;
                    ctx.fillStyle = (model.colors && model.colors[pixel]) || '#ccc';
                    ctx.fillRect(p.x + col * scale, p.y + row * scale, scale, scale);
                }
            }
        } else {
            ctx.fillStyle = '#ff8c28';
            ctx.fillRect(p.x, p.y, p.width, p.height);
        }

        ctx.fillStyle = 'rgba(255,140,40,0.85)';
        ctx.font = '10px monospace';
        ctx.fillText((this.draft && this.draft.name) || 'SHIP', 8, 14);
        ctx.fillText(`SPD ${this.draft ? this.draft.speed : 0}`, 8, 28);
        ctx.fillText(`HP ${this.draft ? this.draft.maxHealth : 0}`, 8, 42);
        ctx.restore();
    },
});


/* --- js/ui/ship-editor.js --- */
"use strict";

// ShipEditorUI is defined in ship-editor/core.js and extended by the other files in ship-editor/,
// which index.html loads before this file.
var shipEditorUI = new ShipEditorUI();


/* --- js/ui/ability-editor.js --- */
"use strict";

/**
 * Ability Editor — edit shared ability metadata (icon, cluster, type, …).
 * Open: Abilities viewer → EDIT / NEW
 */
var AbilityEditorUI = class AbilityEditorUI {
    constructor() {
        this.visible = false;
        this.returnTo = null;
        this.selectedId = 'player_control';
        this.draft = null;
    }

    init() {
        this.ensureOverlay();
    }

    ensureOverlay() {
        if (document.getElementById('abilityEditorOverlay')) return;

        const overlay = document.createElement('div');
        overlay.id = 'abilityEditorOverlay';
        overlay.className = 'planet-editor-overlay ability-editor-overlay hidden';
        overlay.innerHTML = `
            <div class="planet-editor-panel">
                <div class="planet-editor-header">
                    <h2>ABILITY EDITOR</h2>
                    <div class="planet-editor-planet-select" id="aeTypeSelect"></div>
                </div>
                <div class="planet-editor-body ae-body-single">
                    <div class="planet-editor-controls" id="aeControls"></div>
                </div>
                <div class="planet-editor-footer">
                    <button type="button" class="pe-btn" id="aeNew">NEW</button>
                    <button type="button" class="pe-btn" id="aeReset">RESET</button>
                    <button type="button" class="pe-btn pe-primary" id="aeSave">SAVE</button>
                    <button type="button" class="pe-btn" id="aeClose">CLOSE</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);

        overlay.querySelector('#aeSave').addEventListener('click', () => this.save());
        overlay.querySelector('#aeReset').addEventListener('click', () => this.reset());
        overlay.querySelector('#aeNew').addEventListener('click', () => this.createNew());
        overlay.querySelector('#aeClose').addEventListener('click', () => this.hide());

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.visible) {
                e.preventDefault();
                this.hide();
            }
        });
    }

    persistMenuState() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            menuStateManager.setScreen('ability-editor', {
                abilityId: this.selectedId,
                returnTo: this.returnTo
            });
        }
    }

    show(abilityId, fromRestore, options) {
        this.ensureOverlay();
        if (abilityId) this.selectedId = String(abilityId);
        if (options && options.returnTo) this.returnTo = options.returnTo;
        else if (!fromRestore) this.returnTo = null;
        this.loadDraft();
        this.visible = true;
        document.getElementById('abilityEditorOverlay').classList.remove('hidden');
        this.renderTypeSelect();
        this.renderControls();
        if (!fromRestore && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('ability-editor', {
                abilityId: this.selectedId,
                returnTo: this.returnTo
            });
        }
    }

    hide() {
        this.visible = false;
        const el = document.getElementById('abilityEditorOverlay');
        if (el) el.classList.add('hidden');
        const backTo = this.returnTo;
        this.returnTo = null;
        if (backTo === 'ability-viewer' && typeof abilityViewerUI !== 'undefined') {
            abilityViewerUI.show({ abilityId: this.selectedId });
            return;
        }
        if (backTo === 'defense-viewer' && typeof defenseViewerUI !== 'undefined') {
            defenseViewerUI.show({ defenseId: this.selectedId });
            return;
        }
        if (typeof menuStateManager !== 'undefined') {
            const container = document.querySelector('.game-container');
            const inGame = container && container.style.display !== 'none';
            menuStateManager.setScreen(inGame ? 'ingame' : 'start');
        }
    }

    loadDraft() {
        if (typeof abilityConfigManager === 'undefined') {
            this.draft = {
                id: this.selectedId,
                name: this.selectedId,
                description: '',
                icon: '◆',
                cluster: 'other',
                type: 'passive',
                tier: 1,
                uiDescription: '',
                custom: false
            };
            return;
        }
        this.draft = JSON.parse(JSON.stringify(abilityConfigManager.getAbility(this.selectedId)));
    }

    createNew() {
        if (typeof abilityConfigManager === 'undefined') return;
        const ability = abilityConfigManager.createAbility({ name: 'New Ability' });
        this.selectedId = ability.id;
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        this.persistMenuState();
    }

    renderTypeSelect() {
        const root = document.getElementById('aeTypeSelect');
        if (!root) return;
        root.innerHTML = '';
        const ids = typeof abilityConfigManager !== 'undefined'
            ? abilityConfigManager.getIds()
            : [this.selectedId];
        ids.forEach((id) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'pe-planet-btn' + (id === this.selectedId ? ' active' : '');
            const meta = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.getAbility(id)
                : { icon: '◆', name: id };
            const iconHtml = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.resolveIconHtml(meta.icon, 14, 'cv-ability-icon-img')
                : meta.icon;
            btn.innerHTML = `${iconHtml} <span>${meta.name}</span>`;
            btn.addEventListener('click', () => {
                this.selectedId = id;
                this.loadDraft();
                this.renderTypeSelect();
                this.renderControls();
                this.persistMenuState();
            });
            root.appendChild(btn);
        });
    }

    renderControls() {
        const root = document.getElementById('aeControls');
        if (!root || !this.draft) return;
        root.innerHTML = '';

        const preview = document.createElement('div');
        preview.className = 'ae-preview';
        preview.innerHTML = `<span class="ae-preview-icon">${typeof abilityConfigManager !== 'undefined' ? abilityConfigManager.resolveIconHtml(this.draft.icon || '◆', 32, 'cv-ability-icon-img') : (this.draft.icon || '◆')}</span>` +
            `<span class="ae-preview-name">${this.draft.name || this.draft.id}</span>`;
        root.appendChild(preview);

        root.appendChild(this.makeTextInput('Name', this.draft.name || '', (v) => {
            this.draft.name = v;
            this.updatePreview();
        }));
        root.appendChild(this.makeTextInput('Icon key', this.draft.icon || '', (v) => {
            this.draft.icon = v || '◆';
            this.updatePreview();
        }));
        root.appendChild(this.makeTextInput('Description', this.draft.description || '', (v) => {
            this.draft.description = v;
        }));
        root.appendChild(this.makeTextInput('UI summary', this.draft.uiDescription || '', (v) => {
            this.draft.uiDescription = v;
        }));

        const clusters = (typeof abilityConfigManager !== 'undefined'
            ? abilityConfigManager.clusterOrder.map((c) => c.id)
            : ['core', 'mobility', 'offense', 'defense', 'combat', 'other']);
        root.appendChild(this.makeSelect('Cluster', this.draft.cluster || 'other', clusters, (v) => {
            this.draft.cluster = v;
        }));
        root.appendChild(this.makeSelect('Type', this.draft.type || 'passive', ['passive', 'active'], (v) => {
            this.draft.type = v;
        }));
        root.appendChild(this.makeSlider('Tier', this.draft.tier || 1, 1, 5, 1, (v) => {
            this.draft.tier = Math.round(v);
        }));
    }

    updatePreview() {
        const icon = document.querySelector('#aeControls .ae-preview-icon');
        const name = document.querySelector('#aeControls .ae-preview-name');
        if (icon) {
            icon.innerHTML = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.resolveIconHtml(this.draft.icon || '◆', 32, 'cv-ability-icon-img')
                : (this.draft.icon || '◆');
        }
        if (name) name.textContent = this.draft.name || this.draft.id;
    }

    makeSlider(labelText, value, min, max, step, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const val = document.createElement('span');
        val.className = 'pe-val';
        const format = (v) => (step < 1 ? Number(v).toFixed(2) : String(Math.round(v)));
        val.textContent = format(value);
        const input = document.createElement('input');
        input.type = 'range';
        input.min = String(min);
        input.max = String(max);
        input.step = String(step);
        input.value = String(value);
        input.addEventListener('input', () => {
            const v = Number(input.value);
            val.textContent = format(v);
            onChange(v);
        });
        row.appendChild(label);
        row.appendChild(val);
        row.appendChild(input);
        return row;
    }

    makeSelect(labelText, value, options, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const select = document.createElement('select');
        options.forEach((opt) => {
            const o = document.createElement('option');
            o.value = opt;
            o.textContent = opt;
            if (opt === value) o.selected = true;
            select.appendChild(o);
        });
        select.addEventListener('change', () => onChange(select.value));
        row.appendChild(label);
        row.appendChild(select);
        return row;
    }

    makeTextInput(labelText, value, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const input = document.createElement('input');
        input.type = 'text';
        input.value = value;
        input.className = 'pe-text-input';
        input.addEventListener('input', () => onChange(input.value));
        row.appendChild(label);
        row.appendChild(input);
        return row;
    }

    save() {
        if (typeof abilityConfigManager === 'undefined' || !this.draft) return;
        abilityConfigManager.setAbility(this.selectedId, this.draft);
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        const header = document.querySelector('#abilityEditorOverlay .planet-editor-header h2');
        if (header) {
            const prev = header.textContent;
            header.textContent = 'SAVED';
            setTimeout(() => { header.textContent = prev || 'ABILITY EDITOR'; }, 700);
        }
    }

    reset() {
        if (typeof abilityConfigManager === 'undefined') return;
        abilityConfigManager.resetAbility(this.selectedId);
        this.loadDraft();
        this.renderControls();
    }
}

var abilityEditorUI = new AbilityEditorUI();
abilityEditorUI.init();


/* --- js/ui/shot-behavior-editor.js --- */
"use strict";

/**
 * Shot Behavior Editor — tweak flight / hitbox / fire cadence per weapon.
 * Open: Dev Mode → Tools → SHOT BEHAVIOR, or Weapons viewer → EDIT BEHAVIOR.
 */
var ShotBehaviorEditorUI = class ShotBehaviorEditorUI {
    constructor() {
        this.visible = false;
        this.returnTo = null;
        this.selectedId = 'laser';
        this.draft = null;
        this._previewBullets = [];
        this._previewAnimId = null;
        this._previewLastTs = 0;
        this._keyHandler = (e) => {
            if (e.key === 'Escape' && this.visible) {
                e.preventDefault();
                this.hide();
            }
        };
    }

    init() {
        this.ensureOverlay();
    }

    ensureOverlay() {
        if (document.getElementById('shotBehaviorEditorOverlay')) return;

        const overlay = document.createElement('div');
        overlay.id = 'shotBehaviorEditorOverlay';
        overlay.className = 'planet-editor-overlay shot-behavior-editor-overlay hidden';
        overlay.innerHTML = `
            <div class="planet-editor-panel">
                <div class="planet-editor-header">
                    <h2>SHOT BEHAVIOR</h2>
                    <div class="planet-editor-planet-select" id="sbeTypeSelect"></div>
                </div>
                <div class="planet-editor-body has-preview" id="sbeBody">
                    <div class="planet-editor-controls" id="sbeControls"></div>
                    <aside class="content-viewer-preview planet-editor-preview-wrap" id="sbePreviewWrap">
                        <div class="pe-preview-viewport" id="sbePreviewViewport">
                            <canvas id="sbePreview" width="160" height="240"></canvas>
                        </div>
                        <div class="pe-preview-label">FLIGHT PREVIEW</div>
                    </aside>
                </div>
                <div class="planet-editor-footer">
                    <button type="button" class="pe-btn" id="sbeReset">RESET</button>
                    <button type="button" class="pe-btn pe-primary" id="sbeSave">SAVE</button>
                    <button type="button" class="pe-btn" id="sbeClose">CLOSE</button>
                </div>
                <div class="content-viewer-hint">Dev Mode · edits apply after SAVE · ESC Close</div>
            </div>
        `;
        document.body.appendChild(overlay);

        overlay.querySelector('#sbeSave').addEventListener('click', () => this.save());
        overlay.querySelector('#sbeReset').addEventListener('click', () => this.reset());
        overlay.querySelector('#sbeClose').addEventListener('click', () => this.hide());
        document.addEventListener('keydown', this._keyHandler);
    }

    persistMenuState() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            menuStateManager.setScreen('shot-behavior-editor', {
                weaponId: this.selectedId,
                returnTo: this.returnTo
            });
        }
    }

    show(weaponId, fromRestore, options) {
        this.ensureOverlay();
        if (weaponId) this.selectedId = String(weaponId);
        if (options && options.returnTo) this.returnTo = options.returnTo;
        else if (!fromRestore) this.returnTo = null;
        this.loadDraft();
        this.visible = true;
        document.getElementById('shotBehaviorEditorOverlay').classList.remove('hidden');
        this.renderTypeSelect();
        this.renderControls();
        this.resetPreview();
        this.startPreview();
        if (!fromRestore) this.persistMenuState();
    }

    hide() {
        this.visible = false;
        this.stopPreview();
        const el = document.getElementById('shotBehaviorEditorOverlay');
        if (el) el.classList.add('hidden');
        const backTo = this.returnTo;
        this.returnTo = null;
        if (backTo === 'weapon-viewer' && typeof weaponViewerUI !== 'undefined') {
            weaponViewerUI.show({ weaponId: this.selectedId });
            return;
        }
        if (typeof menuStateManager !== 'undefined') {
            const container = document.querySelector('.game-container');
            const inGame = container && container.style.display !== 'none';
            menuStateManager.setScreen(inGame ? 'ingame' : 'start');
        }
    }

    loadDraft() {
        if (typeof weaponConfigManager === 'undefined') {
            this.draft = {
                id: this.selectedId,
                name: this.selectedId,
                damage: 10,
                speed: 12,
                cooldown: 250,
                energyCost: 4,
                width: 2,
                height: 12,
                bulletCount: 1,
                spreadAngle: 0,
                bulletSpacing: 4,
                waveAmp: 0,
                pierce: false
            };
            return;
        }
        const w = weaponConfigManager.getWeapon(this.selectedId);
        this.draft = {
            id: w.id,
            name: w.name,
            description: w.description || '',
            damage: w.damage,
            speed: w.speed,
            cooldown: w.cooldown,
            energyCost: w.energyCost,
            width: w.width,
            height: w.height,
            bulletCount: w.bulletCount || 1,
            spreadAngle: w.spreadAngle || 0,
            bulletSpacing: w.bulletSpacing || 4,
            waveAmp: w.waveAmp || 0,
            pierce: !!w.pierce,
            bulletType: w.bulletType,
            iconKey: w.iconKey,
            faction: w.faction,
            lightRadius: w.lightRadius,
            lightIntensity: w.lightIntensity
        };
    }

    renderTypeSelect() {
        const root = document.getElementById('sbeTypeSelect');
        if (!root) return;
        root.innerHTML = '';
        const ids = typeof weaponConfigManager !== 'undefined'
            ? weaponConfigManager.getIds()
            : [this.selectedId];
        ids.forEach((id) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'pe-planet-btn' + (id === this.selectedId ? ' active' : '');
            const meta = typeof weaponConfigManager !== 'undefined'
                ? weaponConfigManager.getWeapon(id)
                : { name: id };
            const icon = (typeof iconRenderer !== 'undefined' && iconRenderer.weaponImgHtml)
                ? iconRenderer.weaponImgHtml(id, 14, 'cv-ability-icon-img', meta.name)
                : '';
            btn.innerHTML = `${icon} <span>${meta.name || id}</span>`;
            btn.addEventListener('click', () => {
                this.selectedId = id;
                this.loadDraft();
                this.renderTypeSelect();
                this.renderControls();
                this.resetPreview();
                this.persistMenuState();
            });
            root.appendChild(btn);
        });
    }

    renderControls() {
        const root = document.getElementById('sbeControls');
        if (!root || !this.draft) return;
        root.innerHTML = '';

        const head = document.createElement('div');
        head.className = 'ae-preview';
        const icon = (typeof iconRenderer !== 'undefined' && iconRenderer.weaponImgHtml)
            ? iconRenderer.weaponImgHtml(this.draft.id, 28, 'cv-ability-icon-img', this.draft.name)
            : '◆';
        head.innerHTML = `<span class="ae-preview-icon">${icon}</span>`
            + `<span class="ae-preview-name">${this.draft.name || this.draft.id}</span>`;
        root.appendChild(head);

        root.appendChild(this.makeSlider('Speed', this.draft.speed, 1, 24, 0.5, (v) => {
            this.draft.speed = v;
            this.resetPreview();
        }));
        root.appendChild(this.makeSlider('Damage', this.draft.damage, 1, 28, 1, (v) => {
            this.draft.damage = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Cooldown ms', this.draft.cooldown, 80, 1200, 10, (v) => {
            this.draft.cooldown = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Energy', this.draft.energyCost, 0, 12, 1, (v) => {
            this.draft.energyCost = Math.round(v);
        }));
        root.appendChild(this.makeSlider('Hit W', this.draft.width, 1, 4, 1, (v) => {
            this.draft.width = Math.round(v);
            this.resetPreview();
        }));
        root.appendChild(this.makeSlider('Hit H', this.draft.height, 3, 16, 1, (v) => {
            this.draft.height = Math.round(v);
            this.resetPreview();
        }));
        root.appendChild(this.makeSlider('Count', this.draft.bulletCount || 1, 1, 8, 1, (v) => {
            this.draft.bulletCount = Math.round(v);
            this.resetPreview();
        }));
        root.appendChild(this.makeSlider('Spread', this.draft.spreadAngle || 0, 0, 1.2, 0.05, (v) => {
            this.draft.spreadAngle = v;
            this.resetPreview();
        }));
        root.appendChild(this.makeSlider('Spacing', this.draft.bulletSpacing || 4, 0, 12, 1, (v) => {
            this.draft.bulletSpacing = Math.round(v);
            this.resetPreview();
        }));
        root.appendChild(this.makeSlider('Wave amp', this.draft.waveAmp || 0, 0, 4, 0.1, (v) => {
            this.draft.waveAmp = v;
            this.resetPreview();
        }));
        root.appendChild(this.makeToggle('Pierce', !!this.draft.pierce, (v) => {
            this.draft.pierce = v;
        }));
    }

    makeToggle(labelText, value, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'pe-btn' + (value ? ' pe-primary' : '');
        btn.textContent = value ? 'ON' : 'OFF';
        btn.addEventListener('click', () => {
            const next = !value;
            value = next;
            btn.textContent = next ? 'ON' : 'OFF';
            btn.classList.toggle('pe-primary', next);
            onChange(next);
        });
        row.appendChild(label);
        row.appendChild(btn);
        return row;
    }

    makeSlider(labelText, value, min, max, step, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const val = document.createElement('span');
        val.className = 'pe-val';
        const format = (v) => (step < 1 ? Number(v).toFixed(2) : String(Math.round(v)));
        val.textContent = format(value);
        const input = document.createElement('input');
        input.type = 'range';
        input.min = String(min);
        input.max = String(max);
        input.step = String(step);
        input.value = String(value);
        input.addEventListener('input', () => {
            const v = Number(input.value);
            val.textContent = format(v);
            onChange(v);
        });
        row.appendChild(label);
        row.appendChild(val);
        row.appendChild(input);
        return row;
    }

    resetPreview() {
        this._previewBullets = [];
        this._previewAcc = 0;
        this.spawnPreviewVolley();
    }

    spawnPreviewVolley() {
        if (!this.draft) return;
        const canvas = document.getElementById('sbePreview');
        if (!canvas) return;
        const cx = canvas.width / 2;
        const y0 = canvas.height - 28;
        const count = Math.max(1, Math.round(this.draft.bulletCount || 1));
        const spread = Number(this.draft.spreadAngle) || 0;
        const spacing = Number(this.draft.bulletSpacing) || 0;
        const spd = Math.max(0.5, Number(this.draft.speed) || 10);
        const w = Math.max(1, Number(this.draft.width) || 2);
        const h = Math.max(3, Number(this.draft.height) || 8);
        const wave = Number(this.draft.waveAmp) || 0;
        const color = (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getWeaponUiColor)
            ? (weaponConfigManager.getWeaponUiColor(this.draft.id) || '#7ec8ff')
            : '#7ec8ff';
        for (let i = 0; i < count; i++) {
            const t = count === 1 ? 0 : (i / (count - 1)) - 0.5;
            const ang = t * spread * 2;
            const xOff = count > 1 && spread === 0 ? t * spacing * 2 : 0;
            this._previewBullets.push({
                x: cx - w / 2 + xOff,
                y: y0 - h,
                width: w,
                height: h,
                speed: spd * 0.55,
                angle: ang || undefined,
                waveAmp: wave,
                wavePhase: 0,
                type: wave > 0 ? 'wave_beam' : (this.draft.bulletType || 'laser_beam'),
                color
            });
        }
    }

    startPreview() {
        this.stopPreview();
        this._previewLastTs = 0;
        const tick = (ts) => {
            if (!this.visible) return;
            const dt = this._previewLastTs ? Math.min(40, ts - this._previewLastTs) : 16;
            this._previewLastTs = ts;
            this.updatePreview(dt);
            this.drawPreview();
            this._previewAnimId = requestAnimationFrame(tick);
        };
        this._previewAnimId = requestAnimationFrame(tick);
    }

    stopPreview() {
        if (this._previewAnimId) {
            cancelAnimationFrame(this._previewAnimId);
            this._previewAnimId = null;
        }
    }

    updatePreview(dtMs) {
        const sm = (dtMs || 16) / 16.67;
        const canvas = document.getElementById('sbePreview');
        if (!canvas) return;
        this._previewAcc = (this._previewAcc || 0) + dtMs;
        const cd = Math.max(120, Number(this.draft && this.draft.cooldown) || 300);
        if (this._previewAcc >= cd || this._previewBullets.length === 0) {
            this._previewAcc = 0;
            this.spawnPreviewVolley();
        }
        for (let i = this._previewBullets.length - 1; i >= 0; i--) {
            const b = this._previewBullets[i];
            const s = Math.max(0.5, Number(b.speed) || 6) * sm;
            let bdx = 0;
            let bdy = -s;
            if (b.type === 'wave_beam' && b.waveAmp) {
                b.wavePhase = (b.wavePhase || 0) + 0.25 * sm;
                bdx = Math.sin(b.wavePhase) * b.waveAmp * sm;
            } else if (b.angle != null && Number.isFinite(Number(b.angle))) {
                const a = Number(b.angle);
                bdx = Math.sin(a) * s;
                bdy = -Math.cos(a) * s;
            }
            if (Math.abs(bdy) < s * 0.55) {
                bdx = 0;
                bdy = -s;
            }
            b.x += bdx;
            b.y += bdy;
            if (b.y + b.height < 0) this._previewBullets.splice(i, 1);
        }
    }

    drawPreview() {
        const canvas = document.getElementById('sbePreview');
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        ctx.fillStyle = '#07090e';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        // Muzzle marker
        ctx.fillStyle = '#3a4656';
        ctx.fillRect(canvas.width / 2 - 6, canvas.height - 18, 12, 10);
        ctx.fillStyle = '#7a8a9c';
        ctx.fillRect(canvas.width / 2 - 3, canvas.height - 22, 6, 4);
        for (let i = 0; i < this._previewBullets.length; i++) {
            const b = this._previewBullets[i];
            ctx.globalAlpha = 0.35;
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(Math.round(b.x) - 1, Math.round(b.y) - 1, Math.max(1, b.width) + 2, Math.max(1, b.height) + 2);
            ctx.globalAlpha = 1;
            ctx.fillStyle = b.color || '#7ec8ff';
            ctx.fillRect(Math.round(b.x), Math.round(b.y), Math.max(1, b.width), Math.max(1, b.height));
            // Hitbox outline
            ctx.strokeStyle = 'rgba(255,80,80,0.85)';
            ctx.lineWidth = 1;
            ctx.strokeRect(Math.round(b.x) + 0.5, Math.round(b.y) + 0.5, Math.max(1, b.width) - 1, Math.max(1, b.height) - 1);
        }
        ctx.globalAlpha = 1;
    }

    save() {
        if (typeof weaponConfigManager === 'undefined' || !this.draft) return;
        weaponConfigManager.setWeapon(this.selectedId, this.draft);
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        this.resetPreview();
        const header = document.querySelector('#shotBehaviorEditorOverlay .planet-editor-header h2');
        if (header) {
            const prev = header.textContent;
            header.textContent = 'SAVED';
            setTimeout(() => { header.textContent = prev || 'SHOT BEHAVIOR'; }, 700);
        }
    }

    reset() {
        if (typeof weaponConfigManager === 'undefined') return;
        weaponConfigManager.resetWeapon(this.selectedId);
        this.loadDraft();
        this.renderControls();
        this.resetPreview();
    }
}

var shotBehaviorEditorUI = new ShotBehaviorEditorUI();
shotBehaviorEditorUI.init();
window.shotBehaviorEditorUI = shotBehaviorEditorUI;


/* --- js/ui/hangar-test-arena/core.js --- */
"use strict";

/**
 * Hangar Test Arena — interactive flight / damage / defense sandbox.
 * Opened from hangar LIVE PREVIEW. Enemies limited to discovered types.
 */
var HangarTestArena = class HangarTestArena {
    constructor() {
        this.isVisible = false;
        this.overlay = null;
        this.shipId = 'player_scrap';
        this.onClose = null;
        this._animId = null;
        this._lastTs = 0;
        this._keys = Object.create(null);
        this._keyDown = null;
        this._keyUp = null;
        this._selectedEnemies = {};
        this._enemyRespawns = {};
        this._stats = { damageDealt: 0, damageTaken: 0, kills: 0, shots: 0 };
        this._elapsed = 0;
        this._respawnMs = 0;
        this._layoutMode = 'fullscreen';
        this.sim = null;
        this.canvas = null;
        this.ctx = null;
        // Match main playfield (gameStateManager: 240×300)
        this.W = 240;
        this.H = 300;
        // Bottom HUD strip (bars + key caps); the ship stays above it.
        this.HUD_H = 60;
        this.SHIP_DRAW_SCALE = 1;
        this.ENEMY_HIT_SCALE = 1;
        this.RESPAWN_MS = 2000;
    }

    show(options) {
        const opts = options || {};
        this.shipId = opts.shipId || 'player_scrap';
        this.onClose = opts.onClose || null;
        this.isVisible = true;
        this._stats = { damageDealt: 0, damageTaken: 0, kills: 0, shots: 0 };
        this._elapsed = 0;
        this._respawnMs = 0;
        this._enemyRespawns = {};
        this._selectedEnemies = {};
        const discovered = this.getDiscoveredEnemies();
        if (discovered.length) {
            this._selectedEnemies[discovered[0].id] = true;
        }
        this.createUI();
        this.resetSim();
        this.syncEnemiesFromSelection();
        this.bindInput();
        this.startLoop();
    }

    hide() {
        this.isVisible = false;
        this.stopLoop();
        this.unbindInput();
        this.sim = null;
        this.canvas = null;
        this.ctx = null;
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
    }

    close() {
        const cb = this.onClose;
        this.hide();
        if (typeof cb === 'function') cb();
    }

    getDiscoveredEnemies() {
        let ids = [];
        if (typeof profileManager !== 'undefined' && profileManager.getDiscovered) {
            ids = profileManager.getDiscovered('enemies') || [];
        }
        return ids.map((id) => {
            const cfg = (typeof enemyConfigManager !== 'undefined' && enemyConfigManager.getConfig)
                ? enemyConfigManager.getConfig(id)
                : null;
            const name = (typeof enemyConfigManager !== 'undefined' && enemyConfigManager.getDisplayName)
                ? enemyConfigManager.getDisplayName(id)
                : (cfg && cfg.name) || id;
            return {
                id,
                name: name || id,
                maxHealth: (cfg && cfg.maxHealth) || 100,
                armor: (cfg && cfg.armor) || 0,
                shieldMax: (cfg && cfg.shieldMax) || 0,
                damage: (cfg && (cfg.weaponDamage || cfg.damage)) || 10,
                speed: (cfg && cfg.speed) || 1.5,
                verticalSpeed: (cfg && cfg.verticalSpeed) || 0.35,
                shootInterval: (cfg && (cfg.weaponCooldown || cfg.shootInterval)) || 1200,
                weaponSpeed: (cfg && cfg.weaponSpeed) || 5,
                defenseMechanisms: (cfg && (cfg.defenseMechanisms || cfg.abilities)) || [],
                damageReduction: (cfg && cfg.damageReduction) || 0,
                reflectChance: (cfg && cfg.reflectChance) || 0,
                shieldRegen: (cfg && cfg.shieldRegen) || 0
            };
        });
    }

    getShipStats() {
        const shipId = this.shipId;
        const model = (typeof shipConfigManager !== 'undefined' && shipConfigManager.getMergedModel)
            ? shipConfigManager.getMergedModel(shipId)
            : null;
        const cfg = (typeof shipConfigManager !== 'undefined' && shipConfigManager.getConfig)
            ? shipConfigManager.getConfig(shipId)
            : null;
        const loadout = (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.getLoadout)
            ? shipLoadoutManager.getLoadout(shipId)
            : { weapons: [], defenses: [], abilities: [], energy: [], fireMode: 'auto' };

        const defenses = (loadout.defenses || []).concat(loadout.abilities || []);
        const defStats = (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.computeDefenseStats)
            ? shipLoadoutManager.computeDefenseStats(defenses)
            : { shieldMax: 0, shieldRegen: 0, damageReduction: 0, reflectChance: 0, mechs: defenses.slice() };
        const mechs = defStats.mechs;
        const chargeStats = (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.computeChargeStats)
            ? shipLoadoutManager.computeChargeStats(defenses)
            : null;
        const energyStats = (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.computeEnergyStats)
            ? shipLoadoutManager.computeEnergyStats(loadout)
            : { maxEnergy: 0, regen: 0, idleDraw: 0, shotCost: 4, chargePerSec: 12, shieldAbsorbPerDmg: 0.5, boostPerSec: 0, boostSpeedMul: 1 };
        const fireMode = (loadout.abilities || []).indexOf('charge_shot') !== -1 ? 'charge' : 'auto';

        const layout = (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.getLayout)
            ? shipLoadoutManager.getLayout(shipId)
            : null;
        const w = (layout && layout.width) || (model && model.width) || 20;
        const h = (layout && layout.height) || (model && model.height) || 16;

        // Weapon feel from loadout / weapon config (same source as bulletManager)
        let weaponDamage = Number((cfg && cfg.weaponDamage) || (model && model.damage) || 10);
        let weaponSpeed = Number((cfg && cfg.weaponSpeed) || 8);
        let weaponCooldown = Number((cfg && cfg.weaponCooldown) || 300);
        let bulletW = 3;
        let bulletH = 12;
        const weaponId = (loadout.weapons && loadout.weapons[0])
            || (cfg && cfg.defaultWeapon)
            || (model && model.defaultWeapon)
            || 'laser';
        if (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getConfig) {
            const wc = weaponConfigManager.getConfig(weaponId);
            if (wc) {
                if (wc.damage != null) weaponDamage = Number(wc.damage);
                if (wc.speed != null) weaponSpeed = Number(wc.speed);
                if (wc.cooldown != null) weaponCooldown = Number(wc.cooldown);
                if (wc.width != null) bulletW = Number(wc.width);
                if (wc.height != null) bulletH = Number(wc.height);
            }
        }

        return {
            model: model || { width: w, height: h, name: shipId, type: 'player', id: shipId },
            // Same fixed footprint as in game (player applyFixedFootprint):
            // 28 wide, aspect kept — so ship and shots keep in-game proportions.
            width: Math.max(8, Math.round(w * (typeof PLAYER_UNIT_SCALE !== 'undefined' ? PLAYER_UNIT_SCALE : 0.78))),
            height: Math.max(8, Math.round(h * (typeof PLAYER_UNIT_SCALE !== 'undefined' ? PLAYER_UNIT_SCALE : 0.78))),
            speed: Number((cfg && cfg.speed) || (model && model.speed) || 4),
            maxHealth: Number((cfg && cfg.maxHealth) || (model && model.maxHealth) || 100),
            armor: Number((cfg && cfg.armor) || (model && model.armor) || 0),
            weaponDamage,
            weaponSpeed,
            weaponCooldown,
            bulletW,
            bulletH,
            weaponId,
            fireMode: fireMode,
            chargeStats: chargeStats,
            shieldMax: defStats.shieldMax,
            shieldRegen: defStats.shieldRegen,
            defenseMechanisms: mechs,
            damageReduction: defStats.damageReduction,
            reflectChance: defStats.reflectChance,
            energyStats: energyStats
        };
    }

    createUI() {
        if (this.overlay) this.overlay.remove();
        const enemies = this.getDiscoveredEnemies();
        const enemyList = enemies.length
            ? enemies.map((e) => {
                const on = !!this._selectedEnemies[e.id];
                return `<label class="hta-enemy ${on ? 'on' : ''}">` +
                    `<input type="checkbox" data-hta-enemy="${e.id}" ${on ? 'checked' : ''}/>` +
                    `<span class="hta-enemy-name">${e.name}</span>` +
                    `<span class="hta-enemy-meta">HP ${e.maxHealth}` +
                    `${e.shieldMax ? ' · SH ' + e.shieldMax : ''}</span>` +
                    `</label>`;
            }).join('')
            : '<p class="hta-muted">NO ENEMIES DISCOVERED YET — PLAY A LEVEL FIRST</p>';

        this.overlay = document.createElement('div');
        this.overlay.className = 'hta-overlay';
        this.overlay.innerHTML = `
            <div class="hta-panel">
                <header class="hta-head">
                    <h2 class="hta-title">TEST AREA</h2>
                    <p class="hta-sub">LIVE LEVEL PREVIEW</p>
                    <button type="button" class="action-button secondary" id="htaToggleLayout">MODAL</button>
                    <button type="button" class="action-button secondary hta-close" id="htaClose">CLOSE</button>
                </header>
                <div class="hta-body">
                    <aside class="hta-side">
                        <h3 class="hta-side-title">ENEMY</h3>
                        <div class="hta-enemy-list">${enemyList}</div>
                        <p class="hta-hint">SELECT TO SWAP · AUTO RESPAWN 2s</p>
                        <div class="hta-stats" id="htaStats"></div>
                        <p class="hta-hint">ARROWS MOVE · SPACE FIRE ALL · A / S / D SOLO · ESC CLOSE</p>
                    </aside>
                    <div class="hta-stage">
                        <canvas id="htaCanvas" class="hta-canvas" width="${this.W}" height="${this.H}"
                            aria-label="Hangar test arena"></canvas>
                    </div>
                </div>
            </div>`;
        document.body.appendChild(this.overlay);
        this.applyLayoutMode();

        this.canvas = this.overlay.querySelector('#htaCanvas');
        this.ctx = this.canvas.getContext('2d');
        this.renderStats();

        this.overlay.querySelector('#htaClose').addEventListener('click', () => this.close());
        const layoutBtn = this.overlay.querySelector('#htaToggleLayout');
        if (layoutBtn) {
            layoutBtn.addEventListener('click', () => this.toggleLayoutMode());
        }
        this.overlay.querySelectorAll('[data-hta-enemy]').forEach((input) => {
            input.addEventListener('change', () => {
                const id = input.getAttribute('data-hta-enemy');
                this._selectedEnemies[id] = !!input.checked;
                const lab = input.closest('.hta-enemy');
                if (lab) lab.classList.toggle('on', !!input.checked);
                this.syncEnemiesFromSelection();
            });
        });
    }

    applyLayoutMode() {
        if (!this.overlay) return;
        const fullscreen = this._layoutMode !== 'modal';
        this.overlay.classList.toggle('hta-fullscreen', fullscreen);
        this.overlay.classList.toggle('hta-modal', !fullscreen);
        const btn = this.overlay.querySelector('#htaToggleLayout');
        if (btn) btn.textContent = fullscreen ? 'MODAL' : 'FULLSCREEN';
    }

    toggleLayoutMode() {
        this._layoutMode = this._layoutMode === 'fullscreen' ? 'modal' : 'fullscreen';
        this.applyLayoutMode();
    }
}


/* --- js/ui/hangar-test-arena/render-stats.js --- */
"use strict";

// HangarTestArena methods, split from hangar-test-arena.js.
extendClass(HangarTestArena, {
    renderStats() {
        const el = this.overlay && this.overlay.querySelector('#htaStats');
        if (!el || !this.sim) return;
        const p = this.sim.player;
        const sec = Math.max(0.001, this._elapsed / 1000);
        const dps = (this._stats.damageDealt / sec).toFixed(1);
        el.innerHTML =
            `<div class="hta-stat-row"><span>HP</span><strong>${this._respawnMs > 0 ? 0 : Math.ceil(p.health)} / ${p.maxHealth}</strong></div>` +
            `<div class="hta-stat-row"><span>SHIELD</span><strong>${this._respawnMs > 0 ? 0 : Math.ceil(p.shield)} / ${p.shieldMax}</strong></div>` +
            `<div class="hta-stat-row"><span>ENERGY</span><strong>${this._respawnMs > 0 ? 0 : Math.ceil(p.energy || 0)} / ${p.maxEnergy || 0}</strong></div>` +
            `<div class="hta-stat-row"><span>ARMOR</span><strong>${p.armor}</strong></div>` +
            `<div class="hta-stat-row"><span>DMG OUT</span><strong>${Math.round(this._stats.damageDealt)}</strong></div>` +
            `<div class="hta-stat-row"><span>DPS</span><strong>${dps}</strong></div>` +
            `<div class="hta-stat-row"><span>DMG IN</span><strong>${Math.round(this._stats.damageTaken)}</strong></div>` +
            `<div class="hta-stat-row"><span>KILLS</span><strong>${this._stats.kills}</strong></div>` +
            (this._respawnMs > 0
                ? `<div class="hta-stat-row"><span>P RESPAWN</span><strong>${(this._respawnMs / 1000).toFixed(1)}s</strong></div>`
                : '') +
            (this.nextEnemyRespawnMs() > 0
                ? `<div class="hta-stat-row"><span>E RESPAWN</span><strong>${(this.nextEnemyRespawnMs() / 1000).toFixed(1)}s</strong></div>`
                : '');
    },

    nextEnemyRespawnMs() {
        let min = 0;
        Object.keys(this._enemyRespawns).forEach((id) => {
            const v = this._enemyRespawns[id];
            if (v > 0 && (min === 0 || v < min)) min = v;
        });
        return min;
    },

    resetSim() {
        const stats = this.getShipStats();
        const pw = stats.width;
        const ph = stats.height;
        this.sim = {
            player: {
                x: (this.W - pw) / 2,
                y: this.H - (this.HUD_H || 0) - ph - 8,
                width: pw,
                height: ph,
                speed: stats.speed,
                health: stats.maxHealth,
                maxHealth: stats.maxHealth,
                armor: stats.armor,
                shield: stats.shieldMax,
                shieldMax: stats.shieldMax,
                shieldRegen: stats.shieldRegen,
                defenseMechanisms: stats.defenseMechanisms.slice(),
                damageReduction: stats.damageReduction,
                reflectChance: stats.reflectChance,
                weaponDamage: stats.weaponDamage,
                weaponSpeed: stats.weaponSpeed,
                weaponCooldown: stats.weaponCooldown,
                bulletW: stats.bulletW,
                bulletH: stats.bulletH,
                weaponId: stats.weaponId,
                fireMode: stats.fireMode,
                chargeStats: stats.chargeStats,
                cooldown: 0,
                charge: 0,
                charging: false,
                driveCharge: 0,
                driveCharging: false,
                driveBurstMs: 0,
                driveBurstLevel: 0,
                energy: (stats.energyStats && stats.energyStats.maxEnergy) || 0,
                maxEnergy: (stats.energyStats && stats.energyStats.maxEnergy) || 0,
                energyRegen: (stats.energyStats && stats.energyStats.regen) || 0,
                energyIdleDraw: (stats.energyStats && stats.energyStats.idleDraw) || 0,
                shotEnergyCost: (stats.energyStats && stats.energyStats.shotCost) || 0,
                chargeEnergyPerSec: (stats.energyStats && stats.energyStats.chargePerSec) || 0,
                shieldAbsorbEnergyPerDmg: (stats.energyStats && stats.energyStats.shieldAbsorbPerDmg) || 0.5,
                boostEnergyPerSec: (stats.energyStats && stats.energyStats.boostPerSec) || 0,
                energyStats: stats.energyStats,
                model: stats.model,
                invuln: 0
            },
            enemies: [],
            bullets: [],
            enemyBullets: [],
            hits: [],
            phase: 0
        };
        this._stats = { damageDealt: 0, damageTaken: 0, kills: 0, shots: 0 };
        this._elapsed = 0;
        this._respawnMs = 0;
        this._enemyRespawns = {};
        this.renderStats();
    },

    resetPlayerOnly() {
        if (!this.sim) return;
        const stats = this.getShipStats();
        const p = this.sim.player;
        p.health = stats.maxHealth;
        p.maxHealth = stats.maxHealth;
        p.armor = stats.armor;
        p.shield = stats.shieldMax;
        p.shieldMax = stats.shieldMax;
        p.shieldRegen = stats.shieldRegen;
        p.defenseMechanisms = stats.defenseMechanisms.slice();
        p.damageReduction = stats.damageReduction;
        p.reflectChance = stats.reflectChance;
        p.weaponDamage = stats.weaponDamage;
        p.weaponSpeed = stats.weaponSpeed;
        p.weaponCooldown = stats.weaponCooldown;
        p.bulletW = stats.bulletW;
        p.bulletH = stats.bulletH;
        p.weaponId = stats.weaponId;
        p.fireMode = stats.fireMode;
        p.chargeStats = stats.chargeStats;
        p.cooldown = 0;
        p.charge = 0;
        p.charging = false;
        p.driveCharge = 0;
        p.driveCharging = false;
        p.driveBurstMs = 0;
        p.driveBurstLevel = 0;
        p.energy = (stats.energyStats && stats.energyStats.maxEnergy) || 0;
        p.maxEnergy = (stats.energyStats && stats.energyStats.maxEnergy) || 0;
        p.energyRegen = (stats.energyStats && stats.energyStats.regen) || 0;
        p.energyIdleDraw = (stats.energyStats && stats.energyStats.idleDraw) || 0;
        p.shotEnergyCost = (stats.energyStats && stats.energyStats.shotCost) || 0;
        p.chargeEnergyPerSec = (stats.energyStats && stats.energyStats.chargePerSec) || 0;
        p.shieldAbsorbEnergyPerDmg = (stats.energyStats && stats.energyStats.shieldAbsorbPerDmg) || 0.5;
        p.boostEnergyPerSec = (stats.energyStats && stats.energyStats.boostPerSec) || 0;
        p.energyStats = stats.energyStats;
        p.invuln = 1500;
        p.x = (this.W - p.width) / 2;
        p.y = this.H - (this.HUD_H || 0) - p.height - 8;
        this._respawnMs = 0;
        if (this.sim) {
            this.sim.enemyBullets = [];
            this.sim.bullets = [];
        }
        this.renderStats();
    },

    beginRespawn() {
        if (!this.sim || this._respawnMs > 0) return;
        const p = this.sim.player;
        p.health = 0;
        p.charging = false;
        p.charge = 0;
        this._respawnMs = this.RESPAWN_MS;
        this.sim.enemyBullets = [];
        this.sim.bullets = [];
        this.renderStats();
    },

    syncEnemiesFromSelection() {
        if (!this.sim) return;
        const selected = Object.keys(this._selectedEnemies).filter((id) => this._selectedEnemies[id]);
        this.sim.enemies = this.sim.enemies.filter((e) => selected.indexOf(e.id) !== -1);
        Object.keys(this._enemyRespawns).forEach((id) => {
            if (selected.indexOf(id) === -1) delete this._enemyRespawns[id];
        });
        selected.forEach((id) => {
            const alive = this.sim.enemies.some((e) => e.id === id);
            const pending = this._enemyRespawns[id] > 0;
            if (!alive && !pending) this.spawnEnemyById(id);
        });
    },

    queueEnemyRespawn(enemyId) {
        if (!enemyId || !this._selectedEnemies[enemyId]) return;
        this._enemyRespawns[enemyId] = this.RESPAWN_MS;
    },

    updateEnemyRespawns(dtMs) {
        const ids = Object.keys(this._enemyRespawns);
        for (let i = 0; i < ids.length; i++) {
            const id = ids[i];
            this._enemyRespawns[id] -= dtMs;
            if (this._enemyRespawns[id] <= 0) {
                delete this._enemyRespawns[id];
                if (this._selectedEnemies[id] && this.sim && !this.sim.enemies.some((e) => e.id === id)) {
                    this.spawnEnemyById(id);
                }
            }
        }
    },

    spawnEnemyById(enemyId) {
        if (!this.sim || !enemyId) return;
        const def = this.getDiscoveredEnemies().find((e) => e.id === enemyId);
        if (!def) return;
        if (this.sim.enemies.some((e) => e.id === enemyId)) return;
        delete this._enemyRespawns[enemyId];

        const model = (typeof enemyConfigManager !== 'undefined' && enemyConfigManager.getMergedModel)
            ? enemyConfigManager.getMergedModel(def.id)
            : null;
        // Match enemies.js spawn: hitbox = model size, draw scale 1
        const mw = Math.max(8, Math.round(((model && model.width) || 16) * this.ENEMY_HIT_SCALE));
        const mh = Math.max(8, Math.round(((model && model.height) || 12) * this.ENEMY_HIT_SCALE));
        const selectedCount = Object.keys(this._selectedEnemies).filter((id) => this._selectedEnemies[id]).length;
        const slot = this.sim.enemies.length;
        const speed = Math.max(0.25, Number(def.speed) || 0.4);
        const vSpeed = Math.max(0.05, Number(def.verticalSpeed) || 0.25);
        let x;
        let y;
        if (selectedCount <= 1) {
            x = (this.W - mw) / 2;
            y = 36;
        } else {
            const col = slot % 3;
            const row = Math.floor(slot / 3);
            x = 16 + col * ((this.W - 32) / 3) + ((this.W - 32) / 6) - mw / 2;
            y = 28 + row * (mh + 14);
        }
        this.sim.enemies.push({
            id: def.id,
            name: def.name,
            type: def.id,
            x,
            y,
            width: mw,
            height: mh,
            health: def.maxHealth,
            maxHealth: def.maxHealth,
            armor: def.armor,
            shield: def.shieldMax,
            shieldMax: def.shieldMax,
            shieldRegen: def.shieldRegen || 0,
            defenseMechanisms: (def.defenseMechanisms || []).slice(),
            damageReduction: def.damageReduction || 0,
            reflectChance: def.reflectChance || 0,
            damage: def.damage,
            speed: speed * (Math.random() < 0.5 ? -1 : 1),
            verticalSpeed: vSpeed * (Math.random() < 0.5 ? -1 : 1),
            minY: 8,
            maxY: Math.max(40, this.H * 0.38 - mh),
            shootInterval: def.shootInterval,
            weaponSpeed: Math.max(2, Number(def.weaponSpeed) || 2.5),
            shootAcc: 400 + Math.random() * 600,
            model
        });
    },
});


/* --- js/ui/hangar-test-arena/apply-defense.js --- */
"use strict";

// HangarTestArena methods, split from hangar-test-arena.js.
extendClass(HangarTestArena, {
    applyDefense(target, rawDamage) {
        const isPlayer = !!(this.sim && target === this.sim.player);
        const online = isPlayer && (target.maxEnergy || 0) > 0 && (target.energy || 0) > 0;
        const costPer = Math.max(0.01, Number(target.shieldAbsorbEnergyPerDmg) || 0.5);
        const maxAbs = (isPlayer && online) ? (target.energy / costPer) : (isPlayer ? 0 : Infinity);
        const savedShield = target.shield || 0;
        const usable = isPlayer ? Math.min(savedShield, maxAbs === Infinity ? savedShield : maxAbs) : savedShield;
        const proxy = Object.assign({}, target, { shield: usable });

        let rem;
        if (typeof enemyManager !== 'undefined' && enemyManager.applyDefenseToDamage) {
            rem = enemyManager.applyDefenseToDamage(proxy, rawDamage);
        } else {
            let dmg = Number(rawDamage) || 0;
            if (dmg <= 0) return 0;
            const mechs = proxy.defenseMechanisms || [];
            const reflect = (proxy.reflectChance || 0) / 100;
            if (reflect > 0 && Math.random() < reflect) return 0;
            let reduction = (proxy.damageReduction || 0) / 100;
            if (mechs.indexOf('massive_armor') !== -1) reduction = Math.min(0.75, reduction + 0.1);
            else if (mechs.indexOf('heavy_armor') !== -1) reduction = Math.min(0.75, reduction + 0.05);
            if (mechs.indexOf('adaptive_shield') !== -1) reduction = Math.min(0.75, reduction + 0.05);
            dmg *= (1 - Math.max(0, Math.min(0.75, reduction)));
            if (proxy.armor > 0) {
                const mitigation = Math.min(0.65, proxy.armor / (proxy.armor + 100));
                dmg *= (1 - mitigation);
            }
            dmg = Math.max(Math.max(1, Number(rawDamage) * 0.2), dmg);
            if (proxy.shield > 0) {
                const absorbed = Math.min(proxy.shield, dmg);
                proxy.shield -= absorbed;
                dmg -= absorbed;
            }
            rem = Math.max(0, dmg);
        }
        const used = Math.max(0, usable - (proxy.shield || 0));
        target.shield = savedShield - used;
        if (isPlayer && used > 0) {
            target.energy = Math.max(0, (target.energy || 0) - used * costPer);
        }
        return rem;
    },

    bindInput() {
        this.unbindInput();
        this._keyDown = (e) => {
            if (!this.isVisible) return;
            this._keys[e.key] = true;
            if (e.key === 'Shift' || e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
                this._keys['Shift'] = true;
            }
            if (e.key === 'Escape') {
                e.preventDefault();
                e.stopPropagation();
                this.close();
                return;
            }
            if (e.key === ' ' || e.code === 'Space') {
                e.preventDefault();
            }
        };
        this._keyUp = (e) => {
            if (!this.isVisible) return;
            this._keys[e.key] = false;
            if (e.key === ' ' || e.code === 'Space') {
                e.preventDefault();
                if (this.sim && this.sim.player.fireMode === 'charge' && this.sim.player.charging) {
                    this.releaseChargeShot();
                }
            }
            if (e.key === 'Shift' || e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
                this._keys['Shift'] = false;
                if (this.sim && this.sim.player.driveCharging) {
                    this.releaseDriveCharge();
                }
            }
        };
        document.addEventListener('keydown', this._keyDown, true);
        document.addEventListener('keyup', this._keyUp, true);
    },

    unbindInput() {
        if (this._keyDown) {
            document.removeEventListener('keydown', this._keyDown, true);
            this._keyDown = null;
        }
        if (this._keyUp) {
            document.removeEventListener('keyup', this._keyUp, true);
            this._keyUp = null;
        }
        this._keys = Object.create(null);
    },

    startLoop() {
        this.stopLoop();
        this._lastTs = 0;
        const loop = (ts) => {
            if (!this.isVisible) return;
            if (!this._lastTs) this._lastTs = ts;
            const dt = Math.min(50, ts - this._lastTs);
            this._lastTs = ts;
            this.update(dt);
            this.draw();
            if (!this._statsAcc) this._statsAcc = 0;
            this._statsAcc += dt;
            if (this._statsAcc >= 200) {
                this._statsAcc = 0;
                this.renderStats();
            }
            this._animId = requestAnimationFrame(loop);
        };
        this._animId = requestAnimationFrame(loop);
    },

    stopLoop() {
        if (this._animId) {
            cancelAnimationFrame(this._animId);
            this._animId = null;
        }
        this._lastTs = 0;
    },

    keyDown(name) {
        return !!(this._keys[name] || this._keys[name.toLowerCase()] || this._keys[name.toUpperCase()]);
    },

    releaseChargeShot() {
        const sim = this.sim;
        if (!sim) return;
        const p = sim.player;
        const cs = p.chargeStats || {};
        const maxMs = cs.maxChargeMs || 900;
        const minM = cs.minChargeMult || 1;
        const maxM = cs.maxChargeMult || 2.75;
        const t = Math.min(1, p.charge / maxMs);
        let mult = minM + (maxM - minM) * t;
        if (cs.shieldDivert) mult += (cs.divertShotBonus || 0) * t;
        p.charging = false;
        p.charge = 0;
        p.cooldown = p.weaponCooldown;
        const shotCost = p.shotEnergyCost || 0;
        if ((p.maxEnergy || 0) > 0 && (p.energy || 0) < shotCost) return;
        if (shotCost > 0) p.energy -= shotCost;
        const dmg = p.weaponDamage * mult;
        this.fireBullet(p, dmg, true);
    },

    releaseDriveCharge() {
        const sim = this.sim;
        if (!sim) return;
        const p = sim.player;
        p.driveCharging = false;
        p.driveCharge = 0;
        p.driveBurstMs = 0;
        p.driveBurstLevel = 0;
    },

    fireBullet(p, damage, charged) {
        const sim = this.sim;
        if (!sim) return;
        this._stats.shots += 1;
        const bw = charged ? Math.max(2, Math.round((p.bulletW || 2) * 1.25)) : (p.bulletW || 2);
        const bh = charged ? Math.max(8, Math.round((p.bulletH || 8) * 1.15)) : (p.bulletH || 8);
        const spd = p.weaponSpeed * (charged ? 1.15 : 1);
        sim.bullets.push({
            x: p.x + p.width / 2 - bw / 2,
            y: p.y,
            speed: spd,
            w: bw,
            h: bh,
            damage: damage,
            life: 2000
        });
    },
});


/* --- js/ui/hangar-test-arena/update.js --- */
"use strict";

// HangarTestArena methods, split from hangar-test-arena.js.
extendClass(HangarTestArena, {
    update(dtMs) {
        const sim = this.sim;
        if (!sim) return;
        const frame = dtMs / 16.67;
        this._elapsed += dtMs;
        sim.phase += dtMs * 0.003;
        const p = sim.player;

        this.updateEnemyRespawns(dtMs);

        if (this._respawnMs > 0) {
            this._respawnMs -= dtMs;
            if (this._respawnMs <= 0) {
                this._respawnMs = 0;
                this.resetPlayerOnly();
            }
            this.updateEnemies(dtMs, frame, false);
            sim.bullets = [];
            sim.enemyBullets = [];
            sim.hits = sim.hits.filter((h) => {
                h.life -= dtMs;
                h.y -= 0.4 * frame;
                return h.life > 0;
            });
            return;
        }

        // Movement with Shift boost (energy-powered)
        const cs = p.chargeStats || {};
        const es = p.energyStats || {};
        const powered = (p.maxEnergy || 0) > 0 && (p.energy || 0) > 0;

        // Energy net regen
        if ((p.maxEnergy || 0) > 0) {
            let net = p.energyRegen || 0;
            if ((p.energy || 0) > 0) net -= (p.energyIdleDraw || 0);
            p.energy = Math.max(0, Math.min(p.maxEnergy, p.energy + net * (dtMs / 1000)));
        }

        const shift = this.keyDown('Shift') || this.keyDown('ShiftLeft') || this.keyDown('ShiftRight');
        let moveMul = 1;
        if (cs.driveCharge && shift && powered) {
            p.driveCharging = true;
            moveMul = cs.driveBoostMul || es.boostSpeedMul || 1.55;
            const drain = p.boostEnergyPerSec || cs.driveBoostDrainPerSec || 32;
            p.energy = Math.max(0, p.energy - drain * (dtMs / 1000));
            if (p.energy <= 0) p.driveCharging = false;
        } else {
            p.driveCharging = false;
        }
        const moveSpeed = p.speed * frame * moveMul;
        // Arrows only: A / S / D are weapon fire keys.
        if (this.keyDown('ArrowLeft')) p.x -= moveSpeed;
        if (this.keyDown('ArrowRight')) p.x += moveSpeed;
        if (this.keyDown('ArrowUp')) p.y -= moveSpeed;
        if (this.keyDown('ArrowDown')) p.y += moveSpeed;

        p.x = Math.max(0, Math.min(this.W - p.width, p.x));
        p.y = Math.max(0, Math.min(this.H - (this.HUD_H || 0) - p.height, p.y));

        if (p.invuln > 0) p.invuln -= dtMs;

        const diverting = !!(p.charging && cs.shieldDivert);
        if (!diverting && p.shieldMax > 0 && p.shieldRegen > 0 && p.shield < p.shieldMax) {
            p.shield = Math.min(p.shieldMax, p.shield + p.shieldRegen * (dtMs / 1000));
        }

        p.cooldown = Math.max(0, p.cooldown - dtMs);
        // Charge mode still charges on Space; auto fire goes per key through
        // the game's own per-mount weapon logic (fireArenaKey).
        const space = this.keyDown(' ') || this.keyDown('Space');
        const systemsOnline = (p.maxEnergy || 0) > 0 && (p.energy || 0) > 0;
        if (p.fireMode === 'charge') {
            if (space && p.cooldown <= 0 && systemsOnline) {
                p.charging = true;
                const maxMs = cs.maxChargeMs || 900;
                p.charge = Math.min(maxMs, p.charge + dtMs);
                const chargeDrain = (p.chargeEnergyPerSec || 12) * (dtMs / 1000);
                p.energy = Math.max(0, p.energy - chargeDrain);
                if (p.energy <= 0) {
                    if (p.charge > 0.05 * maxMs) this.releaseChargeShot();
                    else {
                        p.charging = false;
                        p.charge = 0;
                    }
                }
                const level = Math.min(1, p.charge / maxMs);
                if (cs.shieldSync && cs.shieldFillPerSec > 0 && p.shieldMax > 0) {
                    p.shield = Math.min(p.shieldMax, p.shield + cs.shieldFillPerSec * level * (dtMs / 1000));
                }
                if (cs.shieldDivert) p.shield = 0;
            } else if (!space && p.charging) {
                this.releaseChargeShot();
            }
        } else if (systemsOnline) {
            ['space', 'a', 's', 'd'].forEach((k) => {
                const down = k === 'space' ? space : (this.keyDown(k) || this.keyDown(k.toUpperCase()));
                if (down) this.fireArenaKey(p, k);
            });
        }

        this.updateEnemies(dtMs, frame, true);

        // Player bullets — up, or along their angle (spread shots), like bulletManager
        sim.bullets = sim.bullets.filter((b) => {
            if (b.angle !== undefined) {
                b.x += Math.sin(b.angle) * b.speed * frame;
                b.y -= Math.cos(b.angle) * b.speed * frame;
            } else {
                b.y -= b.speed * frame;
            }
            b.life -= dtMs;
            if (b.life <= 0 || b.y + b.h < 0 || b.x < 0 || b.x > this.W) return false;
            for (let i = sim.enemies.length - 1; i >= 0; i--) {
                const e = sim.enemies[i];
                if (this.hit(b, e)) {
                    const before = e.health + e.shield;
                    const rem = this.applyDefense(e, b.damage);
                    e.health -= rem;
                    const dealt = Math.max(0, before - (e.health + e.shield));
                    this._stats.damageDealt += dealt;
                    sim.hits.push({ x: e.x + e.width / 2, y: e.y + e.height / 2, life: 220, dmg: Math.round(dealt) });
                    if (e.health <= 0) {
                        this._stats.kills += 1;
                        const deadId = e.id;
                        sim.enemies.splice(i, 1);
                        this.queueEnemyRespawn(deadId);
                    }
                    return false;
                }
            }
            return true;
        });

        // Enemy bullets — straight down
        sim.enemyBullets = sim.enemyBullets.filter((b) => {
            b.y += b.speed * frame;
            b.life -= dtMs;
            if (b.life <= 0 || b.y > this.H || b.x < 0 || b.x > this.W) return false;
            if (p.invuln <= 0 && this.hit(b, p)) {
                const before = p.health + p.shield;
                const rem = this.applyDefense(p, b.damage);
                p.health = Math.max(0, p.health - rem);
                this._stats.damageTaken += Math.max(0, before - (p.health + p.shield));
                p.invuln = 400;
                if (p.charging && p.chargeStats && p.chargeStats.shieldSync) {
                    p.charge = 0;
                }
                sim.hits.push({ x: p.x + p.width / 2, y: p.y + p.height / 2, life: 220, dmg: Math.round(rem) });
                if (p.health <= 0) {
                    this.beginRespawn();
                }
                return false;
            }
            return true;
        });

        sim.hits = sim.hits.filter((h) => {
            h.life -= dtMs;
            h.y -= 0.4 * frame;
            return h.life > 0;
        });
    },

    /** Ship model with the hangar layout applied — what the game flies (mount positions, weaponKeys). */
    getArenaFireModel() {
        const base = this.sim && this.sim.player && this.sim.player.model;
        if (!base) return null;
        if (!this._arenaFireModel || this._arenaFireModelBase !== base) {
            let m = Object.assign({}, base);
            if (typeof shipLoadoutManager !== 'undefined' && shipLoadoutManager.applyLayoutToModel) {
                shipLoadoutManager.applyLayoutToModel(m, this.shipId);
            }
            if (!m.weaponConfig && typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getDefaultsForShip) {
                m.weaponConfig = {};
                (m.availableWeapons || []).forEach((id) => { m.weaponConfig[id] = weaponConfigManager.getDefaultsForShip(id); });
            }
            this._arenaFireModel = m;
            this._arenaFireModelBase = base;
        }
        return this._arenaFireModel;
    },

    /** Detached BulletManager: per-mount cooldowns without touching the live game. */
    getArenaBulletManager() {
        if (!this._arenaBm) {
            const bm = (typeof BulletManager !== 'undefined') ? Object.create(BulletManager.prototype) : null;
            if (!bm) return null;
            bm.bullets = [];
            bm.enemyBullets = [];
            bm.weaponCooldowns = {};
            bm.muzzleFlashes = {};
            bm.lastShotTime = 0;
            this._arenaBm = bm;
        }
        return this._arenaBm;
    },

    /** Fire what `key` is bound to: every gun for the ALL key, else its assigned slots. */
    fireArenaKey(p, key) {
        const sim = this.sim;
        const model = this.getArenaFireModel();
        const bm = this.getArenaBulletManager();
        const allKey = (model && model.loadout && model.loadout.allFireKey) || 'space';
        const group = key === allKey ? 'all' : key;
        const shotCost = p.shotEnergyCost || 0;
        if ((p.maxEnergy || 0) > 0 && shotCost > 0 && p.energy < shotCost) return;
        if (!model || !bm || !model.weaponConfig) {
            // No weapon slots: the single centre gun on the ALL key.
            if (group !== 'all' || p.cooldown > 0) return;
            if (shotCost > 0) p.energy -= shotCost;
            p.cooldown = p.weaponCooldown;
            this.fireBullet(p, p.weaponDamage, false);
            return;
        }
        bm.currentShipModel = model;
        bm.currentWeapon = model.defaultWeapon || 'laser';
        bm.bullets = [];
        const fired = bm.shootWithShipWeapon(p, Date.now(), { fireKey: group });
        if (!fired) return;
        if (shotCost > 0) p.energy -= shotCost;
        bm.bullets.forEach((b) => {
            this._stats.shots += 1;
            sim.bullets.push({
                x: b.x,
                y: b.y,
                w: b.width,
                h: b.height,
                speed: b.speed,
                angle: b.angle,
                damage: b.damage != null ? b.damage : p.weaponDamage,
                type: b.type,
                weaponId: b.weaponId,
                life: 2000
            });
        });
        bm.bullets = [];
    },

    updateEnemies(dtMs, frame, allowShoot) {
        const sim = this.sim;
        if (!sim) return;
        sim.enemies.forEach((e) => {
            // Match enemyManager: axis bounce with speed / verticalSpeed
            e.x += e.speed * frame;
            e.y += e.verticalSpeed * frame;
            if (e.x <= 0) {
                e.x = 0;
                e.speed = Math.abs(e.speed);
            } else if (e.x >= this.W - e.width) {
                e.x = this.W - e.width;
                e.speed = -Math.abs(e.speed);
            }
            if (e.y <= e.minY) {
                e.y = e.minY;
                e.verticalSpeed = Math.abs(e.verticalSpeed);
            } else if (e.y >= e.maxY) {
                e.y = e.maxY;
                e.verticalSpeed = -Math.abs(e.verticalSpeed);
            }
            if (e.shieldMax > 0 && e.shieldRegen > 0 && e.shield < e.shieldMax) {
                e.shield = Math.min(e.shieldMax, e.shield + e.shieldRegen * (dtMs / 1000));
            }
            if (!allowShoot) return;
            e.shootAcc -= dtMs;
            if (e.shootAcc <= 0) {
                e.shootAcc = e.shootInterval;
                // Shot size of the enemy's weapon (same config as in game).
                const wid = e.weaponId || (e.model && e.model.defaultWeapon) || 'laser';
                const wc = (typeof weaponConfigManager !== 'undefined' && weaponConfigManager.getDefaultsForShip)
                    ? weaponConfigManager.getDefaultsForShip(wid) : null;
                const bw = (wc && wc.width) || 2;
                const bh = (wc && wc.height) || 8;
                sim.enemyBullets.push({
                    x: e.x + e.width / 2 - bw / 2,
                    y: e.y + e.height,
                    speed: Math.max(2.5, Number(e.weaponSpeed) || 2.5),
                    w: bw,
                    h: bh,
                    damage: e.damage,
                    weaponId: wid,
                    life: 2500
                });
            }
        });
    },

    hit(a, b) {
        return a.x < b.x + b.width && a.x + a.w > b.x && a.y < b.y + b.height && a.y + a.h > b.y;
    },

    drawShip(ctx, model, entity, flip) {
        if (typeof graphicsManager !== 'undefined') {
            if (flip && graphicsManager.renderEnemyShip) {
                const prev = graphicsManager.currentEnemyModel;
                if (model) graphicsManager.currentEnemyModel = model;
                graphicsManager.renderEnemyShip(ctx, entity, this.SHIP_DRAW_SCALE);
                graphicsManager.currentEnemyModel = prev;
                return;
            }
            if (!flip && graphicsManager.renderPlayerShip) {
                const prev = graphicsManager.currentPlayerModel;
                if (model) graphicsManager.currentPlayerModel = model;
                graphicsManager.renderPlayerShip(ctx, entity, this.SHIP_DRAW_SCALE);
                graphicsManager.currentPlayerModel = prev;
                return;
            }
        }
        if (typeof shipRenderer !== 'undefined') {
            if (shipRenderer.init) shipRenderer.init();
            const tmp = document.createElement('canvas');
            tmp.width = Math.max(1, entity.width);
            tmp.height = Math.max(1, entity.height);
            const m = model ? Object.assign({}, model) : { width: entity.width, height: entity.height };
            if (flip) m.forceEnemyOrientation = true;
            shipRenderer.renderShipPreview(tmp, m, 1);
            ctx.drawImage(tmp, Math.round(entity.x), Math.round(entity.y), entity.width, entity.height);
            return;
        }
        ctx.fillStyle = flip ? '#ff6688' : '#b44dff';
        ctx.fillRect(entity.x, entity.y, entity.width, entity.height);
    },

    drawBar(ctx, x, y, w, ratio, color) {
        ctx.fillStyle = 'rgba(0,0,0,0.55)';
        ctx.fillRect(x, y, w, 3);
        ctx.fillStyle = color;
        ctx.fillRect(x, y, Math.max(0, w * Math.min(1, ratio)), 3);
    },

    drawShieldHull(ctx, model, entity, flip, ratio, opts) {
        if (!(ratio > 0)) return;
        if (typeof graphicsManager !== 'undefined' && graphicsManager.drawShieldHull) {
            graphicsManager.drawShieldHull(ctx, entity, ratio, flip, model, opts || null);
            return;
        }
        // Fallback: thin box if graphics manager unavailable
        ctx.strokeStyle = 'rgba(100,200,255,' + (0.35 + 0.4 * Math.min(1, ratio || 0)) + ')';
        ctx.strokeRect(entity.x - 2, entity.y - 2, entity.width + 4, entity.height + 4);
    },
});


/* --- js/ui/hangar-test-arena/get-shield-threat-proximity.js --- */
"use strict";

// HangarTestArena methods, split from hangar-test-arena.js.
extendClass(HangarTestArena, {
    /** 0..1 — soft proximity fade for shield outline. */
    getShieldThreatProximity(entity, mode) {
        if (!entity || !this.sim) return 0;
        const radius = 72;
        let best = 0;
        const consider = (obj) => {
            if (!obj) return;
            const ox = (obj.x != null ? obj.x : 0) + ((obj.width != null ? obj.width : obj.w) || 0) / 2;
            const oy = (obj.y != null ? obj.y : 0) + ((obj.height != null ? obj.height : obj.h) || 0) / 2;
            const ex = entity.x + entity.width / 2;
            const ey = entity.y + entity.height / 2;
            const d = Math.sqrt((ox - ex) * (ox - ex) + (oy - ey) * (oy - ey));
            if (d >= radius) return;
            const t = 1 - (d / radius);
            const fade = t * t * (3 - 2 * t);
            if (fade > best) best = fade;
        };
        if (mode === 'enemy') {
            this.sim.bullets.forEach(consider);
            this.sim.enemyBullets.forEach((b) => { if (b.reflected) consider(b); });
        } else {
            this.sim.enemyBullets.forEach(consider);
            this.sim.bullets.forEach((b) => { if (b.reflected) consider(b); });
        }
        return best;
    },

    /** True when `key` ('space' | 'a' | 's' | 'd') is the ship's fire-all key. */
    arenaKeyIsAll(key) {
        const m = this.getArenaFireModel ? this.getArenaFireModel() : null;
        return ((m && m.loadout && m.loadout.allFireKey) || 'space') === key;
    },

    /** Weapon ids fired by a key: all equipped for the ALL key, else the slots assigned to it. */
    arenaKeyWeapons(key) {
        const m = this.getArenaFireModel ? this.getArenaFireModel() : null;
        const L = m && m.loadout;
        if (!L) return [];
        const slots = (L.weaponSlots && L.weaponSlots.length ? L.weaponSlots : L.weapons) || [];
        const keys = L.weaponKeys || {};
        if (this.arenaKeyIsAll(key)) return slots.filter(Boolean);
        return slots.filter((id, i) => id && (keys[String(i)] || 'space') === key);
    },

    /** Bottom strip: HULL / SHIELD / ENERGY bars, then A S D and SPACE key caps. */
    drawHud(ctx, p, accent) {
        const W = this.W;
        const top = this.H - this.HUD_H;
        const pad = 6;
        ctx.save();
        ctx.fillStyle = 'rgba(5,5,8,0.85)';
        ctx.fillRect(0, top, W, this.HUD_H);
        ctx.fillStyle = accent;
        ctx.globalAlpha = 0.6;
        ctx.fillRect(0, top, W, 1);
        ctx.globalAlpha = 1;
        const bars = [
            ['HULL', p.maxHealth > 0 ? p.health / p.maxHealth : 0, '#88ff88', p.maxHealth > 0],
            ['SHLD', p.shieldMax > 0 ? p.shield / p.shieldMax : 0, accent, p.shieldMax > 0],
            ['ENRG', p.maxEnergy > 0 ? p.energy / p.maxEnergy : 0, '#ffd23d', p.maxEnergy > 0]
        ];
        ctx.font = 'bold 7px monospace';
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'left';
        const labelW = 24;
        bars.forEach(([label, ratio, color, has], i) => {
            const y = top + 5 + i * 8;
            ctx.globalAlpha = has ? 1 : 0.35;
            ctx.fillStyle = color;
            ctx.fillText(label, pad, y + 2);
            const bx = pad + labelW;
            const bw = W - bx - pad;
            ctx.fillStyle = 'rgba(255,255,255,0.12)';
            ctx.fillRect(bx, y, bw, 4);
            ctx.fillStyle = color;
            ctx.fillRect(bx, y, Math.round(bw * Math.max(0, Math.min(1, ratio))), 4);
        });
        ctx.globalAlpha = 1;
        // Keys: A S D on one row, SPACE on its own row; lit while held.
        const held = (k) => (k === 'space' ? (this.keyDown(' ') || this.keyDown('Space')) : this.keyDown(k));
        const capH = 11;
        const gap = 4;
        const keysTop = top + 30;
        const unit = (W - pad * 2 - gap * 2) / 3;
        ctx.font = 'bold 8px monospace';
        ctx.textAlign = 'center';
        [['a', 'A'], ['s', 'S'], ['d', 'D'], ['space', 'SPACE']].forEach(([id, label], i) => {
            const isSpace = id === 'space';
            const x = isSpace ? pad : Math.round(pad + i * (unit + gap));
            const y = isSpace ? keysTop + capH + gap : keysTop;
            const cw = Math.round(isSpace ? W - pad * 2 : unit);
            const on = held(id);
            if (on) {
                ctx.fillStyle = accent;
                ctx.fillRect(x, y + 1, cw, capH);
                ctx.fillStyle = '#050508';
            } else {
                ctx.strokeStyle = accent;
                ctx.strokeRect(x + 0.5, y + 0.5, cw - 1, capH - 1);
                ctx.fillStyle = accent;
                ctx.fillRect(x, y + capH - 1, cw, 2);
            }
            ctx.fillText(label, x + cw / 2, y + capH / 2 + (on ? 1.5 : 0));
            // Icons of the weapons this key fires (ALL = every equipped gun).
            const ids = this.arenaKeyWeapons(id);
            const ic = capH - 3;
            ids.slice(0, 4).forEach((wid, j) => {
                if (typeof iconRenderer === 'undefined' || !iconRenderer.drawWeapon) return;
                iconRenderer.drawWeapon(ctx, wid, x + 2 + j * (ic + 1), y + 1.5 + (on ? 1 : 0), ic);
            });
            if (this.arenaKeyIsAll(id)) {
                ctx.textAlign = 'right';
                ctx.fillText('ALL', x + cw - 3, y + capH / 2 + (on ? 1.5 : 0));
                ctx.textAlign = 'center';
            }
        });
        ctx.restore();
    },

    draw() {
        const ctx = this.ctx;
        const sim = this.sim;
        if (!ctx || !sim) return;
        const accent = (getComputedStyle(document.documentElement).getPropertyValue('--color-primary') || '#b44dff').trim() || '#b44dff';
        const bg = (getComputedStyle(document.documentElement).getPropertyValue('--current-background')
            || getComputedStyle(document.documentElement).getPropertyValue('--color-background')
            || '#0a0a0a').trim() || '#0a0a0a';
        const W = this.W;
        const H = this.H;

        ctx.imageSmoothingEnabled = false;
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, W, H);

        // Match main playfield star scroll
        ctx.fillStyle = (getComputedStyle(document.documentElement).getPropertyValue('--current-text') || '#e0e0e0').trim() || '#e0e0e0';
        for (let i = 0; i < 50; i++) {
            ctx.globalAlpha = 0.15 + (i % 5) * 0.05;
            const sx = (i * 7) % W;
            const sy = ((i * 11) + sim.phase * 40) % H;
            ctx.fillRect(sx, sy, 1, 1);
        }
        ctx.globalAlpha = 1;

        // Player shots in their weapon type's colour (same renderer as in game).
        sim.bullets.forEach((b) => {
            if (b.weaponId && typeof renderManager !== 'undefined' && renderManager.drawBullet) {
                renderManager.drawBullet(ctx, { x: b.x, y: b.y, width: b.w, height: b.h, type: b.type, weaponId: b.weaponId }, null);
                return;
            }
            ctx.fillStyle = accent;
            ctx.fillRect(b.x, b.y, b.w, b.h);
        });
        // Enemy shots in their weapon's colour and shape (same renderer as in game).
        sim.enemyBullets.forEach((b) => {
            if (b.weaponId && typeof renderManager !== 'undefined' && renderManager.drawBullet) {
                renderManager.drawBullet(ctx, { x: b.x, y: b.y, width: b.w, height: b.h, weaponId: b.weaponId, isEnemyShot: true }, null);
                return;
            }
            ctx.fillStyle = '#ff5577';
            ctx.fillRect(b.x, b.y, b.w, b.h);
        });

        sim.enemies.forEach((e) => {
            this.drawShip(ctx, e.model, e, true);
            this.drawBar(ctx, e.x, e.y - 6, e.width, e.health / e.maxHealth, '#ff6677');
            if (e.shieldMax > 0) {
                this.drawBar(ctx, e.x, e.y - 3, e.width, e.shield / e.shieldMax, accent);
                const threat = this.getShieldThreatProximity(e, 'enemy');
                if (threat > 0.01) {
                    const strength = e.shield / e.shieldMax;
                    this.drawShieldHull(ctx, e.model, e, true, threat * (0.45 + 0.55 * strength));
                }
            }
        });

        const p = sim.player;
        if (this._respawnMs <= 0) {
            if (p.invuln > 0 && Math.floor(p.invuln / 60) % 2 === 0) {
                ctx.globalAlpha = 0.45;
            }
            // Same layout model the shots come from, so muzzles line up.
            this.drawShip(ctx, this.getArenaFireModel() || p.model, p, false);
            // Muzzle flashes from the arena's own bullet manager (same as in game).
            if (this._arenaBm && this._arenaBm.drawMuzzleFlashes && this._arenaBm.currentShipModel) {
                this._arenaBm.drawMuzzleFlashes(ctx, p);
            }
            ctx.globalAlpha = 1;
            this.drawBar(ctx, p.x, p.y + p.height + 2, p.width, p.health / p.maxHealth, '#88ff88');
            if (p.shieldMax > 0) {
                this.drawBar(ctx, p.x, p.y + p.height + 5, p.width, p.shield / p.shieldMax, accent);
                const threat = this.getShieldThreatProximity(p, 'player');
                const cs = p.chargeStats || {};
                const maxMs = cs.maxChargeMs || 900;
                const level = p.charging ? Math.min(1, p.charge / maxMs) : 0;
                const syncVis = !!(p.charging && cs.shieldSync && p.shield > 0);
                if (threat > 0.01 || syncVis) {
                    const strength = p.shield / p.shieldMax;
                    const pulseSpeed = 2 + level * 6;
                    const pulse = syncVis
                        ? (0.55 + 0.45 * (0.5 + 0.5 * Math.sin(Date.now() / 1000 * pulseSpeed * Math.PI * 2)))
                        : 1;
                    const thick = syncVis ? (2 + Math.round(level * 3)) : 2;
                    const base = syncVis
                        ? Math.max(threat, 0.35 + 0.55 * level)
                        : threat;
                    this.drawShieldHull(
                        ctx, p.model, p, false,
                        base * (0.45 + 0.55 * strength),
                        syncVis ? { thick: thick, pulse: pulse } : null
                    );
                }
            }
            if (p.charging && p.charge > 0) {
                const maxMs = (p.chargeStats && p.chargeStats.maxChargeMs) || 900;
                const r = Math.min(1, p.charge / maxMs);
                ctx.fillStyle = accent;
                ctx.globalAlpha = 0.35 + r * 0.5;
                ctx.fillRect(p.x + p.width / 2 - 1, p.y - 12 - r * 10, 2, 8 + r * 10);
                ctx.globalAlpha = 1;
            }
        }

        this.drawHud(ctx, p, accent);

        sim.hits.forEach((h) => {
            ctx.globalAlpha = Math.max(0.2, h.life / 220);
            ctx.fillStyle = '#ffffff';
            ctx.font = '10px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('-' + h.dmg, h.x, h.y);
        });
        ctx.globalAlpha = 1;
    },
});


/* --- js/ui/hangar-test-arena.js --- */
"use strict";

// HangarTestArena is defined in hangar-test-arena/core.js and extended by the other files in hangar-test-arena/,
// which index.html loads before this file.
var hangarTestArena = new HangarTestArena();
window.hangarTestArena = hangarTestArena;


/* --- js/ui/soundtrack-editor.js --- */
"use strict";

// Soundtrack Editor (dev mode → Settings → Soundtrack Editor):
// YouTube / local audio / vftrack JSON per screen·stage·enemy, plus planet
// tracker library import/export for LLM-authored chiptune loops.
// Kind `screen` owns start-screen Hauptmelodien (Start hub + Title fanfare).
var SoundtrackEditorUI = class SoundtrackEditorUI {
    constructor() {
        this.selectedKind = 'screen';
        this.selectedId = 'start';
        this.customScreenEntriesKey = 'vf_soundtrack_screen_entries_v1';
        this.ensureOverlay();
    }

    /** Devmode-added screen entries, persisted across reloads. */
    loadCustomScreenEntries() {
        try {
            const raw = localStorage.getItem(this.customScreenEntriesKey);
            const parsed = raw ? JSON.parse(raw) : [];
            return Array.isArray(parsed) ? parsed : [];
        } catch (e) {
            return [];
        }
    }

    saveCustomScreenEntries(entries) {
        try {
            localStorage.setItem(this.customScreenEntriesKey, JSON.stringify(entries));
        } catch (e) { /* storage unavailable or quota exceeded */ }
    }

    /** Screen-role tracks: id → library key + label. */
    getScreenEntries() {
        const defaults = [
            { id: 'start', key: 'menu', label: 'START SCREEN' },
            { id: 'title', key: 'title-intro', label: 'TITLE FANFARE' }
        ];
        return defaults.concat(this.loadCustomScreenEntries());
    }

    addScreenEntry() {
        const label = window.prompt('Screentyp Name (z.B. CREDITS SCREEN):');
        if (!label || !label.trim()) return;
        const id = window.prompt('Screentyp ID (eindeutig, z.B. credits):', label.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-'));
        if (!id || !id.trim()) return;
        const key = window.prompt('Library Key für diesen Screentyp (z.B. credits-theme):', id.trim());
        if (!key || !key.trim()) return;
        const entries = this.loadCustomScreenEntries();
        const cleanId = id.trim();
        if (this.getScreenEntries().some((e) => e.id === cleanId)) {
            window.alert('ID bereits vorhanden.');
            return;
        }
        entries.push({ id: cleanId, key: key.trim(), label: label.trim().toUpperCase() });
        this.saveCustomScreenEntries(entries);
        this.selectedKind = 'screen';
        this.selectedId = cleanId;
        this.render();
    }

    removeScreenEntry(id) {
        const entries = this.loadCustomScreenEntries().filter((e) => e.id !== id);
        this.saveCustomScreenEntries(entries);
        if (this.selectedKind === 'screen' && this.selectedId === id) {
            this.selectedKind = 'screen';
            this.selectedId = 'start';
        }
        this.render();
    }

    screenLibraryKey(id) {
        const hit = this.getScreenEntries().find((e) => e.id === id);
        return hit ? hit.key : String(id || 'menu');
    }

    getStageIds() {
        if (typeof levelManager !== 'undefined' && levelManager.getAllStageIds) {
            try {
                const ids = levelManager.getAllStageIds();
                if (Array.isArray(ids) && ids.length) return ids;
            } catch (e) { /* fall through */ }
        }
        return [];
    }

    getEnemyTypeIds() {
        const ids = [];
        if (typeof enemyConfigManager !== 'undefined' && enemyConfigManager.getTypeIds) {
            try { ids.push(...enemyConfigManager.getTypeIds()); } catch (e) { /* ignore */ }
        }
        if (!ids.length && typeof planetConfigManager !== 'undefined' && planetConfigManager.availableEnemyTypes) {
            ids.push(...planetConfigManager.availableEnemyTypes);
        }
        ids.push('boss');
        return [...new Set(ids)];
    }

    getPlanetIds() {
        return ['mars', 'jupiter', 'saturn', 'neptune', 'pluto',
            'mars-boss', 'jupiter-boss', 'saturn-boss', 'neptune-boss', 'pluto-boss'];
    }

    getFactionIds() {
        if (typeof VFTrackerFactionCompose !== 'undefined') return VFTrackerFactionCompose.FACTIONS.slice();
        return ['terran', 'kronax', 'voidborn', 'pirate', 'machine'];
    }

    getFactionCombatKeys() {
        const out = [];
        this.getPlanetIds().filter((p) => p.indexOf('boss') === -1).forEach((p) => {
            this.getFactionIds().forEach((f) => {
                out.push(p + ':' + f);
                out.push(p + '-boss:' + f);
            });
        });
        this.getFactionIds().forEach((f) => out.push('faction:' + f));
        return out;
    }

    getEndingKeys() {
        const out = ['victory', 'lose'];
        this.getFactionIds().forEach((f) => {
            out.push('victory:' + f);
            out.push('lose:' + f);
        });
        return out;
    }

    ensureOverlay() {
        if (document.getElementById('soundtrackEditorOverlay')) return;
        const overlay = document.createElement('div');
        overlay.id = 'soundtrackEditorOverlay';
        overlay.className = 'difficulty-editor-overlay hidden';
        overlay.innerHTML = `
            <div class="difficulty-editor-panel">
                <header class="difficulty-editor-header">
                    <h2>SOUNDTRACK EDITOR</h2>
                    <button type="button" class="pe-btn" id="steCurrentSelection"></button>
                    <button type="button" class="de-close" id="steClose">×</button>
                </header>
                <div class="difficulty-editor-body">
                    <aside class="difficulty-editor-nav">
                        <div class="de-section-title">SCREEN</div>
                        <div id="steScreenList"></div>
                        <div class="de-section-title">MEDIA OVERRIDE</div>
                        <div id="steMenuList"></div>
                        <div class="de-section-title">PLANET TRACKER</div>
                        <div id="stePlanetList"></div>
                        <div class="de-section-title">PLANET × FACTION</div>
                        <div id="steFactionList"></div>
                        <div class="de-section-title">VICTORY / LOSE</div>
                        <div id="steEndingList"></div>
                        <div class="de-section-title">STAGES</div>
                        <div id="steStageList"></div>
                        <div class="de-section-title">ENEMY TYPES</div>
                        <div id="steEnemyList"></div>
                    </aside>
                    <main class="difficulty-editor-controls" id="steControls"></main>
                </div>
                <footer class="difficulty-editor-footer">
                    <button type="button" class="pe-btn" id="steBack">BACK</button>
                </footer>
            </div>`;
        document.body.appendChild(overlay);
        const q = (s) => overlay.querySelector(s);
        q('#steClose').addEventListener('click', () => this.hide());
        q('#steBack').addEventListener('click', () => this.hide());
        q('#steCurrentSelection').addEventListener('click', () => {
            const host = document.getElementById('steControls');
            if (host) host.scrollIntoView({ block: 'nearest' });
        });
        overlay.addEventListener('keydown', (e) => {
            if (e.target && (e.target.tagName === 'TEXTAREA' || e.target.tagName === 'INPUT')) {
                if (e.key === 'Escape') this.hide();
                return;
            }
            e.stopPropagation();
            if (e.key === 'Escape') this.hide();
        });
    }

    renderNavButton(container, label, kind, id, hasMark, onRemove) {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'de-profile-btn';
        b.textContent = (hasMark ? '♪ ' : '') + label + (onRemove ? ' ×' : '');
        if (kind === this.selectedKind && id === this.selectedId) b.classList.add('pe-primary');
        b.addEventListener('click', (e) => {
            if (onRemove && e.offsetX > b.clientWidth - 18) {
                if (window.confirm('Screentyp "' + label + '" entfernen?')) onRemove();
                return;
            }
            this.selectedKind = kind;
            this.selectedId = id;
            this.render();
        });
        container.appendChild(b);
    }

    show() {
        this.ensureOverlay();
        this._returnToSettings = !!(typeof startScreenManager !== 'undefined' && startScreenManager
            && (startScreenManager.showSettings || startScreenManager.overlayMode || startScreenManager.embeddedMode));
        if (typeof startScreenManager !== 'undefined' && startScreenManager) {
            if (startScreenManager.overlayMode) startScreenManager.hideOverlay();
            if (startScreenManager.embeddedMode) startScreenManager.hideEmbedded();
        }
        if (typeof settingsManager !== 'undefined' && settingsManager.hideSettings) settingsManager.hideSettings();
        const overlay = document.getElementById('soundtrackEditorOverlay');
        if (overlay.parentNode !== document.body) document.body.appendChild(overlay);
        overlay.classList.remove('hidden');
        this.render();
    }

    hide() {
        const overlay = document.getElementById('soundtrackEditorOverlay');
        if (overlay) overlay.classList.add('hidden');
        if (typeof localAudioManager !== 'undefined') localAudioManager.stop();
        if (typeof vfTrackerManager !== 'undefined') vfTrackerManager.stop();
        if (this._returnToSettings && typeof startScreenManager !== 'undefined' && startScreenManager) {
            this._returnToSettings = false;
            startScreenManager.showSettings = true;
            startScreenManager.showCredits = false;
            if (startScreenManager.hasActiveProfile && startScreenManager.hasActiveProfile()
                && typeof homeStationUI !== 'undefined') {
                if (!homeStationUI.isVisible) homeStationUI.show({ skipPersist: true });
                startScreenManager.show({ asOverlay: true, showSettings: true });
            } else {
                startScreenManager.show({ forceMenu: true });
            }
        }
    }

    render() {
        const screenList = document.getElementById('steScreenList');
        const menuList = document.getElementById('steMenuList');
        const planetList = document.getElementById('stePlanetList');
        const factionList = document.getElementById('steFactionList');
        const endingList = document.getElementById('steEndingList');
        const stageList = document.getElementById('steStageList');
        const enemyList = document.getElementById('steEnemyList');
        if (screenList) screenList.innerHTML = '';
        menuList.innerHTML = '';
        planetList.innerHTML = '';
        if (factionList) factionList.innerHTML = '';
        if (endingList) endingList.innerHTML = '';
        stageList.innerHTML = '';
        enemyList.innerHTML = '';

        const customScreenIds = this.loadCustomScreenEntries().map((e) => e.id);
        this.getScreenEntries().forEach((entry) => {
            const custom = typeof vfTrackerManager !== 'undefined' && vfTrackerManager.library[entry.key];
            if (screenList) {
                this.renderNavButton(screenList, entry.label, 'screen', entry.id, !!custom,
                    customScreenIds.indexOf(entry.id) !== -1 ? () => this.removeScreenEntry(entry.id) : null);
            }
        });
        if (screenList) {
            const addBtn = document.createElement('button');
            addBtn.type = 'button';
            addBtn.className = 'de-profile-btn';
            addBtn.textContent = '+ ADD SCREENTYP';
            addBtn.addEventListener('click', () => this.addScreenEntry());
            screenList.appendChild(addBtn);
        }

        const menuHas = typeof soundtrackConfigManager !== 'undefined'
            && soundtrackConfigManager.hasTrack(soundtrackConfigManager.getMenuTrack());
        this.renderNavButton(menuList, 'Start Media', 'menu', 'menu', menuHas);

        this.getPlanetIds().forEach((id) => {
            const custom = typeof vfTrackerManager !== 'undefined' && vfTrackerManager.library[id];
            this.renderNavButton(planetList, id, 'planet', id, !!custom);
        });
        if (factionList) {
            this.getFactionCombatKeys().forEach((id) => {
                const custom = typeof vfTrackerManager !== 'undefined' && vfTrackerManager.library[id];
                this.renderNavButton(factionList, id, 'planet', id, !!custom);
            });
        }
        if (endingList) {
            this.getEndingKeys().forEach((id) => {
                const custom = typeof vfTrackerManager !== 'undefined' && vfTrackerManager.library[id];
                this.renderNavButton(endingList, id, 'planet', id, !!custom);
            });
        }

        this.getStageIds().forEach((id) => {
            const has = typeof soundtrackConfigManager !== 'undefined'
                && soundtrackConfigManager.hasTrack(soundtrackConfigManager.getStageTrack(id));
            this.renderNavButton(stageList, id, 'stage', id, has);
        });
        this.getEnemyTypeIds().forEach((id) => {
            const has = typeof soundtrackConfigManager !== 'undefined'
                && soundtrackConfigManager.hasTrack(soundtrackConfigManager.getEnemyTrack(id));
            this.renderNavButton(enemyList, id, 'enemy', id, has);
        });

        this._updateCurrentSelectionLabel();

        const host = document.getElementById('steControls');
        host.innerHTML = '';
        if (!this.selectedId) {
            const hint = document.createElement('p');
            hint.className = 'ss-code-hint';
            hint.textContent = 'SCREEN = start-screen Hauptmelodie. Planet×faction combat, then stage/enemy overrides.';
            host.appendChild(hint);
            return;
        }
        if (this.selectedKind === 'screen') this.renderScreenTracker(host, this.selectedId);
        else if (this.selectedKind === 'planet') this.renderPlanetTracker(host, this.selectedId);
        else this.renderOverrideEditor(host, this.selectedKind, this.selectedId);
    }

    /** Header button that always shows the currently selected nav entry. */
    _updateCurrentSelectionLabel() {
        const btn = document.getElementById('steCurrentSelection');
        if (!btn) return;
        if (!this.selectedId) {
            btn.textContent = 'KEINE AUSWAHL';
            return;
        }
        let label = this.selectedId;
        if (this.selectedKind === 'screen') {
            const entry = this.getScreenEntries().find((e) => e.id === this.selectedId);
            if (entry) label = entry.label;
        } else if (this.selectedKind === 'menu') {
            label = 'START MEDIA';
        } else if (this.selectedKind === 'stage') {
            label = 'STAGE: ' + this.selectedId;
        } else if (this.selectedKind === 'enemy') {
            label = 'ENEMY: ' + this.selectedId;
        } else if (this.selectedKind === 'planet') {
            label = this.selectedId;
        }
        btn.textContent = 'AUSGEWÄHLT: ' + label;
    }

    _stopPreview() {
        if (typeof localAudioManager !== 'undefined') localAudioManager.stop();
        if (typeof youtubeSoundtrackManager !== 'undefined') youtubeSoundtrackManager.stop();
        if (typeof vfTrackerManager !== 'undefined') vfTrackerManager.stop();
    }

    _addTrackerTools(host, opts) {
        const { getJson, setJson, libraryKey, title } = opts;

        const section = document.createElement('div');
        section.className = 'de-section-title';
        section.textContent = title || 'VF TRACKER (.vftrack.json)';
        host.appendChild(section);

        const hint = document.createElement('p');
        hint.className = 'ss-code-hint';
        hint.textContent = 'Code / LLM authored chiptune. Import JSON from Gemini etc., or export + edit with assets/soundtracks/LLM_PROMPT.md';
        host.appendChild(hint);

        const ta = document.createElement('textarea');
        ta.rows = 14;
        ta.spellcheck = false;
        ta.style.width = '100%';
        ta.style.fontFamily = 'monospace';
        ta.style.fontSize = '11px';
        ta.value = getJson() || '';
        ta.addEventListener('keydown', (e) => e.stopPropagation());
        host.appendChild(ta);

        const status = document.createElement('p');
        status.className = 'ss-code-hint';
        status.id = 'steTrackerStatus';
        host.appendChild(status);

        const btnRow = document.createElement('div');
        btnRow.className = 'de-slider-row';

        const applyBtn = document.createElement('button');
        applyBtn.type = 'button';
        applyBtn.className = 'pe-btn pe-primary';
        applyBtn.textContent = 'APPLY JSON';
        applyBtn.addEventListener('click', () => {
            try {
                setJson(ta.value);
                status.textContent = 'Applied.';
                this.render();
            } catch (e) {
                status.textContent = 'Error: ' + (e && e.message ? e.message : e);
            }
        });

        const previewBtn = document.createElement('button');
        previewBtn.type = 'button';
        previewBtn.className = 'pe-btn';
        previewBtn.textContent = 'PREVIEW';
        previewBtn.addEventListener('click', () => {
            try {
                const data = JSON.parse(ta.value);
                this._stopPreview();
                if (typeof soundManager !== 'undefined' && soundManager.ensureContext) soundManager.ensureContext();
                if (typeof vfTrackerManager !== 'undefined') {
                    const bus = (typeof soundManager !== 'undefined' && soundManager.musicBusVolume)
                        ? soundManager.musicBusVolume()
                        : ((typeof VFVolume !== 'undefined') ? VFVolume.busDefault() : 0.065);
                    vfTrackerManager.setVolume(bus);
                    vfTrackerManager.play('preview:' + (libraryKey || 'edit'), data);
                    status.textContent = 'Playing preview…';
                }
            } catch (e) {
                status.textContent = 'Error: ' + (e && e.message ? e.message : e);
            }
        });

        const stopBtn = document.createElement('button');
        stopBtn.type = 'button';
        stopBtn.className = 'pe-btn';
        stopBtn.textContent = 'STOP';
        stopBtn.addEventListener('click', () => {
            this._stopPreview();
            status.textContent = 'Stopped.';
        });

        const exportBtn = document.createElement('button');
        exportBtn.type = 'button';
        exportBtn.className = 'pe-btn';
        exportBtn.textContent = 'EXPORT';
        exportBtn.addEventListener('click', () => {
            try {
                const compact = VFTrackerParse.toCompact(JSON.parse(ta.value));
                const json = JSON.stringify(compact, null, 2);
                const blob = new Blob([json], { type: 'application/json' });
                const a = document.createElement('a');
                a.href = URL.createObjectURL(blob);
                a.download = (libraryKey || 'track') + '.vftrack.json';
                document.body.appendChild(a);
                a.click();
                setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 400);
                status.textContent = 'Exported.';
            } catch (e) {
                status.textContent = 'Export error: ' + (e && e.message ? e.message : e);
            }
        });

        const importBtn = document.createElement('button');
        importBtn.type = 'button';
        importBtn.className = 'pe-btn';
        importBtn.textContent = 'IMPORT FILE';
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = '.json,application/json,.vftrack.json';
        fileInput.style.display = 'none';
        fileInput.addEventListener('change', () => {
            const file = fileInput.files && fileInput.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = () => {
                ta.value = String(reader.result || '');
                status.textContent = 'Loaded ' + file.name + ' — press APPLY JSON.';
            };
            reader.readAsText(file);
        });
        importBtn.addEventListener('click', () => fileInput.click());

        const promptBtn = document.createElement('button');
        promptBtn.type = 'button';
        promptBtn.className = 'pe-btn';
        promptBtn.textContent = 'COPY LLM PROMPT';
        promptBtn.addEventListener('click', async () => {
            const planet = libraryKey || this.selectedId || 'mars';
            const prompt = this.buildLlmPrompt(planet);
            try {
                await navigator.clipboard.writeText(prompt);
                status.textContent = 'LLM prompt copied.';
            } catch (e) {
                ta.value = prompt;
                status.textContent = 'Clipboard blocked — prompt pasted into the editor.';
            }
        });

        const resetBtn = document.createElement('button');
        resetBtn.type = 'button';
        resetBtn.className = 'pe-btn';
        resetBtn.textContent = 'RESET DEFAULT';
        resetBtn.addEventListener('click', () => {
            setJson(null);
            status.textContent = 'Reverted to built-in default.';
            this.render();
        });

        btnRow.append(applyBtn, previewBtn, stopBtn, exportBtn, importBtn, promptBtn, resetBtn, fileInput);
        host.appendChild(btnRow);
    }

    buildLlmPrompt(planet) {
        const p = String(planet || 'mars');
        return [
            'You write chiptune tracker songs for GLXEE / VolleyFire.',
            'Output ONLY valid JSON, format "vftrack" version 1. No markdown.',
            '',
            'Schema: format, version, meta{title,author,planet,notes}, bpm, rowsPerBeat:1,',
            'rowsPerPattern:16, channels:4, instruments[{id,name,wave,volume,attack,decay,sustain,release,filter}],',
            'patterns[{id, channels:["tok tok ..."]}], order:[0], loop:true.',
            '',
            'Each channels[i] has exactly 16 space-separated tokens.',
            'Tokens: "." | "OFF" | "C-2:1" | "C-2:1:64" | "C#4:2:40" | "Eb3:3:32"',
            'waves: sine|square|sawtooth|triangle|noise. Volume on notes 0-64.',
            'ch0 bass, ch1 lead, ch2 arp, ch3 kick+hat. Sci-fi minor mood.',
            '',
            'Write a vftrack for planet "' + p + '". BPM 84-118. Title something thematic.',
            'Return only the JSON object.'
        ].join('\n');
    }

    renderPlanetTracker(host, planetId) {
        const title = document.createElement('div');
        title.className = 'de-section-title';
        title.textContent = 'PLANET TRACKER: ' + planetId;
        host.appendChild(title);

        this._addTrackerTools(host, {
            libraryKey: planetId,
            title: 'VF TRACKER JSON',
            getJson: () => {
                if (typeof vfTrackerManager === 'undefined') return '';
                return vfTrackerManager.exportJson(planetId) || '';
            },
            setJson: (text) => {
                if (typeof vfTrackerManager === 'undefined') throw new Error('tracker manager missing');
                if (text == null || String(text).trim() === '') {
                    vfTrackerManager.setTrack(planetId, null);
                    return;
                }
                vfTrackerManager.importJson(planetId, text);
            }
        });
    }

    /** Type `screen`: Start hub + Title fanfare Hauptmelodien (library keys menu / title-intro). */
    renderScreenTracker(host, screenId) {
        const entry = this.getScreenEntries().find((e) => e.id === screenId) || this.getScreenEntries()[0];
        const key = entry.key;
        const title = document.createElement('div');
        title.className = 'de-section-title';
        title.textContent = 'SCREEN · ' + entry.label + ' (' + key + ')';
        host.appendChild(title);

        const hint = document.createElement('p');
        hint.className = 'ss-code-hint';
        hint.textContent = screenId === 'title'
            ? 'One-shot title fanfare before the Start Screen loop. Set loop:false in the JSON.'
            : screenId === 'start'
                ? 'Start Screen / Planet Select Hauptmelodie. Media override (YouTube / local) lives under MEDIA OVERRIDE.'
                : 'Benutzerdefinierter Screentyp (Library Key "' + key + '"). Wiedergabe erfolgt nur, wenn dieser Key an entsprechender Stelle im Code abgespielt wird.';
        host.appendChild(hint);

        this._addTrackerTools(host, {
            libraryKey: key,
            title: 'VF TRACKER JSON · TYPE SCREEN',
            getJson: () => {
                if (typeof vfTrackerManager === 'undefined') return '';
                return vfTrackerManager.exportJson(key) || '';
            },
            setJson: (text) => {
                if (typeof vfTrackerManager === 'undefined') throw new Error('tracker manager missing');
                if (text == null || String(text).trim() === '') {
                    vfTrackerManager.setTrack(key, null);
                } else {
                    vfTrackerManager.importJson(key, text);
                }
                if (typeof soundManager !== 'undefined' && soundManager.startMenuMusic) {
                    // Force title fanfare / hub to pick up the new screen track.
                    if (screenId === 'title') soundManager._titleIntroDone = false;
                    soundManager.startMenuMusic();
                }
            }
        });
    }

    renderOverrideEditor(host, kind, id) {
        const title = document.createElement('div');
        title.className = 'de-section-title';
        title.textContent = (kind === 'menu' ? 'START MEDIA OVERRIDE' : kind === 'stage' ? 'STAGE: ' + id : 'ENEMY TYPE: ' + id);
        host.appendChild(title);

        const getTrack = () => {
            const t = kind === 'menu' ? soundtrackConfigManager.getMenuTrack()
                : kind === 'stage' ? soundtrackConfigManager.getStageTrack(id)
                : soundtrackConfigManager.getEnemyTrack(id);
            return t || { youtubeUrl: '', localAudioData: '', localAudioName: '', trackerData: null };
        };
        const setTrack = (data) => {
            if (kind === 'menu') soundtrackConfigManager.setMenuTrack(data);
            else if (kind === 'stage') soundtrackConfigManager.setStageTrack(id, data);
            else soundtrackConfigManager.setEnemyTrack(id, data);
            if (kind === 'menu' && typeof soundManager !== 'undefined' && soundManager.startMenuMusic) {
                soundManager.startMenuMusic();
            }
            this.render();
        };

        const track = getTrack();

        const urlRow = document.createElement('div');
        urlRow.className = 'de-slider-row';
        const urlLabel = document.createElement('label');
        urlLabel.textContent = 'YOUTUBE URL';
        const urlInput = document.createElement('input');
        urlInput.type = 'text';
        urlInput.placeholder = 'https://youtu.be/...';
        urlInput.value = track.youtubeUrl || '';
        urlInput.spellcheck = false;
        urlInput.addEventListener('keydown', (e) => e.stopPropagation());
        urlInput.addEventListener('change', () => {
            setTrack({
                youtubeUrl: urlInput.value.trim(),
                localAudioData: '',
                localAudioName: '',
                trackerData: null
            });
        });
        urlRow.append(urlLabel, urlInput);
        host.appendChild(urlRow);

        const fileRow = document.createElement('div');
        fileRow.className = 'de-slider-row';
        const fileLabel = document.createElement('label');
        fileLabel.textContent = 'LOCAL AUDIO';
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = 'audio/*';
        fileInput.addEventListener('change', () => {
            const file = fileInput.files && fileInput.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = () => {
                setTrack({
                    youtubeUrl: '',
                    localAudioData: reader.result,
                    localAudioName: file.name,
                    trackerData: null
                });
            };
            reader.readAsDataURL(file);
        });
        fileRow.append(fileLabel, fileInput);
        host.appendChild(fileRow);

        if (track.localAudioName) {
            const fileNote = document.createElement('p');
            fileNote.className = 'ss-code-hint';
            fileNote.textContent = 'Current file: ' + track.localAudioName;
            host.appendChild(fileNote);
        }

        const btnRow = document.createElement('div');
        btnRow.className = 'de-slider-row';
        const previewBtn = document.createElement('button');
        previewBtn.type = 'button';
        previewBtn.className = 'pe-btn';
        previewBtn.textContent = 'PREVIEW MEDIA';
        previewBtn.addEventListener('click', () => {
            const t = getTrack();
            this._stopPreview();
            if (t.localAudioData && typeof localAudioManager !== 'undefined') {
                localAudioManager.setVolume(0.3);
                localAudioManager.play('preview:' + kind + ':' + id, t.localAudioData);
            } else if (t.trackerData && typeof vfTrackerManager !== 'undefined') {
                if (typeof soundManager !== 'undefined' && soundManager.ensureContext) soundManager.ensureContext();
                vfTrackerManager.setVolume(0.35);
                vfTrackerManager.play('preview:' + kind + ':' + id, t.trackerData);
            } else if (t.youtubeUrl && typeof youtubeSoundtrackManager !== 'undefined') {
                youtubeSoundtrackManager.setEnabled(true);
                youtubeSoundtrackManager.setVolume(0.3);
                youtubeSoundtrackManager.playUrl('preview:' + kind + ':' + id, t.youtubeUrl);
            }
        });
        const clearBtn = document.createElement('button');
        clearBtn.type = 'button';
        clearBtn.className = 'pe-btn';
        clearBtn.textContent = 'CLEAR';
        clearBtn.addEventListener('click', () => {
            this._stopPreview();
            setTrack(null);
        });
        btnRow.append(previewBtn, clearBtn);
        host.appendChild(btnRow);

        this._addTrackerTools(host, {
            libraryKey: kind + '-' + id,
            title: 'OR ASSIGN VF TRACKER JSON',
            getJson: () => {
                const t = getTrack();
                if (!t.trackerData) return '';
                try {
                    return JSON.stringify(VFTrackerParse.toCompact(t.trackerData), null, 2);
                } catch (e) {
                    return JSON.stringify(t.trackerData, null, 2);
                }
            },
            setJson: (text) => {
                if (text == null || String(text).trim() === '') {
                    const cur = getTrack();
                    if (cur.youtubeUrl || cur.localAudioData) {
                        setTrack({
                            youtubeUrl: cur.youtubeUrl || '',
                            localAudioData: cur.localAudioData || '',
                            localAudioName: cur.localAudioName || '',
                            trackerData: null
                        });
                    } else {
                        setTrack(null);
                    }
                    return;
                }
                const data = VFTrackerParse.toCompact(JSON.parse(text));
                setTrack({
                    youtubeUrl: '',
                    localAudioData: '',
                    localAudioName: '',
                    trackerData: data
                });
            }
        });
    }
}

var soundtrackEditorUI = new SoundtrackEditorUI();


/* --- js/ui/hud-layout-editor.js --- */
"use strict";

/**
 * Dev-mode HUD layout editor. The combat HUD panels stay in normal flex flow — this only lets
 * the player (a) reorder panels within their own cluster via a drag grip, and (b) drag the
 * boundary between two adjacent panels to resize them (an explicit pixel height via flex-basis),
 * rather than freely moving/resizing panels. Persisted to localStorage. Only reachable while
 * startScreenManager.devMode is on.
 *
 * Resizing uses a plain height, not `zoom`: zoom was tried first so a panel's content (text,
 * icons, bars) would scale together with it, but on the game's tightly packed icon rows (the
 * under-stage stat bar in particular) it produced overlapping, garbled icons — the combination of
 * this zoom with the stage's own existing zoom/transform layers doesn't render cleanly for that
 * kind of content. A plain height is quietly safe: the panel just gets more or less room, its
 * content never gets distorted.
 */
var hudLayoutEditor = (function () {
    const STORAGE_KEY = 'vf_hud_layout_v4';
    const CLUSTER_SELECTORS = ['#gameLeftCluster', '.game-canvas-container', '#gameRightCluster'];
    const GAME_CONTAINER_SEL = '.game-container';
    const MIN_H = 30, MAX_H = 2000;
    const MIN_SIDE_W = 140, MAX_SIDE_W = 460;
    // Dragging the boundary between a side cluster and the playfield resizes that cluster's width
    // directly (not via zoom — it's a column width, not panel content); the canvas column is
    // `flex: 1 1 auto` already, so it absorbs whatever width the side cluster gives up or takes,
    // i.e. "the game gets resized" as a natural side effect, with no extra code needed for that.
    const CONTAINER_SPLITTERS = [
        { clusterSel: '#gameLeftCluster', sign: 1 },
        { clusterSel: '#gameRightCluster', sign: -1 }
    ];

    let layout = { clusters: {}, container: {}, scales: {} };
    try {
        const raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
        if (raw && raw.clusters) layout = raw;
        if (!layout.container) layout.container = {};
        if (!layout.scales) layout.scales = {};
    } catch (e) { /* ignore */ }

    const originalOrder = {}; // clusterSel -> [childKey, ...] as authored, captured once at boot

    let editing = false;
    const liveGrips = []; // { child, grip }
    const livePickers = []; // { child, btn }
    const liveSplitters = []; // element refs
    let picker = null; // the open content-picker popover, or null

    // Every panel across all three clusters that a slot can be made to show, keyed by a selector
    // stable enough to find it wherever it currently lives (its id/class never changes, only its
    // parent does). .game-stage is deliberately absent: it's the actual game canvas, sized by the
    // game's own viewport-fit code, never a swappable slot.
    const PANEL_REGISTRY = [
        { sel: '#gameInfoPanel', label: 'INFO' },
        { sel: '.weapon-selection', label: 'WEAPONS' },
        { sel: '.player-vitals-side', label: 'PLAYER VITALS' },
        { sel: '#giLoadoutSide', label: 'LOADOUT' },
        { sel: '.enemy-vitals-side', label: 'ENEMY VITALS' },
        { sel: '#giMissionSide', label: 'MISSION' },
        { sel: '#giUnderStage', label: 'UNDER-STAGE BAR' }
    ];

    function findPanelByKey(k) {
        for (let i = 0; i < PANEL_REGISTRY.length; i++) {
            const el = document.querySelector(PANEL_REGISTRY[i].sel);
            if (el && childKey(el) === k) return el;
        }
        return null;
    }

    function isActive() {
        return typeof startScreenManager !== 'undefined' && !!startScreenManager.devMode;
    }

    // The stage sits under several stacked, independent scale layers (CSS `zoom`, `transform:
    // scale`, possibly more) between an authored CSS pixel and what getBoundingClientRect() /
    // mouse coordinates report. Rather than track down and multiply every factor by name (fragile
    // — a new layer silently breaks the math again), measure the combined effect directly: drop an
    // invisible probe of a known authored size into the same parent and compare its rendered size.
    function measureScale(referenceEl) {
        const parent = referenceEl && referenceEl.nodeType === 1 ? referenceEl : document.body;
        const probe = document.createElement('div');
        probe.style.cssText = 'position:absolute;left:0;top:0;width:2000px;height:2000px;margin:0;border:0;padding:0;visibility:hidden;pointer-events:none;';
        parent.appendChild(probe);
        const w = probe.getBoundingClientRect().width;
        probe.remove();
        return w > 0 ? w / 2000 : 1;
    }

    function saveLayout() {
        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(layout)); } catch (e) { /* ignore */ }
    }

    function childKey(el) {
        if (el.id) return '#' + el.id;
        const cls = (el.className || '').toString().trim().split(/\s+/)[0];
        if (cls) return '.' + cls;
        return 'idx' + Array.prototype.indexOf.call(el.parentElement ? el.parentElement.children : [], el);
    }

    function clusterEntry(sel) {
        if (!layout.clusters[sel]) layout.clusters[sel] = { order: [], sizes: {} };
        return layout.clusters[sel];
    }

    // Direct children of a cluster that are real HUD panels, excluding the splitter bars we
    // inject ourselves while editing.
    function liveChildren(cluster) {
        return Array.prototype.filter.call(cluster.children, function (c) {
            return !c.hasAttribute('data-hle-splitter');
        });
    }

    function clusterSelOf(cluster) {
        return CLUSTER_SELECTORS.filter(function (s) { return document.querySelector(s) === cluster; })[0] || null;
    }

    function applySaved() {
        CLUSTER_SELECTORS.forEach(function (sel) {
            const cluster = document.querySelector(sel);
            if (!cluster) return;
            const entry = layout.clusters[sel];
            if (entry && entry.order && entry.order.length) {
                // Looked up globally (not just among this cluster's current children) so a panel
                // the player dragged into a DIFFERENT cluster via the content picker gets moved
                // back there too, not just reordered within whatever cluster it happens to already
                // be in.
                entry.order.forEach(function (k) {
                    const el = findPanelByKey(k);
                    if (el) cluster.appendChild(el);
                });
            }
            liveChildren(cluster).forEach(function (c) {
                const h = entry && entry.sizes && entry.sizes[childKey(c)];
                if (h) {
                    ownPanelBox(c);
                    c.style.flexGrow = '0';
                    c.style.flexShrink = '0';
                    c.style.flexBasis = h + 'px';
                    c.dataset.hleSized = '1';
                }
            });
        });
        CONTAINER_SPLITTERS.forEach(function (cfg) {
            const w = layout.container && layout.container[cfg.clusterSel];
            const el = w && document.querySelector(cfg.clusterSel);
            if (el) {
                el.style.width = w + 'px';
                el.dataset.hleSized = '1';
            }
        });
        applyAllScales();
    }

    // Icon/font size, set by the picker modal's sliders (see openPicker), keyed globally like
    // PANEL_REGISTRY rather than per-cluster — the scale belongs to the PANEL, not the slot, so it
    // travels with it across a content-picker swap into a different cluster.
    function applyScale(panel) {
        const s = layout.scales[childKey(panel)];
        panel.style.setProperty('--hle-icon-scale', s && s.icon ? s.icon : '');
        panel.style.setProperty('--hle-font-scale', s && s.font ? s.font : '');
    }

    function applyAllScales() {
        PANEL_REGISTRY.forEach(function (entry) {
            const el = document.querySelector(entry.sel);
            if (el) applyScale(el);
        });
    }

    function refreshOrder(cluster) {
        const sel = clusterSelOf(cluster);
        if (!sel) return;
        clusterEntry(sel).order = liveChildren(cluster).map(childKey);
    }

    function refreshAllOrders() {
        CLUSTER_SELECTORS.forEach(function (sel) {
            const cluster = document.querySelector(sel);
            if (cluster) clusterEntry(sel).order = liveChildren(cluster).map(childKey);
        });
    }

    // A splitter resizes only the two panels it directly sits between: the one before gains
    // exactly what the one after gives up (and vice versa), both pinned to an explicit flex-basis.
    // Non-adjacent panels (e.g. one further up the column) are never touched, regardless of their
    // own flex-grow/shrink — that would resize a panel the player never actually dragged a border
    // of.
    // Pinning a panel for the editor means OWNING its box model outright, not layering an inline
    // flex-basis on top of whatever the rest of the stylesheet happens to say. Earlier versions
    // only pinned flex-grow/shrink/basis and left each panel's own CSS min-height/max-height (a mix
    // of fixed clamps and percentages, written for the responsive auto-layout, not for a human
    // dragging a border) in effect — a growing panel would silently cap out against its own
    // max-height while the splitter kept being dragged, so the border froze there while the OTHER
    // panel in the pair (unaware anything stopped) kept shrinking; and panels not already
    // `box-sizing: border-box` jumped by their padding the instant they were pinned, because
    // flex-basis sizes the content box while getBoundingClientRect() reports the border box. Both
    // are instances of the same problem: two systems (this editor and the stylesheet) independently
    // claiming authority over the same box. The fix is to leave only one in charge — the moment a
    // panel is grabbed, this neutralizes every stylesheet constraint on its height (min/max-height,
    // box-sizing) with inline styles, so from then on flex-basis is the panel's one and only source
    // of size, bounded purely by the generous, editor-owned MIN_H/MAX_H.
    function ownPanelBox(panel) {
        panel.style.boxSizing = 'border-box';
        panel.style.minHeight = '0';
        panel.style.maxHeight = 'none';
    }

    function bindSplitter(splitter) {
        let prevPanel = null, nextPanel = null, startY = 0, startPrevH = 0, startNextH = 0, scale = 1;

        function onMove(e) {
            if (!prevPanel && !nextPanel) return;
            const dy = (startY - e.clientY) / scale;
            // Moving the splitter up grows the panel after it by taking exactly that much from the
            // panel before it (and vice versa), so the pair's combined height never changes. Both
            // panels' height is now fully owned by this editor (see ownPanelBox), so MIN_H/MAX_H are
            // the only limits left to honor — no external CSS constraint can intervene mid-drag.
            let nextH = startNextH + dy;
            let prevH = startPrevH - dy;
            if (nextH < MIN_H) { prevH -= (MIN_H - nextH); nextH = MIN_H; }
            if (prevH < MIN_H) { nextH -= (MIN_H - prevH); prevH = MIN_H; }
            nextH = Math.min(MAX_H, nextH);
            prevH = Math.min(MAX_H, prevH);
            if (nextPanel) { nextPanel.style.flexBasis = Math.round(nextH) + 'px'; nextPanel.dataset.hleSized = '1'; }
            if (prevPanel) { prevPanel.style.flexBasis = Math.round(prevH) + 'px'; prevPanel.dataset.hleSized = '1'; }
        }
        function onUp() {
            if (!prevPanel && !nextPanel) return;
            const cluster = splitter.parentElement;
            const sel = cluster && clusterSelOf(cluster);
            if (sel) {
                if (nextPanel) clusterEntry(sel).sizes[childKey(nextPanel)] = parseFloat(nextPanel.style.flexBasis) || 0;
                if (prevPanel) clusterEntry(sel).sizes[childKey(prevPanel)] = parseFloat(prevPanel.style.flexBasis) || 0;
            }
            prevPanel = null;
            nextPanel = null;
            window.removeEventListener('pointermove', onMove);
            window.removeEventListener('pointerup', onUp);
        }
        splitter.addEventListener('pointerdown', function (e) {
            if (e.button !== undefined && e.button !== 0) return;
            prevPanel = splitter.previousElementSibling;
            nextPanel = splitter.nextElementSibling;
            if (!prevPanel && !nextPanel) return;
            scale = measureScale(splitter.parentElement);
            // Panels can be `flex: 1 1 auto` in CSS (fills whatever space is left), so take over
            // the box first (see ownPanelBox) and set flex-basis to its CURRENT rendered height in
            // the same step, so pinning never itself jumps the layout — only the drag from here on
            // does.
            if (nextPanel) {
                ownPanelBox(nextPanel);
                startNextH = nextPanel.getBoundingClientRect().height / scale;
                nextPanel.style.flexGrow = '0';
                nextPanel.style.flexShrink = '0';
                nextPanel.style.flexBasis = startNextH + 'px';
                nextPanel.dataset.hleSized = '1';
            }
            if (prevPanel) {
                ownPanelBox(prevPanel);
                startPrevH = prevPanel.getBoundingClientRect().height / scale;
                prevPanel.style.flexGrow = '0';
                prevPanel.style.flexShrink = '0';
                prevPanel.style.flexBasis = startPrevH + 'px';
                prevPanel.dataset.hleSized = '1';
            }
            startY = e.clientY;
            e.preventDefault();
            e.stopPropagation();
            window.addEventListener('pointermove', onMove);
            window.addEventListener('pointerup', onUp, { once: true });
        });
    }

    function refreshSplitters(cluster) {
        Array.prototype.slice.call(cluster.querySelectorAll(':scope > [data-hle-splitter]')).forEach(function (s) {
            const i = liveSplitters.indexOf(s);
            if (i >= 0) liveSplitters.splice(i, 1);
            s.remove();
        });
        const children = liveChildren(cluster);
        children.forEach(function (child, i) {
            if (i >= children.length - 1) return;
            const splitter = document.createElement('div');
            splitter.className = 'hle-splitter';
            splitter.setAttribute('data-hle-splitter', '1');
            cluster.insertBefore(splitter, child.nextSibling);
            bindSplitter(splitter);
            liveSplitters.push(splitter);
        });
    }

    function bindContainerSplitter(splitter, cfg) {
        let startX = 0, startW = 0, scale = 1;
        const cluster = document.querySelector(cfg.clusterSel);

        function onMove(e) {
            if (!cluster) return;
            const dx = (e.clientX - startX) / scale;
            const w = Math.max(MIN_SIDE_W, Math.min(MAX_SIDE_W, Math.round(startW + cfg.sign * dx)));
            cluster.style.width = w + 'px';
            cluster.dataset.hleSized = '1';
        }
        function onUp() {
            window.removeEventListener('pointermove', onMove);
            window.removeEventListener('pointerup', onUp);
            if (!cluster) return;
            layout.container[cfg.clusterSel] = parseFloat(cluster.style.width) || 0;
        }
        splitter.addEventListener('pointerdown', function (e) {
            if (e.button !== undefined && e.button !== 0) return;
            if (!cluster) return;
            scale = measureScale(splitter.parentElement);
            startX = e.clientX;
            startW = cluster.getBoundingClientRect().width / scale;
            e.preventDefault();
            e.stopPropagation();
            window.addEventListener('pointermove', onMove);
            window.addEventListener('pointerup', onUp, { once: true });
        });
    }

    function setupContainerSplitters() {
        const container = document.querySelector(GAME_CONTAINER_SEL);
        if (!container) return;
        CONTAINER_SPLITTERS.forEach(function (cfg) {
            const cluster = document.querySelector(cfg.clusterSel);
            if (!cluster || cluster.parentElement !== container) return;
            const splitter = document.createElement('div');
            splitter.className = 'hle-vsplitter';
            splitter.setAttribute('data-hle-splitter', '1');
            splitter.setAttribute('data-hle-vsplitter', '1');
            if (cfg.sign > 0) container.insertBefore(splitter, cluster.nextSibling);
            else container.insertBefore(splitter, cluster);
            bindContainerSplitter(splitter, cfg);
            liveSplitters.push(splitter);
        });
    }

    function addGrip(child) {
        child.dataset.hlePrevPos = child.style.position || '';
        child.style.position = 'relative';
        const grip = document.createElement('div');
        grip.className = 'hle-grip';
        grip.title = 'Drag to reorder (within this column)';
        grip.textContent = '⠿';
        child.appendChild(grip);
        liveGrips.push({ child, grip });

        let dragging = false;
        function onMove(e) {
            if (!dragging) return;
            const cluster = child.parentElement;
            if (!cluster) return;
            const siblings = liveChildren(cluster).filter(function (c) { return c !== child; });
            let target = null, before = true;
            for (let i = 0; i < siblings.length; i++) {
                const r = siblings[i].getBoundingClientRect();
                const mid = r.top + r.height / 2;
                if (e.clientY < mid) { target = siblings[i]; before = true; break; }
                target = siblings[i]; before = false;
            }
            if (target) {
                cluster.insertBefore(child, before ? target : target.nextSibling);
                refreshSplitters(cluster);
            }
        }
        function onUp() {
            if (!dragging) return;
            dragging = false;
            grip.classList.remove('hle-grip-active');
            window.removeEventListener('pointermove', onMove);
            window.removeEventListener('pointerup', onUp);
            if (child.parentElement) refreshOrder(child.parentElement);
        }
        grip.addEventListener('pointerdown', function (e) {
            if (e.button !== undefined && e.button !== 0) return;
            dragging = true;
            grip.classList.add('hle-grip-active');
            e.preventDefault();
            e.stopPropagation();
            window.addEventListener('pointermove', onMove);
            window.addEventListener('pointerup', onUp, { once: true });
        });
    }

    // Swaps two panels' positions in the DOM outright, even across different clusters — the
    // classic two-pointer swap (insert each where the other used to be) handles adjacency and
    // cross-parent moves alike without a temporary placeholder node. Both clusters' splitters and
    // saved order are refreshed afterward since the set of children in each one just changed.
    function swapPanels(a, b) {
        if (!a || !b || a === b) return;
        const aParent = a.parentElement, aNext = a.nextElementSibling;
        const bParent = b.parentElement, bNext = b.nextElementSibling;
        if (!aParent || !bParent) return;
        bParent.insertBefore(a, bNext);
        aParent.insertBefore(b, aNext);
        [aParent, bParent].forEach(function (p) {
            refreshSplitters(p);
            refreshOrder(p);
        });
    }

    let pickOverlay = null;
    let pickSpotlit = null; // the panel currently poking through the overlay

    function closePicker() {
        if (pickSpotlit) {
            pickSpotlit.style.zIndex = pickSpotlit.dataset.hlePrevZ || '';
            delete pickSpotlit.dataset.hlePrevZ;
            pickSpotlit.classList.remove('hle-spotlit');
            pickSpotlit = null;
        }
        if (pickOverlay) { pickOverlay.remove(); pickOverlay = null; }
        if (picker) { picker.remove(); picker = null; }
    }

    // A full modal, not a corner popover: everything else on screen dims behind a scrim, and the
    // panel being reassigned is lifted (z-index) above that same scrim so it alone stays lit — the
    // player sees exactly which slot they're about to change while they pick its new content.
    function openPicker(forPanel) {
        closePicker();
        pickOverlay = document.createElement('div');
        pickOverlay.className = 'hle-pick-overlay';
        pickOverlay.addEventListener('click', closePicker);
        document.body.appendChild(pickOverlay);

        pickSpotlit = forPanel;
        forPanel.dataset.hlePrevZ = forPanel.style.zIndex || '';
        forPanel.style.zIndex = '100001';
        forPanel.classList.add('hle-spotlit');

        picker = document.createElement('div');
        picker._forPanel = forPanel;
        picker.className = 'hle-picker';
        PANEL_REGISTRY.forEach(function (entry) {
            const el = document.querySelector(entry.sel);
            if (!el) return;
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.textContent = entry.label;
            if (el === forPanel) btn.className = 'hle-pick-current';
            btn.addEventListener('click', function (e) {
                e.stopPropagation();
                swapPanels(forPanel, el);
                closePicker();
            });
            picker.appendChild(btn);
        });

        const sep = document.createElement('div');
        sep.className = 'hle-pick-sep';
        picker.appendChild(sep);

        const key = childKey(forPanel);
        const cur = layout.scales[key] || {};
        function addSlider(labelText, prop, initial) {
            const wrap = document.createElement('label');
            wrap.className = 'hle-pick-slider';
            const span = document.createElement('span');
            span.textContent = labelText;
            const input = document.createElement('input');
            input.type = 'range';
            input.min = '0.6';
            input.max = '2';
            input.step = '0.05';
            input.value = String(initial);
            input.addEventListener('input', function () {
                const v = parseFloat(input.value) || 1;
                if (!layout.scales[key]) layout.scales[key] = {};
                layout.scales[key][prop] = v;
                forPanel.style.setProperty('--hle-' + prop + '-scale', v);
            });
            wrap.appendChild(span);
            wrap.appendChild(input);
            picker.appendChild(wrap);
        }
        addSlider('ICON SIZE', 'icon', cur.icon || 1);
        addSlider('FONT SIZE', 'font', cur.font || 1);

        document.body.appendChild(picker);
    }

    // The whole panel is the click target (not just a tiny corner icon) — "click the container" is
    // the whole point. The `⇄` badge is just a passive hint that it's clickable (pointer-events:
    // none, see injectStyles), so it never needs its own listener or steals the click. Clicks that
    // land on the reorder grip, the resize handle, or inside an already-open picker are excluded so
    // this doesn't fight those, and so a drag-to-reorder release (which still fires a trailing
    // `click`) doesn't immediately reopen the picker on top of it.
    function addPicker(child) {
        const hint = document.createElement('div');
        hint.className = 'hle-pick';
        hint.title = 'Click to change what this slot shows';
        hint.textContent = '⇄';
        child.appendChild(hint);
        livePickers.push({ child, btn: hint });
        child.addEventListener('click', function (e) {
            if (e.target.closest('.hle-grip, .hle-splitter, .hle-picker')) return;
            if (picker && picker._forPanel === child) { closePicker(); return; }
            e.stopPropagation();
            openPicker(child);
        });
    }

    // .game-stage (the actual game canvas) is never grip-draggable or re-assignable: it's
    // sized/rendered by the game's own viewport-fit code, not something this editor should let the
    // player reorder or replace.
    function isReorderable(el) {
        return !el.classList.contains('game-stage');
    }

    function setupCluster(cluster) {
        liveChildren(cluster).filter(isReorderable).forEach(function (c) {
            addGrip(c);
            addPicker(c);
        });
        refreshSplitters(cluster);
    }

    function enterEdit() {
        if (editing || !isActive()) return;
        editing = true;
        document.documentElement.setAttribute('data-hud-edit', '1');
        CLUSTER_SELECTORS.forEach(function (sel) {
            const cluster = document.querySelector(sel);
            if (!cluster || !cluster.offsetWidth || !cluster.offsetHeight) return;
            setupCluster(cluster);
        });
        setupContainerSplitters();
        syncControls();
    }

    function exitEdit() {
        if (!editing) return;
        editing = false;
        document.documentElement.removeAttribute('data-hud-edit');
        liveGrips.forEach(function (g) {
            g.grip.remove();
            g.child.style.position = g.child.dataset.hlePrevPos || '';
            delete g.child.dataset.hlePrevPos;
        });
        liveGrips.length = 0;
        livePickers.forEach(function (p) { p.btn.remove(); });
        livePickers.length = 0;
        closePicker();
        liveSplitters.forEach(function (s) { s.remove(); });
        liveSplitters.length = 0;
        syncControls();
    }

    function toggleEdit() {
        if (editing) exitEdit(); else enterEdit();
    }

    function isEditing() {
        return editing;
    }

    function resetLayout() {
        layout = { clusters: {}, container: {}, scales: {} };
        saveLayout();
        PANEL_REGISTRY.forEach(function (entry) {
            const el = document.querySelector(entry.sel);
            if (el) { el.style.removeProperty('--hle-icon-scale'); el.style.removeProperty('--hle-font-scale'); }
        });
        CLUSTER_SELECTORS.forEach(function (sel) {
            const cluster = document.querySelector(sel);
            if (!cluster) return;
            const order = originalOrder[sel];
            if (order) {
                // Global lookup for the same reason as in applySaved: a panel the content picker
                // moved to a different cluster needs to be found there and moved back, not just
                // reordered among whichever children this cluster currently happens to have.
                order.forEach(function (k) {
                    const el = findPanelByKey(k);
                    if (el) cluster.appendChild(el);
                });
            }
            liveChildren(cluster).forEach(function (c) {
                if (c.dataset.hleSized === '1') {
                    c.style.flexBasis = '';
                    c.style.flexGrow = '';
                    c.style.flexShrink = '';
                    c.style.minHeight = '';
                    c.style.maxHeight = '';
                    c.style.boxSizing = '';
                    delete c.dataset.hleSized;
                }
            });
        });
        CONTAINER_SPLITTERS.forEach(function (cfg) {
            const el = document.querySelector(cfg.clusterSel);
            if (el && el.dataset.hleSized === '1') {
                el.style.width = '';
                delete el.dataset.hleSized;
            }
        });
        if (editing) { exitEdit(); enterEdit(); }
    }

    // SAVE/RESET/LAYOUT all live as icon keys in the bezel tool strip (see
    // js/core/viewport-fit-part3.js, data-tool="save"/"reset"/"layout"), gated to show only while
    // dev mode is on (and, for save/reset, only while actively editing). Nothing to build here.
    function save() {
        refreshAllOrders();
        saveLayout();
    }

    function syncControls() {
        if (!isActive() && editing) exitEdit();
    }

    // Shift+C in combat is handled by js/core/input-handler/core.js (boot path).
    // This mirror stays for when the editors bundle loads mid-session (HUD edit
    // sync); toggleDevMode's same-press lock prevents double flips.
    function bindGlobalToggle() {
        window.addEventListener('keydown', function (e) {
            if (!e.shiftKey || (e.key !== 'c' && e.key !== 'C')) return;
            if (e.repeat) return;
            if (typeof startScreenManager === 'undefined' || startScreenManager.visible) return;
            if (typeof homeStationUI !== 'undefined' && homeStationUI.isVisible) return;
            if (typeof profileSelectionManager !== 'undefined' && profileSelectionManager.isVisible) return;
            if (typeof onboardingManager !== 'undefined' && onboardingManager.isVisible) return;
            const tag = e.target && e.target.tagName;
            if (tag === 'INPUT' || tag === 'TEXTAREA') return;
            e.preventDefault();
            startScreenManager.toggleDevMode();
            syncControls();
        });
    }

    function injectStyles() {
        const style = document.createElement('style');
        style.textContent =
            '[data-hud-edit="1"] #gameLeftCluster > :not([data-hle-splitter]),' +
            '[data-hud-edit="1"] .game-canvas-container > :not([data-hle-splitter]),' +
            '[data-hud-edit="1"] #gameRightCluster > :not([data-hle-splitter])' +
            '{outline:1px dashed #5fd0ff;outline-offset:-1px;cursor:pointer;}' +
            '.hle-splitter{flex:0 0 8px;margin:2px 0;cursor:ns-resize;background:repeating-linear-gradient(90deg,#5fd0ff 0 6px,transparent 6px 12px);opacity:0.6;border-radius:2px;}' +
            '.hle-splitter:hover{opacity:1;}' +
            '.hle-vsplitter{flex:0 0 8px;margin:0 2px;cursor:ew-resize;background:repeating-linear-gradient(180deg,#ffb15f 0 6px,transparent 6px 12px);opacity:0.6;border-radius:2px;}' +
            '.hle-vsplitter:hover{opacity:1;}' +
            '.hle-grip{position:absolute;bottom:2px;right:2px;width:16px;height:16px;line-height:16px;text-align:center;' +
            'background:#0b2436;color:#aee6ff;font:12px monospace;border-radius:2px;cursor:grab;user-select:none;z-index:10000;}' +
            '.hle-grip-active{cursor:grabbing;background:#1e5278;}' +
            '.hle-pick{position:absolute;top:2px;right:2px;width:16px;height:16px;line-height:16px;text-align:center;' +
            'background:#0b2436;color:#ffd79a;font:12px monospace;border-radius:2px;user-select:none;z-index:10000;pointer-events:none;}' +
            '.hle-pick-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:100000;}' +
            '.hle-spotlit{position:relative;box-shadow:0 0 0 2px #ffd79a,0 0 28px 6px rgba(0,0,0,0.6);}' +
            '.hle-picker{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:100002;' +
            'background:#0f141c;border:1px solid #3a4a60;border-radius:6px;' +
            'padding:4px;display:flex;flex-direction:column;gap:2px;font:12px/1.4 monospace;min-width:180px;}' +
            '.hle-picker button{background:#141821;color:#cfe8ff;border:1px solid transparent;border-radius:4px;' +
            'padding:6px 10px;cursor:pointer;text-align:left;}' +
            '.hle-picker button:hover{background:#1e2733;}' +
            '.hle-picker button.hle-pick-current{border-color:#ffd79a;color:#fff;}' +
            '.hle-pick-sep{height:1px;background:#3a4a60;margin:4px 2px;}' +
            '.hle-pick-slider{display:flex;flex-direction:column;gap:4px;padding:4px 8px;color:#9fb4c8;' +
            'letter-spacing:0.06em;font-size:11px;}' +
            '.hle-pick-slider input[type=range]{width:100%;accent-color:#ffd79a;}';
        document.head.appendChild(style);
    }

    function captureOriginalOrder() {
        CLUSTER_SELECTORS.forEach(function (sel) {
            const cluster = document.querySelector(sel);
            if (cluster) originalOrder[sel] = liveChildren(cluster).map(childKey);
        });
    }

    // Lets .gi-loadout-side / .gi-mission-side switch their rows from icon-left to icon-on-top
    // once the player has actually resized them tall enough (see the `.gi-roomy` rules in
    // css/styles/part-02.css). This used to be a CSS container query, but that silently does
    // nothing on an engine without `@container` size-containment support, leaving the icons stuck
    // left with no visible failure; a ResizeObserver gets the same result and is universally
    // supported, so there's no silent-failure mode to debug around.
    const ROOMY_MIN_H = 240;
    function watchRoomyPanels() {
        if (typeof ResizeObserver === 'undefined') return;
        const targets = Array.prototype.filter.call(
            document.querySelectorAll('.gi-loadout-side, .gi-mission-side'),
            function (el) { return el.nodeType === 1; }
        );
        if (!targets.length) return;
        const ro = new ResizeObserver(function (entries) {
            entries.forEach(function (entry) {
                const h = entry.contentRect ? entry.contentRect.height : entry.target.getBoundingClientRect().height;
                entry.target.classList.toggle('gi-roomy', h >= ROOMY_MIN_H);
            });
        });
        targets.forEach(function (el) { ro.observe(el); });
    }

    function init() {
        injectStyles();
        captureOriginalOrder();
        applySaved();
        bindGlobalToggle();
        watchRoomyPanels();
        syncControls();
        setInterval(syncControls, 1000);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init, { once: true });
    } else {
        init();
    }

    return { enterEdit, exitEdit, toggleEdit, resetLayout, isActive, isEditing, save };
})();

window.hudLayoutEditor = hudLayoutEditor;


/* --- js/ui/component-editor/procedural-generate.js --- */
"use strict";

// ComponentEditorUI: seeded procedural sprite generator + grid quantiser (global Pixel Size friendly:
// 1 grid cell == 1 sprite pixel, so the editor shows it at the global pixel size).
extendClass(ComponentEditorUI, {
    /** Small deterministic PRNG (mulberry32). */
    _procRng(seed) {
        let a = (Number(seed) || 0) >>> 0;
        return () => {
            a = (a + 0x6D2B79F5) >>> 0;
            let t = a;
            t = Math.imul(t ^ (t >>> 15), t | 1);
            t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    },

    /** Build a symmetric blob grid of shade indices (0 = empty). */
    buildProceduralGrid(size, seed, shades) {
        const rnd = this._procRng(seed);
        const half = Math.ceil(size / 2);
        const g = [];
        for (let y = 0; y < size; y++) g.push(new Array(size).fill(0));
        const cy = (size - 1) / 2;
        // Random-walk blobs seeded on the centre column, grown to the left half, then mirrored.
        const blobs = 2 + Math.floor(rnd() * 3);
        for (let b = 0; b < blobs; b++) {
            const bx = half - 1 - Math.floor(rnd() * half * 0.5);
            const by = Math.round(cy + (rnd() - 0.5) * size * 0.5);
            const r = size * (0.12 + rnd() * 0.2);
            for (let y = 0; y < size; y++) {
                for (let x = 0; x < half; x++) {
                    const dx = (x - bx) / (r * (0.8 + rnd() * 0.4));
                    const dy = (y - by) / (r * (1 + rnd() * 0.5));
                    if (dx * dx + dy * dy <= 1) g[y][x] = 1;
                }
            }
        }
        for (let y = 0; y < size; y++) for (let x = 0; x < half; x++) g[y][size - 1 - x] = g[y][x];
        // Shade: dark rim, lighter towards the middle, light noise.
        const out = g.map((row) => row.slice());
        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                if (!g[y][x]) continue;
                const edge = !(g[y - 1] && g[y - 1][x]) || !(g[y + 1] && g[y + 1][x]) || !g[y][x - 1] || !g[y][x + 1];
                let t = edge ? 0 : 0.35 + 0.65 * (1 - Math.abs(x - (size - 1) / 2) / half) + (rnd() - 0.5) * 0.25;
                t = Math.max(0, Math.min(0.999, t));
                out[y][x] = shades[Math.floor(t * shades.length)];
            }
        }
        return out;
    },

    onProceduralGenerate() {
        const entry = this.currentEntry();
        if (!entry || this.busy) return;
        this.readGenFields();
        const size = this.outSize || entry.size || 16;
        this.reloadEditBuffer(true);
        if (!this._editCanvas) return;
        const seed = this.seed !== "" && Number.isFinite(Number(this.seed))
            ? Number(this.seed) : Math.floor(Math.random() * 1e9);
        const grid = this.buildProceduralGrid(size, seed, this.getPaletteShades());
        const ctx = this._editCanvas.getContext("2d");
        ctx.clearRect(0, 0, size, size);
        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                if (!grid[y][x]) continue;
                const v = this.shadeToGray(grid[y][x]);
                ctx.fillStyle = "rgb(" + v + "," + v + "," + v + ")";
                ctx.fillRect(x, y, 1, 1);
            }
        }
        this._pixelDirty = true;
        this.setStatus("Procedural · seed " + seed);
        this.drawCenter();
    },

    /** Downscale any image/canvas onto a size×size grid in the palette grays (nearest sampling). */
    quantizeToGrid(src, size) {
        const c = document.createElement("canvas");
        c.width = c.height = size;
        const ctx = c.getContext("2d");
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(src, 0, 0, size, size);
        return c;
    }
});


/* --- js/ui/content-viewer-stat-range.js --- */
"use strict";

/**
 * Shared by the weapon/ability/defense/energy library viewers: every equippable item's stats
 * are not fixed — they scale across the category's MODULES upgrade tracks (economyConfig
 * .moduleUpgradeDefs), so a flat number in the wiki would be wrong the moment the player
 * upgrades anything. This lists each track's own label/description — the real upgrade system,
 * not invented numbers — as "stat rows" so every item's page reads "this varies, upgradeable
 * via these tracks" instead of implying a fixed value.
 */
function contentViewerUpgradeRangeRowsHtml(category) {
    if (typeof economyConfig === 'undefined' || !economyConfig.moduleUpgradeDefs) return '';
    const tracks = economyConfig.moduleUpgradeDefs[category];
    if (!tracks) return '';
    return Object.keys(tracks).map((track) => {
        const meta = tracks[track];
        return `<div class="stat-row"><span class="stat-label">Range: ${meta.label}</span>` +
            `<span class="stat-value">${meta.desc} · L0–L${meta.maxLevel}</span></div>`;
    }).join('');
}


/* --- js/ui/energy-viewer/core.js --- */
"use strict";

/**
 * Energy Systems Viewer — browse energy-core modules (the ship's power plant).
 * Open: Start menu → ENERGY SYSTEMS
 */
var EnergyViewerUI = class EnergyViewerUI {
    constructor() {
        this.visible = false;
        this.selectedIndex = 0;
        this.items = [];
        this.overlay = null;
        this.previewCanvas = null;
        this.previewCtx = null;
        this.previewAnimId = null;
        this.previewZoom = 1;
        this.previewFullscreen = false;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewPanning = false;
        this.previewPanLastX = 0;
        this.previewPanLastY = 0;
        this.previewSim = null;
        this.previewLastTs = 0;
        this._keyHandler = (e) => this.handleKeyDown(e);
    }

    getEnergyList() {
        if (typeof abilityConfigManager === 'undefined' || typeof shipLoadoutManager === 'undefined') return [];
        const list = [];
        const grouped = abilityConfigManager.getIdsByCluster();
        // Energy modules sit in the 'core' cluster alongside Flight Assist / Weapon Systems —
        // isEnergyId is what actually marks an id as an energy-slot module (today: energy_core).
        const ids = (grouped.core || []).filter((id) => shipLoadoutManager.isEnergyId(id));
        const devMode = typeof startScreenManager !== 'undefined' && startScreenManager.devMode;
        const allowed = {};
        if (!devMode && typeof profileManager !== 'undefined' && profileManager.hasActiveProfile()) {
            profileManager.getDiscovered('energy').forEach((id) => { allowed[id] = true; });
        }
        const filterDiscovery = !devMode && typeof profileManager !== 'undefined' && profileManager.hasActiveProfile();
        ids.forEach((id) => {
            if (filterDiscovery && !allowed[id]) return;
            const a = abilityConfigManager.getAbility(id);
            list.push({
                id: a.id,
                name: a.name,
                description: a.description,
                icon: a.icon,
                mountSprite: a.mountSprite,
                cluster: a.cluster,
                clusterLabel: abilityConfigManager.getClusterLabel(a.cluster),
                type: a.type,
                tier: a.tier,
                uiDescription: a.uiDescription,
                custom: !!a.custom
            });
        });
        return list;
    }

    show(options) {
        if (options && Object.prototype.hasOwnProperty.call(options, 'onClose')) {
            this.onClose = options.onClose;
        }
        this.items = this.getEnergyList();
        if (!this.items.length) return;
        const preferId = options && options.energyId;
        if (preferId) {
            const idx = this.items.findIndex((a) => a.id === preferId);
            if (idx >= 0) this.selectedIndex = idx;
        }
        this.selectedIndex = Math.max(0, Math.min(this.selectedIndex, this.items.length - 1));
        this.visible = true;
        this.createUI();
        document.addEventListener('keydown', this._keyHandler);
        if (!(options && options.skipPersist) && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('energy-viewer', {
                energyId: this.items[this.selectedIndex].id
            });
        }
    }

    hide() {
        this.visible = false;
        this.stopPreview();
        this.cleanupPreviewControls();
        this.setPreviewFullscreen(false);
        document.removeEventListener('keydown', this._keyHandler);
        if (this._panelResize) {
            this._panelResize.destroy();
            this._panelResize = null;
        }
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
        this.previewCanvas = null;
        this.previewCtx = null;
        this.previewSim = null;
    }

    themeColor() {
        if (typeof iconRenderer !== 'undefined' && iconRenderer.getThemeTint) {
            return iconRenderer.getThemeTint() || '#ffd24a';
        }
        return '#ffd24a';
    }

    createUI() {
        if (this._panelResize) {
            this._panelResize.destroy();
            this._panelResize = null;
        }
        if (this.overlay) this.overlay.remove();

        this.overlay = document.createElement('div');
        this.overlay.className = 'content-viewer-overlay';
        this.overlay.innerHTML = `
            <div class="content-viewer-panel">
                <h2 class="content-viewer-title">ENERGY SYSTEMS</h2>
                <div class="content-viewer-body has-preview" id="evViewerBody">
                    <aside class="content-viewer-list" id="evList"></aside>
                    <div class="pe-resize-handle" data-resize="left" title="Resize energy list"></div>
                    <div class="content-viewer-detail" id="evDetail"></div>
                    <div class="pe-resize-handle" data-resize="right" title="Resize preview"></div>
                    <aside class="content-viewer-preview planet-editor-preview-wrap" id="evPreviewWrap">
                        <div class="pe-preview-toolbar">
                            <button type="button" class="pe-btn pe-preview-btn" id="evZoomOut" title="Zoom out">−</button>
                            <span class="pe-zoom-label" id="evZoomLabel">100%</span>
                            <button type="button" class="pe-btn pe-preview-btn" id="evZoomIn" title="Zoom in">+</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="evZoomReset" title="Reset zoom">1:1</button>
                            <button type="button" class="pe-btn pe-preview-btn" id="evPreviewFullscreen" title="Fullscreen">FULL</button>
                        </div>
                        <div class="pe-preview-viewport" id="evPreviewViewport">
                            <canvas id="evPreview" width="200" height="300"></canvas>
                        </div>
                        <div class="pe-preview-label">PREVIEW</div>
                    </aside>
                </div>
                <div class="content-viewer-footer">
                    <button type="button" class="pe-btn pe-primary" id="evEdit">EDIT</button>
                    <button type="button" class="pe-btn" id="evEditGfx">EDIT GFX</button>
                    <button type="button" class="pe-btn" id="evClose">CLOSE</button>
                </div>
                <div class="content-viewer-hint">↑↓ Navigate • E Edit • ESC Close</div>
            </div>
        `;
        document.body.appendChild(this.overlay);
        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }

        this.bindPreviewControls();
        this.setupPanelResize();
        this.renderList();
        this.renderDetail();
        this.resetPreviewSim();
        this.startPreview();

        this.overlay.querySelector('#evEdit').addEventListener('click', () => this.openEditor());
        this.overlay.querySelector('#evEditGfx').addEventListener('click', () => this.openGfxEditor());
        this.overlay.querySelector('#evClose').addEventListener('click', () => this.close());
        this.mountDevToggles();
    }

    mountDevToggles() {
        this._devToggles = null;
        if (typeof devProfileToggles === 'undefined' || !devProfileToggles.active()) return;
        const footer = this.overlay.querySelector('.content-viewer-footer');
        const hint = this.overlay.querySelector('.content-viewer-hint');
        this._devToggles = devProfileToggles.mount(footer, hint, {
            known: () => {
                const a = this.items[this.selectedIndex];
                return !!(a && profileManager.isDiscovered('energy', a.id));
            },
            toggleKnown: () => {
                const a = this.items[this.selectedIndex];
                if (a) profileManager.toggleDiscovered('energy', a.id);
            },
            owned: () => {
                const a = this.items[this.selectedIndex];
                return !!(a && profileManager.getPartCount('energy', a.id) > 0);
            },
            toggleOwned: () => {
                const a = this.items[this.selectedIndex];
                if (a) profileManager.togglePartOwned('energy', a.id);
            },
            onChange: () => {
                this.renderList();
                this.renderDetail();
                if (this._devToggles) this._devToggles.refresh();
            }
        });
    }

    setupPanelResize() {
        const body = this.overlay && this.overlay.querySelector('#evViewerBody');
        if (!body || typeof setupPanelResize !== 'function') return;
        this._panelResize = setupPanelResize({
            body,
            root: this.overlay,
            storageKey: 'evPanelWidths',
            defaults: { left: 240, right: 260 },
            mins: { left: 140, right: 180, center: 200 },
            leftVar: '--cv-left-w',
            rightVar: '--cv-right-w',
            onChange: () => {
                if (this.visible) this.applyPreviewView();
            }
        });
    }

    bindPreviewControls() {
        const overlay = this.overlay;
        this.previewCanvas = overlay.querySelector('#evPreview');
        this.previewCtx = this.previewCanvas.getContext('2d');
        this.previewZoom = 1;
        this.previewPanX = 0;
        this.previewPanY = 0;
        this.previewFullscreen = false;

        overlay.querySelector('#evZoomOut').addEventListener('click', () => this.setPreviewZoom(this.previewZoom - 0.25));
        overlay.querySelector('#evZoomIn').addEventListener('click', () => this.setPreviewZoom(this.previewZoom + 0.25));
        overlay.querySelector('#evZoomReset').addEventListener('click', () => {
            this.previewPanX = 0;
            this.previewPanY = 0;
            this.setPreviewZoom(1);
        });
        overlay.querySelector('#evPreviewFullscreen').addEventListener('click', () => {
            this.setPreviewFullscreen(!this.previewFullscreen);
        });

        const viewport = overlay.querySelector('#evPreviewViewport');
        viewport.addEventListener('wheel', (e) => {
            e.preventDefault();
            this.setPreviewZoom(this.previewZoom + (e.deltaY < 0 ? 0.1 : -0.1));
        }, { passive: false });
        viewport.addEventListener('contextmenu', (e) => e.preventDefault());
        viewport.addEventListener('mousedown', (e) => {
            if (e.button !== 2) return;
            e.preventDefault();
            this.previewPanning = true;
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            viewport.classList.add('pe-panning');
        });
        const onMove = (e) => {
            if (!this.previewPanning || !this.visible) return;
            this.previewPanX += e.clientX - this.previewPanLastX;
            this.previewPanY += e.clientY - this.previewPanLastY;
            this.previewPanLastX = e.clientX;
            this.previewPanLastY = e.clientY;
            this.applyPreviewView();
        };
        const endPan = () => {
            if (!this.previewPanning) return;
            this.previewPanning = false;
            const vp = this.overlay && this.overlay.querySelector('#evPreviewViewport');
            if (vp) vp.classList.remove('pe-panning');
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', endPan);
        this._previewCleanup = () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', endPan);
        };
        this.applyPreviewView();
        requestAnimationFrame(() => this.applyPreviewView());
    }

    setPreviewZoom(zoom) {
        this.previewZoom = Math.min(3, Math.max(0.5, Math.round(zoom * 100) / 100));
        this.applyPreviewView();
    }

    setPreviewFullscreen(on) {
        this.previewFullscreen = !!on;
        requestAnimationFrame(() => this.applyPreviewView());
    }
}


/* --- js/ui/energy-viewer/apply-preview-view.js --- */
"use strict";

// EnergyViewerUI methods, split from energy-viewer.js.
extendClass(EnergyViewerUI, {
    applyPreviewView() {
        const wrap = this.overlay && this.overlay.querySelector('#evPreviewWrap');
        const label = this.overlay && this.overlay.querySelector('#evZoomLabel');
        const fsBtn = this.overlay && this.overlay.querySelector('#evPreviewFullscreen');
        const viewport = this.overlay && this.overlay.querySelector('#evPreviewViewport');
        if (wrap) wrap.classList.toggle('pe-preview-fs', this.previewFullscreen);
        if (label) label.textContent = `${Math.round(this.previewZoom * 100)}%`;
        if (fsBtn) fsBtn.textContent = this.previewFullscreen ? 'EXIT' : 'FULL';
        if (this.previewCanvas && viewport) {
            const pad = 8;
            const availW = Math.max(140, viewport.clientWidth - pad);
            const availH = Math.max(200, viewport.clientHeight - pad);
            const aspect = this.previewCanvas.width / this.previewCanvas.height || (2 / 3);
            let fitW = availW;
            let fitH = fitW / aspect;
            if (fitH > availH) {
                fitH = availH;
                fitW = fitH * aspect;
            }
            this.previewCanvas.style.width = `${Math.round(fitW)}px`;
            this.previewCanvas.style.height = `${Math.round(fitH)}px`;
            this.previewCanvas.style.transform =
                `translate(${this.previewPanX}px, ${this.previewPanY}px) scale(${this.previewZoom})`;
        }
    },

    startPreview() {
        this.stopPreview();
        this.previewLastTs = 0;
        if (!this.previewSim) this.resetPreviewSim();
        const loop = () => {
            if (!this.visible) return;
            this.drawPreview();
            this.previewAnimId = requestAnimationFrame(loop);
        };
        this.previewAnimId = requestAnimationFrame(loop);
    },

    stopPreview() {
        if (this.previewAnimId) {
            cancelAnimationFrame(this.previewAnimId);
            this.previewAnimId = null;
        }
        this.previewLastTs = 0;
    },

    cleanupPreviewControls() {
        if (this._previewCleanup) {
            this._previewCleanup();
            this._previewCleanup = null;
        }
    },

    resetPreviewSim() {
        this.previewSim = { phase: 0, pulse: 0 };
        this.previewLastTs = 0;
    },

    updatePreviewSim(dtMs) {
        const sim = this.previewSim;
        if (!sim) return;
        sim.phase += dtMs * 0.003;
        sim.pulse = 0.5 + Math.sin(sim.phase * 3) * 0.5;
    },

    drawPreview() {
        const canvas = this.previewCanvas;
        const ctx = this.previewCtx;
        const item = this.items[this.selectedIndex];
        if (!canvas || !ctx || !item) return;
        canvas.setAttribute('data-ag-type', 'ability');
        canvas.setAttribute('data-ag-id', item.id);
        if (item.mountSprite) canvas.setAttribute('data-ag-key', item.mountSprite);
        else if (item.icon) canvas.setAttribute('data-ag-key', item.icon);
        else canvas.setAttribute('data-ag-key', item.id);

        const now = performance.now();
        const dt = this.previewLastTs ? Math.min(48, now - this.previewLastTs) : 16;
        this.previewLastTs = now;
        if (!this.previewSim) this.resetPreviewSim();
        this.updatePreviewSim(dt);

        const w = canvas.width;
        const h = canvas.height;
        const sim = this.previewSim;
        const tint = this.themeColor();
        const cx = w / 2;
        const cy = 150;

        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, w, h);

        ctx.fillStyle = 'rgba(200, 180, 140, 0.28)';
        for (let i = 0; i < 32; i++) {
            const sx = (i * 91) % w;
            const sy = (i * 57 + Math.floor(sim.phase * 16)) % h;
            ctx.fillRect(sx, sy, 2, 2);
        }

        // Power-core pulse: a few expanding rings instead of the shield/armor hit sim the other
        // viewers use — this item isn't absorbing hits, it's radiating power to the rest of the ship.
        for (let r = 0; r < 3; r++) {
            const ringPhase = (sim.phase * 1.2 + r / 3) % 1;
            ctx.strokeStyle = tint;
            ctx.globalAlpha = Math.max(0, 0.5 - ringPhase * 0.5);
            ctx.beginPath();
            ctx.arc(cx, cy, 14 + ringPhase * 34, 0, Math.PI * 2);
            ctx.stroke();
        }
        ctx.globalAlpha = 1;

        if (typeof iconRenderer !== 'undefined' && item.icon) {
            const tmp = document.createElement('canvas');
            tmp.width = 40;
            tmp.height = 40;
            iconRenderer.drawToCanvas(tmp, item.icon, tint);
            ctx.globalAlpha = 0.75 + sim.pulse * 0.25;
            ctx.drawImage(tmp, cx - 20, cy - 20, 40, 40);
            ctx.globalAlpha = 1;
        }

        ctx.fillStyle = tint;
        ctx.font = '10px "Courier New", monospace';
        ctx.textAlign = 'center';
        ctx.fillText(String(item.name || item.id).toUpperCase(), w / 2, h - 34);
        ctx.font = '9px "Courier New", monospace';
        ctx.globalAlpha = 0.75;
        ctx.fillText(`TIER ${item.tier}  ${String(item.type || '').toUpperCase()}`, w / 2, h - 20);
        ctx.fillText(item.uiDescription || 'ENERGY', w / 2, h - 8);
        ctx.globalAlpha = 1;
    },

    iconHtml(icon, size, tipLabel) {
        if (typeof abilityConfigManager !== 'undefined') {
            return abilityConfigManager.resolveIconHtml(icon, size || 16, 'cv-ability-icon-img', tipLabel);
        }
        return icon || '◆';
    },

    renderList() {
        const list = this.overlay && this.overlay.querySelector('#evList');
        if (!list) return;
        list.innerHTML = '';
        this.items.forEach((item, index) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'content-viewer-item' + (index === this.selectedIndex ? ' selected' : '');
            btn.innerHTML =
                `<span class="cv-ability-icon cv-list-ability-icon">${this.iconHtml(item.icon, 16, item.name)}</span>` +
                `<span class="cv-item-label">${item.name}${item.custom ? ' *' : ''}` +
                (typeof devProfileToggles !== 'undefined' && devProfileToggles.active()
                    ? devProfileToggles.badgesHtml({
                        known: profileManager.isDiscovered('energy', item.id),
                        owned: profileManager.getPartCount('energy', item.id) > 0
                    })
                    : '') +
                `</span>`;
            btn.addEventListener('click', () => {
                this.selectedIndex = index;
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
                this.persist();
            });
            list.appendChild(btn);
        });
        const selected = list.querySelector('.content-viewer-item.selected');
        if (selected) selected.scrollIntoView({ block: 'nearest', behavior: 'auto' });
    },
});


/* --- js/ui/energy-viewer/render-detail.js --- */
"use strict";

// EnergyViewerUI methods, split from energy-viewer.js.
extendClass(EnergyViewerUI, {
    renderDetail() {
        const root = this.overlay && this.overlay.querySelector('#evDetail');
        const a = this.items[this.selectedIndex];
        if (!root || !a) return;
        root.innerHTML = `
            <div class="content-viewer-hero">
                <div class="cv-ability-hero-icon">${this.iconHtml(a.icon, 48, a.name)}</div>
                <div>
                    <h3 class="content-viewer-name">${a.name}</h3>
                    <p class="content-viewer-desc">${a.description || 'No description.'}</p>
                </div>
            </div>
            <div class="content-viewer-stats">
                <div class="stat-row"><span class="stat-label">System</span><span class="stat-value">ENERGY</span></div>
                <div class="stat-row"><span class="stat-label">Type</span><span class="stat-value">${String(a.type || '—').toUpperCase()}</span></div>
                <div class="stat-row"><span class="stat-label">Tier</span><span class="stat-value">${a.tier}</span></div>
                <div class="stat-row"><span class="stat-label">ID</span><span class="stat-value">${a.id}</span></div>
                <div class="stat-row"><span class="stat-label">Summary</span><span class="stat-value">${a.uiDescription || '—'}</span></div>
                ${contentViewerUpgradeRangeRowsHtml('energy')}
            </div>
        `;
        if (this._devToggles) this._devToggles.refresh();
    },

    persist() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            const a = this.items[this.selectedIndex];
            menuStateManager.setScreen('energy-viewer', { energyId: a ? a.id : 'energy_core' });
        }
    },

    handleKeyDown(e) {
        if (!this.visible) return;
        if (this._devToggles && this._devToggles.handleKey(e)) return;
        if (e.key === 'Escape' && this.previewFullscreen) {
            e.preventDefault();
            this.setPreviewFullscreen(false);
            return;
        }
        switch (e.key) {
            case 'ArrowUp':
            case 'ArrowLeft':
                e.preventDefault();
                this.selectedIndex = Math.max(0, this.selectedIndex - 1);
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
                this.persist();
                break;
            case 'ArrowDown':
            case 'ArrowRight':
                e.preventDefault();
                this.selectedIndex = Math.min(this.items.length - 1, this.selectedIndex + 1);
                this.renderList();
                this.renderDetail();
                this.resetPreviewSim();
                this.persist();
                break;
            case 'e':
            case 'E':
            case 'Enter':
                e.preventDefault();
                this.openEditor();
                break;
            case 'Escape':
                e.preventDefault();
                this.close();
                break;
        }
    },

    openEditor() {
        const item = this.items[this.selectedIndex];
        if (!item || typeof abilityEditorUI === 'undefined') return;
        this.hide();
        abilityEditorUI.show(item.id, false, { returnTo: 'energy-viewer' });
    },

    openGfxEditor() {
        const item = this.items[this.selectedIndex];
        if (!item || typeof componentEditorUI === 'undefined') return;
        let type = 'mount';
        let id = item.mountSprite || ('mount_' + item.id);
        if (typeof assetGenRegistry !== 'undefined' && assetGenRegistry.findByKey) {
            const hit = assetGenRegistry.findByKey(id) || assetGenRegistry.get('ability', item.id);
            if (hit) {
                type = hit.type;
                id = hit.id;
            }
        }
        const returnCb = this.onClose;
        this.hide();
        componentEditorUI.open({
            type: type,
            id: id,
            returnTo: 'energy-viewer',
            onClose: () => {
                this.show({ onClose: returnCb });
            }
        });
    },

    close() {
        this.hide();
        const container = document.querySelector('.game-container');
        const inGame = container && container.style.display !== 'none';
        if (inGame) {
            if (typeof menuStateManager !== 'undefined') menuStateManager.setScreen('ingame');
            return;
        }
        if (this.onClose) {
            const cb = this.onClose;
            this.onClose = null;
            cb();
            return;
        }
        if (typeof homeStationUI !== 'undefined') {
            homeStationUI.show({
                tab: 'explorations',
                focusExplore: 'energy',
                onClose: () => {
                    if (typeof startScreenManager !== 'undefined') startScreenManager.show();
                }
            });
        } else if (typeof startScreenManager !== 'undefined') {
            startScreenManager.show();
        } else if (typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('start');
        }
    },
});


